// Meanings for the Bhagavad Gītā — shown by the "Meaning" button on each verse.
// Written fresh in plain words (English, Telugu, Hindi). Key = the verse's key in the app: gita_ch<C>_v<N>.
window.MEANINGS = Object.assign(window.MEANINGS || {}, {

// ── Chapter 1 · Arjuna Viṣāda Yoga ──
"gita_ch1_v1": {
  en: "Dhṛtarāṣṭra said: Sañjaya, on the holy field of Kurukṣetra, the field of dharma, my sons and the sons of Pāṇḍu gathered together, eager to fight — what did they do?",
  te: "ధృతరాష్ట్రుడు అన్నాడు: సంజయా! ధర్మక్షేత్రమైన కురుక్షేత్రంలో యుద్ధం చేయాలనే కోరికతో చేరిన నా కుమారులు, పాండవులు ఏం చేశారు?",
  hi: "धृतराष्ट्र ने कहा: हे संजय! धर्मभूमि कुरुक्षेत्र में युद्ध की इच्छा से इकट्ठे हुए मेरे पुत्रों और पांडु के पुत्रों ने क्या किया?"
},
"gita_ch1_v2": {
  en: "Sañjaya said: Seeing the Pāṇḍava army drawn up in battle formation, King Duryodhana went to his teacher Droṇa and spoke these words:",
  te: "సంజయుడు అన్నాడు: వ్యూహంగా నిలిచిన పాండవ సైన్యాన్ని చూసి, రాజు దుర్యోధనుడు అప్పుడు తన గురువు ద్రోణాచార్యుని దగ్గరకు వెళ్ళి ఇలా అన్నాడు:",
  hi: "संजय ने कहा: व्यूह में खड़ी पांडवों की सेना को देखकर राजा दुर्योधन अपने आचार्य द्रोण के पास गया और यह बात कही:"
},
"gita_ch1_v3": {
  en: "Duryodhana said: Teacher, look at this mighty army of the sons of Pāṇḍu, arranged for battle by your own clever pupil, the son of Drupada.",
  te: "దుర్యోధనుడు అన్నాడు: ఆచార్యా! మీ తెలివైన శిష్యుడు, ద్రుపదుని కుమారుడు వ్యూహంగా నిలబెట్టిన పాండవుల ఈ మహాసైన్యాన్ని చూడండి.",
  hi: "दुर्योधन ने कहा: हे आचार्य! आपके ही बुद्धिमान शिष्य, द्रुपद-पुत्र द्वारा व्यूह में सजाई गई पांडवों की इस विशाल सेना को देखिए।"
},
"gita_ch1_v4": {
  en: "Here are heroes and great archers, equal in battle to Bhīma and Arjuna — Yuyudhāna, Virāṭa and the great chariot-warrior Drupada —",
  te: "ఇక్కడ యుద్ధంలో భీమార్జునులతో సమానమైన శూరులు, గొప్ప విలుకాండ్రు ఉన్నారు — యుయుధానుడు, విరాటుడు, మహారథుడైన ద్రుపదుడు —",
  hi: "यहाँ युद्ध में भीम और अर्जुन के समान बड़े-बड़े धनुर्धर वीर हैं — युयुधान, विराट और महारथी द्रुपद —"
},
"gita_ch1_v5": {
  en: "— Dhṛṣṭaketu, Cekitāna and the valiant king of Kāśī; Purujit, Kuntibhoja and Śaibya, the finest of men —",
  te: "— ధృష్టకేతువు, చేకితానుడు, పరాక్రమవంతుడైన కాశీరాజు; పురుజిత్తు, కుంతిభోజుడు, నరశ్రేష్ఠుడైన శైబ్యుడు —",
  hi: "— धृष्टकेतु, चेकितान और पराक्रमी काशीराज; पुरुजित, कुंतिभोज और नरश्रेष्ठ शैब्य —"
},
"gita_ch1_v6": {
  en: "— the bold Yudhāmanyu and the mighty Uttamaujā, the son of Subhadrā and the sons of Draupadī — all of them great chariot-warriors.",
  te: "— పరాక్రమశాలి యుధామన్యుడు, బలవంతుడైన ఉత్తమౌజుడు, సుభద్ర కుమారుడు (అభిమన్యుడు), ద్రౌపది కుమారులు — వీరందరూ మహారథులే.",
  hi: "— पराक्रमी युधामन्यु और बलवान उत्तमौजा, सुभद्रा का पुत्र (अभिमन्यु) और द्रौपदी के पुत्र — ये सभी महारथी हैं।"
},
"gita_ch1_v7": {
  en: "Now hear, best of the twice-born, about the most distinguished ones on our side, the leaders of my army. I name them for you.",
  te: "ద్విజోత్తమా! మన పక్షంలో ఉన్న ప్రముఖులను, నా సైన్యానికి నాయకులను కూడా తెలుసుకోండి. మీకు గుర్తు చేయడానికి వారి పేర్లు చెబుతాను.",
  hi: "हे द्विजश्रेष्ठ! हमारी ओर के जो प्रमुख योद्धा और मेरी सेना के नायक हैं, उन्हें भी जान लीजिए। आपकी जानकारी के लिए मैं उनके नाम बताता हूँ।"
},
"gita_ch1_v8": {
  en: "Yourself, Bhīṣma, Karṇa and Kṛpa, who always wins in battle; Aśvatthāmā, Vikarṇa, and the son of Somadatta as well.",
  te: "మీరు, భీష్ముడు, కర్ణుడు, యుద్ధంలో ఎప్పుడూ గెలిచే కృపాచార్యుడు; అశ్వత్థామ, వికర్ణుడు, సోమదత్తుని కుమారుడు (భూరిశ్రవుడు).",
  hi: "आप स्वयं, भीष्म, कर्ण और युद्ध में सदा विजयी कृपाचार्य; अश्वत्थामा, विकर्ण और सोमदत्त का पुत्र (भूरिश्रवा) भी।"
},
"gita_ch1_v9": {
  en: "And there are many other heroes ready to give their lives for my sake, armed with many kinds of weapons, all skilled in war.",
  te: "ఇంకా నా కోసం ప్రాణాలు ఇవ్వడానికి సిద్ధంగా ఉన్న ఎంతో మంది వీరులు ఉన్నారు; వారు రకరకాల ఆయుధాలు ధరించినవారు, అందరూ యుద్ధంలో నేర్పరులు.",
  hi: "और भी बहुत-से वीर हैं जो मेरे लिए प्राण देने को तैयार हैं; वे अनेक प्रकार के शस्त्र लिए हुए हैं और सभी युद्ध में निपुण हैं।"
},
"gita_ch1_v10": {
  en: "Our army, guarded by Bhīṣma, is beyond measure; their army, guarded by Bhīma, is limited. (The word can also be read the other way round: ours seems not enough, theirs seems enough.)",
  te: "భీష్ముడు రక్షిస్తున్న మన సైన్యం అపారమైనది; భీముడు రక్షిస్తున్న వారి సైన్యం పరిమితమైనది. (ఈ మాటను మరో విధంగా కూడా చదవవచ్చు: మన బలం చాలదు, వారి బలం చాలు.)",
  hi: "भीष्म द्वारा रक्षित हमारी सेना अपार है; भीम द्वारा रक्षित उनकी सेना सीमित है। (इस शब्द को उलटे अर्थ में भी पढ़ा जाता है: हमारा बल अपर्याप्त, उनका पर्याप्त लगता है।)"
},
"gita_ch1_v11": {
  en: "So all of you, holding your positions at every entry point of the formation, must above all protect Bhīṣma.",
  te: "కాబట్టి మీరందరూ వ్యూహంలోని అన్ని ద్వారాల దగ్గర మీ మీ స్థానాల్లో నిలబడి, అన్నిటికంటే ముందు భీష్ముణ్ణే కాపాడాలి.",
  hi: "इसलिए आप सब व्यूह के सभी मोर्चों पर अपने-अपने स्थान पर डटे रहकर, सबसे पहले भीष्म की ही रक्षा करें।"
},
"gita_ch1_v12": {
  en: "Sañjaya said: Then, to cheer Duryodhana, the mighty Bhīṣma, the grandsire and eldest of the Kurus, roared like a lion and blew his conch loudly.",
  te: "సంజయుడు అన్నాడు: అప్పుడు దుర్యోధనునికి ఉత్సాహం కలిగించడానికి, కురువృద్ధుడు, తాత, ప్రతాపవంతుడు అయిన భీష్ముడు సింహంలా గర్జించి గట్టిగా శంఖం ఊదాడు.",
  hi: "संजय ने कहा: तब दुर्योधन का उत्साह बढ़ाने के लिए कुरुवंश के सबसे बड़े, प्रतापी पितामह भीष्म ने सिंह की तरह गरजकर ज़ोर से अपना शंख बजाया।"
},
"gita_ch1_v13": {
  en: "Then conches, kettledrums, tabors, drums and horns all sounded at once, and the noise was tremendous.",
  te: "వెంటనే శంఖాలు, భేరీలు, పణవాలు, ఆనకాలు, గోముఖాలు ఒక్కసారిగా మోగాయి; ఆ శబ్దం భయంకరంగా ఉంది.",
  hi: "फिर शंख, नगाड़े, ढोल, मृदंग और नरसिंघे एक साथ बज उठे; वह शब्द बड़ा भयंकर था।"
},
"gita_ch1_v14": {
  en: "Then, standing in a great chariot yoked with white horses, Mādhava (Kṛṣṇa) and the son of Pāṇḍu (Arjuna) blew their divine conches.",
  te: "అప్పుడు తెల్లని గుర్రాలు కట్టిన గొప్ప రథంలో నిలిచిన మాధవుడు (శ్రీకృష్ణుడు), పాండుపుత్రుడు (అర్జునుడు) తమ దివ్య శంఖాలను ఊదారు.",
  hi: "तब सफ़ेद घोड़ों से जुते विशाल रथ पर बैठे माधव (श्रीकृष्ण) और पांडु-पुत्र (अर्जुन) ने अपने दिव्य शंख बजाए।"
},
"gita_ch1_v15": {
  en: "Hṛṣīkeśa (Kṛṣṇa) blew Pāñcajanya, Dhanañjaya (Arjuna) blew Devadatta, and Bhīma, the doer of mighty deeds, blew the great conch Pauṇḍra.",
  te: "హృషీకేశుడు పాంచజన్యాన్ని, ధనంజయుడు దేవదత్తాన్ని ఊదారు; భయంకరమైన పనులు చేసే వృకోదరుడు (భీముడు) పౌండ్రం అనే మహాశంఖాన్ని ఊదాడు.",
  hi: "हृषीकेश ने पांचजन्य, धनंजय ने देवदत्त बजाया, और भयंकर कर्म करने वाले वृकोदर (भीम) ने पौंड्र नाम का महाशंख बजाया।"
},
"gita_ch1_v16": {
  en: "King Yudhiṣṭhira, son of Kuntī, blew Anantavijaya; Nakula and Sahadeva blew Sughoṣa and Maṇipuṣpaka.",
  te: "కుంతీపుత్రుడైన యుధిష్ఠిర మహారాజు అనంతవిజయాన్ని ఊదాడు; నకులుడు సుఘోషాన్ని, సహదేవుడు మణిపుష్పకాన్ని ఊదారు.",
  hi: "कुंती-पुत्र राजा युधिष्ठिर ने अनंतविजय बजाया; नकुल और सहदेव ने सुघोष और मणिपुष्पक शंख बजाए।"
},
"gita_ch1_v17": {
  en: "The king of Kāśī, the great archer, Śikhaṇḍī the great chariot-warrior, Dhṛṣṭadyumna, Virāṭa and the unconquered Sātyaki —",
  te: "గొప్ప విలుకాడైన కాశీరాజు, మహారథుడైన శిఖండి, ధృష్టద్యుమ్నుడు, విరాటుడు, ఓటమి ఎరుగని సాత్యకి —",
  hi: "महान धनुर्धर काशीराज, महारथी शिखंडी, धृष्टद्युम्न, विराट और अजेय सात्यकि —"
},
"gita_ch1_v18": {
  en: "— Drupada and the sons of Draupadī, and the mighty-armed son of Subhadrā — all of them, O lord of the earth, blew their own conches, each one in turn.",
  te: "— ద్రుపదుడు, ద్రౌపది కుమారులు, మహాబాహువైన సుభద్ర కుమారుడు — మహారాజా! వీరందరూ తమ తమ శంఖాలను వేర్వేరుగా ఊదారు.",
  hi: "— द्रुपद, द्रौपदी के पुत्र और महाबाहु सुभद्रा-पुत्र — हे राजन्! इन सबने अलग-अलग अपने-अपने शंख बजाए।"
},
"gita_ch1_v19": {
  en: "That tumultuous sound, echoing through sky and earth, tore through the hearts of Dhṛtarāṣṭra's sons.",
  te: "ఆకాశాన్నీ భూమినీ ప్రతిధ్వనింపజేసిన ఆ భయంకరమైన ఘోష ధృతరాష్ట్రుని కుమారుల గుండెలను చీల్చివేసింది.",
  hi: "आकाश और पृथ्वी को गुँजा देने वाले उस भयंकर घोष ने धृतराष्ट्र के पुत्रों के हृदय दहला दिए।"
},
"gita_ch1_v20": {
  en: "Then, O King, seeing Dhṛtarāṣṭra's sons drawn up in array, just as the weapons were about to fly, Arjuna — whose banner bore Hanumān — raised his bow —",
  te: "మహారాజా! అప్పుడు ఆయుధాలు ప్రయోగించే సమయం రాగానే, యుద్ధానికి నిలిచిన ధృతరాష్ట్రుని కుమారులను చూసి, కపిధ్వజుడైన అర్జునుడు తన విల్లు ఎత్తి —",
  hi: "हे राजन्! तब शस्त्र चलने ही वाले थे कि सामने खड़े धृतराष्ट्र के पुत्रों को देखकर, कपिध्वज अर्जुन ने अपना धनुष उठाया —"
},
"gita_ch1_v21": {
  en: "— and spoke these words to Hṛṣīkeśa (Kṛṣṇa). Arjuna said: Acyuta, place my chariot between the two armies —",
  te: "— హృషీకేశునితో ఈ మాట అన్నాడు. అర్జునుడు అన్నాడు: అచ్యుతా! నా రథాన్ని రెండు సైన్యాల మధ్య నిలుపు —",
  hi: "— और हृषीकेश से यह वचन कहा। अर्जुन ने कहा: हे अच्युत! मेरा रथ दोनों सेनाओं के बीच खड़ा कीजिए —"
},
"gita_ch1_v22": {
  en: "— so that I may look at those standing here eager for battle, and see whom I must fight in this war.",
  te: "— యుద్ధం చేయాలనే కోరికతో ఇక్కడ నిలిచిన వీరిని నేను చూడాలి; ఈ యుద్ధంలో నేను ఎవరెవరితో పోరాడాలో తెలుసుకోవాలి.",
  hi: "— ताकि मैं यहाँ युद्ध की इच्छा से खड़े इन लोगों को देख सकूँ, और जान सकूँ कि इस युद्ध में मुझे किन-किन से लड़ना है।"
},
"gita_ch1_v23": {
  en: "I want to see those who have come here to fight, wishing to please the wicked-minded son of Dhṛtarāṣṭra in this war.",
  te: "దుర్బుద్ధి అయిన దుర్యోధనునికి యుద్ధంలో మేలు చేయాలని ఇక్కడ చేరిన యోధులను నేను చూడాలనుకుంటున్నాను.",
  hi: "दुर्बुद्धि दुर्योधन का युद्ध में भला करने की इच्छा से जो योद्धा यहाँ आए हैं, मैं उन्हें देखना चाहता हूँ।"
},
"gita_ch1_v24": {
  en: "Sañjaya said: Asked this way by Arjuna, O descendant of Bharata, Hṛṣīkeśa placed that finest of chariots between the two armies —",
  te: "సంజయుడు అన్నాడు: భారతా! అర్జునుడు ఇలా అడగగానే, హృషీకేశుడు ఆ ఉత్తమమైన రథాన్ని రెండు సైన్యాల మధ్య నిలిపి —",
  hi: "संजय ने कहा: हे भारत! अर्जुन के ऐसा कहने पर हृषीकेश ने उस उत्तम रथ को दोनों सेनाओं के बीच खड़ा किया —"
},
"gita_ch1_v25": {
  en: "— right in front of Bhīṣma, Droṇa and all the kings, and said: Pārtha, look at all these Kurus gathered here.",
  te: "— భీష్ముడు, ద్రోణుడు, ఇతర రాజులందరి ఎదుట నిలిపి, ‘పార్థా! ఇక్కడ చేరిన ఈ కౌరవులందరినీ చూడు’ అన్నాడు.",
  hi: "— भीष्म, द्रोण और सभी राजाओं के ठीक सामने, और कहा: हे पार्थ! यहाँ इकट्ठे हुए इन सब कौरवों को देखो।"
},
"gita_ch1_v26": {
  en: "There Pārtha saw, standing in both armies, fathers and grandfathers, teachers, uncles, brothers, sons, grandsons and friends —",
  te: "అక్కడ రెండు సైన్యాలలోనూ నిలిచిన తండ్రులను, తాతలను, గురువులను, మేనమామలను, సోదరులను, కుమారులను, మనుమలను, స్నేహితులను పార్థుడు చూశాడు —",
  hi: "वहाँ पार्थ ने दोनों सेनाओं में खड़े पिताओं, दादाओं, गुरुओं, मामाओं, भाइयों, पुत्रों, पोतों और मित्रों को देखा —"
},
"gita_ch1_v27": {
  en: "— fathers-in-law and dear friends too. Seeing all these relatives standing there, the son of Kuntī —",
  te: "— మామలను, ఆప్తులను కూడా చూశాడు. అక్కడ నిలిచిన ఈ బంధువులందరినీ చూసి కౌంతేయుడు —",
  hi: "— ससुरों और हितैषियों को भी। वहाँ खड़े इन सब बंधुओं को देखकर कुंती-पुत्र —"
},
"gita_ch1_v28": {
  en: "— was overcome with deep pity and spoke in sorrow. Arjuna said: Kṛṣṇa, seeing my own people gathered here, eager to fight —",
  te: "— తీవ్రమైన జాలితో నిండిపోయి, దుఃఖంతో ఇలా అన్నాడు. అర్జునుడు అన్నాడు: కృష్ణా! యుద్ధం చేయాలని ఇక్కడ చేరిన నా వాళ్ళను చూస్తుంటే —",
  hi: "— गहरी करुणा से भर गया और दुःखी होकर बोला। अर्जुन ने कहा: हे कृष्ण! युद्ध की इच्छा से यहाँ खड़े अपने ही लोगों को देखकर —"
},
"gita_ch1_v29": {
  en: "— my limbs give way and my mouth goes dry; my body trembles and my hair stands on end.",
  te: "— నా అవయవాలు సడలిపోతున్నాయి, నోరు ఎండిపోతోంది; శరీరం వణుకుతోంది, ఒళ్ళు గగుర్పొడుస్తోంది.",
  hi: "— मेरे अंग ढीले पड़ रहे हैं, मुँह सूख रहा है; शरीर काँप रहा है और रोंगटे खड़े हो रहे हैं।"
},
"gita_ch1_v30": {
  en: "The bow Gāṇḍīva is slipping from my hand and my skin is burning; I cannot stand steady, and my mind seems to be spinning.",
  te: "గాండీవం నా చేతి నుండి జారిపోతోంది, చర్మం మండిపోతోంది; నిలబడలేకపోతున్నాను, నా మనసు తిరుగుతున్నట్టు ఉంది.",
  hi: "गांडीव मेरे हाथ से फिसल रहा है और त्वचा जल रही है; मैं खड़ा नहीं रह पा रहा, मेरा मन मानो चकरा रहा है।"
},
"gita_ch1_v31": {
  en: "Keśava, I see bad omens, and I can see no good in killing my own people in battle.",
  te: "కేశవా! నాకు అపశకునాలు కనిపిస్తున్నాయి; యుద్ధంలో నా వాళ్ళను చంపడంలో ఏ మేలూ నాకు కనిపించడం లేదు.",
  hi: "हे केशव! मुझे अपशकुन दिखाई दे रहे हैं; युद्ध में अपने ही लोगों को मारने में मुझे कोई भलाई नहीं दिखती।"
},
"gita_ch1_v32": {
  en: "Kṛṣṇa, I do not want victory, nor a kingdom, nor pleasures. Govinda, what use to us is a kingdom, or enjoyment, or even life itself?",
  te: "కృష్ణా! నాకు విజయం వద్దు, రాజ్యం వద్దు, సుఖాలూ వద్దు. గోవిందా! రాజ్యంతో గానీ, భోగాలతో గానీ, చివరకు బ్రతుకుతో గానీ మాకు ఏం ప్రయోజనం?",
  hi: "हे कृष्ण! मुझे न विजय चाहिए, न राज्य, न सुख। हे गोविंद! हमें राज्य से, भोगों से, या जीवन से भी क्या लाभ?"
},
"gita_ch1_v33": {
  en: "The very people for whose sake we wanted kingdom, enjoyment and happiness stand here in battle, ready to give up their lives and wealth —",
  te: "ఎవరి కోసం మేము రాజ్యాన్ని, భోగాలను, సుఖాలను కోరుకున్నామో, వారే ప్రాణాలనూ ధనాన్నీ వదులుకోవడానికి సిద్ధపడి ఇక్కడ యుద్ధానికి నిలిచారు —",
  hi: "जिनके लिए हमने राज्य, भोग और सुख चाहे थे, वही लोग प्राण और धन त्यागने को तैयार होकर यहाँ युद्ध में खड़े हैं —"
},
"gita_ch1_v34": {
  en: "— teachers, fathers, sons and grandfathers, uncles, fathers-in-law, grandsons, brothers-in-law and other relatives.",
  te: "— గురువులు, తండ్రులు, కుమారులు, తాతలు, మేనమామలు, మామలు, మనుమలు, బావమరుదులు, ఇంకా ఇతర బంధువులు.",
  hi: "— गुरु, पिता, पुत्र, दादा, मामा, ससुर, पोते, साले और अन्य संबंधी।"
},
"gita_ch1_v35": {
  en: "Madhusūdana, I do not wish to kill them, even if they kill me — not even for rule over the three worlds, let alone for this earth.",
  te: "మధుసూదనా! వాళ్ళు నన్ను చంపినా సరే, నేను వాళ్ళను చంపాలనుకోవడం లేదు — మూడు లోకాల రాజ్యం కోసమైనా చంపను, ఇక ఈ భూమి కోసం ఏం చెప్పాలి?",
  hi: "हे मधुसूदन! वे मुझे मार भी दें, तब भी मैं उन्हें मारना नहीं चाहता — तीनों लोकों के राज्य के लिए भी नहीं, फिर इस पृथ्वी के लिए तो क्या?"
},
"gita_ch1_v36": {
  en: "Janārdana, what joy could we have by killing the sons of Dhṛtarāṣṭra? Even though they are wrongdoers, only sin would come to us by killing them.",
  te: "జనార్దనా! ధృతరాష్ట్రుని కుమారులను చంపి మాకు ఏం ఆనందం దక్కుతుంది? వాళ్ళు దుర్మార్గులే అయినా, వారిని చంపితే మాకు పాపమే అంటుకుంటుంది.",
  hi: "हे जनार्दन! धृतराष्ट्र के पुत्रों को मारकर हमें क्या प्रसन्नता मिलेगी? वे आततायी हैं, फिर भी उन्हें मारकर हमें पाप ही लगेगा।"
},
"gita_ch1_v37": {
  en: "So it is not right for us to kill the sons of Dhṛtarāṣṭra, our own kinsmen. Mādhava, how could we ever be happy after killing our own people?",
  te: "కాబట్టి మన బంధువులైన ధృతరాష్ట్రుని కుమారులను చంపడం మనకు తగదు. మాధవా! మన వాళ్ళనే చంపుకొని మనం ఎలా సుఖంగా ఉండగలం?",
  hi: "इसलिए अपने ही बंधु धृतराष्ट्र-पुत्रों को मारना हमें उचित नहीं। हे माधव! अपने ही लोगों को मारकर हम सुखी कैसे रह सकते हैं?"
},
"gita_ch1_v38": {
  en: "Even if they, their minds clouded by greed, do not see the wrong in destroying a family or the sin in betraying friends —",
  te: "లోభంతో బుద్ధి మసకబారిన వాళ్ళు, కులనాశనం వల్ల వచ్చే దోషాన్ని, మిత్రద్రోహంలోని పాపాన్ని చూడలేకపోయినా —",
  hi: "भले ही लोभ से अंधी बुद्धि वाले ये लोग कुल के नाश का दोष और मित्रों से द्रोह का पाप न देख पाएँ —"
},
"gita_ch1_v39": {
  en: "— why should we, who clearly see the wrong in destroying a family, not know enough to turn away from this sin, Janārdana?",
  te: "— జనార్దనా! కులనాశనంలోని దోషాన్ని స్పష్టంగా చూస్తున్న మనం ఈ పాపం నుండి వెనక్కి తగ్గాలని ఎందుకు తెలుసుకోకూడదు?",
  hi: "— पर हे जनार्दन! कुल के नाश का दोष साफ़ देखने वाले हम लोग इस पाप से हटने की बात क्यों न समझें?"
},
"gita_ch1_v40": {
  en: "When a family is destroyed, its age-old traditions of dharma perish; and when dharma is lost, adharma takes over the whole family.",
  te: "కులం నశిస్తే, తరతరాలుగా వస్తున్న కులధర్మాలు నశిస్తాయి; ధర్మం నశిస్తే, కులమంతటినీ అధర్మం ఆక్రమిస్తుంది.",
  hi: "कुल का नाश होने पर सनातन कुल-धर्म नष्ट हो जाते हैं; और धर्म नष्ट होने पर पूरे कुल पर अधर्म छा जाता है।"
},
"gita_ch1_v41": {
  en: "Kṛṣṇa, when adharma takes over, the women of the family go astray; and when that happens, O Vārṣṇeya, the order of society becomes mixed up and confused.",
  te: "కృష్ణా! అధర్మం పెరిగితే కులస్త్రీలు దారి తప్పుతారు; వార్ష్ణేయా! అలా జరిగితే సమాజంలో వర్ణసంకరం ఏర్పడుతుంది.",
  hi: "हे कृष्ण! अधर्म बढ़ने पर कुल की स्त्रियाँ भटक जाती हैं; और हे वार्ष्णेय! ऐसा होने पर समाज में वर्णसंकर पैदा होता है।"
},
"gita_ch1_v42": {
  en: "This confusion drags both the family and those who destroyed it into hell; their ancestors fall too, deprived of the offerings of rice-balls and water.",
  te: "ఈ సంకరం కులాన్నీ, కులాన్ని నాశనం చేసినవారినీ నరకానికే తీసుకెళ్తుంది; పిండోదక క్రియలు ఆగిపోవడం వల్ల వారి పితృదేవతలు కూడా పతనమవుతారు.",
  hi: "यह संकर कुल को और कुल का नाश करने वालों को नरक में ले जाता है; पिंड और जल-तर्पण बंद हो जाने से उनके पितर भी गिर जाते हैं।"
},
"gita_ch1_v43": {
  en: "Through these wrongs of the family-destroyers, which bring about this confusion, the duties of the community and the age-old duties of the family are ruined.",
  te: "వర్ణసంకరానికి కారణమైన కులఘాతకుల ఈ దోషాల వల్ల జాతిధర్మాలు, శాశ్వతమైన కులధర్మాలు నాశనమవుతాయి.",
  hi: "वर्णसंकर पैदा करने वाले कुल-नाशकों के इन दोषों से जाति-धर्म और सनातन कुल-धर्म नष्ट हो जाते हैं।"
},
"gita_ch1_v44": {
  en: "Janārdana, we have heard that people whose family traditions are destroyed must live in hell for a very long time.",
  te: "జనార్దనా! కులధర్మాలు నశించిన మనుషులు ఎంతో కాలం నరకంలో ఉండవలసి వస్తుందని మేము విన్నాము.",
  hi: "हे जनार्दन! हमने सुना है कि जिन मनुष्यों के कुल-धर्म नष्ट हो जाते हैं, उन्हें अनिश्चित काल तक नरक में रहना पड़ता है।"
},
"gita_ch1_v45": {
  en: "Alas! What a great sin we have made up our minds to commit — ready to kill our own people out of greed for the pleasures of a kingdom!",
  te: "అయ్యో! రాజ్యసుఖాల మీద ఆశతో మన వాళ్ళనే చంపడానికి సిద్ధపడి, ఎంత పెద్ద పాపం చేయడానికి నిశ్చయించుకున్నాం!",
  hi: "हाय! राज्य-सुख के लोभ में अपने ही लोगों को मारने को तैयार होकर, हमने कितना बड़ा पाप करने का निश्चय कर लिया है!"
},
"gita_ch1_v46": {
  en: "It would be better for me if the sons of Dhṛtarāṣṭra, weapons in hand, killed me in battle while I stood unarmed and did not fight back.",
  te: "నేను ఆయుధం లేకుండా, ఎదురు తిరగకుండా ఉండగా, ఆయుధాలు పట్టిన ధృతరాష్ట్రుని కుమారులు నన్ను యుద్ధంలో చంపినా, అదే నాకు మేలు.",
  hi: "यदि मैं बिना शस्त्र के, बिना प्रतिकार किए रहूँ और हाथ में शस्त्र लिए धृतराष्ट्र के पुत्र मुझे युद्ध में मार डालें, तो वह मेरे लिए अधिक कल्याणकारी होगा।"
},
"gita_ch1_v47": {
  en: "Sañjaya said: Having spoken this way on the battlefield, Arjuna threw aside his bow and arrows and sank down on the seat of his chariot, his mind overwhelmed with grief.",
  te: "సంజయుడు అన్నాడు: యుద్ధభూమిలో ఇలా పలికి, అర్జునుడు బాణాలతో సహా విల్లును పక్కన పడేసి, దుఃఖంతో కలత చెందిన మనసుతో రథంలో కూలబడ్డాడు.",
  hi: "संजय ने कहा: रणभूमि में ऐसा कहकर, शोक से व्याकुल मन वाला अर्जुन बाणों सहित धनुष त्यागकर रथ के पिछले भाग में बैठ गया।"
},

// ── Chapter 2 · Sāṅkhya Yoga ──
"gita_ch2_v1": {
  en: "Sañjaya said: To Arjuna, overcome with pity, his eyes full of tears and troubled, sinking in sorrow, Madhusūdana spoke these words.",
  te: "సంజయుడు అన్నాడు: జాలితో నిండిపోయి, కన్నీళ్ళతో నిండిన కళ్ళతో కలవరపడుతూ, దుఃఖంలో మునిగిపోయిన అర్జునునితో మధుసూదనుడు ఈ మాటలు అన్నాడు.",
  hi: "संजय ने कहा: करुणा से घिरे, आँसुओं से भरी व्याकुल आँखों वाले और शोक में डूबे अर्जुन से मधुसूदन ने ये वचन कहे।"
},
"gita_ch2_v2": {
  en: "The Lord said: Arjuna, where has this weakness come upon you at such a critical hour? It does not suit a noble person; it leads neither to heaven nor to honour.",
  te: "శ్రీ భగవానుడు అన్నాడు: అర్జునా! ఇంత కీలకమైన సమయంలో ఈ మనోదౌర్బల్యం నీకు ఎక్కడి నుండి వచ్చింది? ఇది శ్రేష్ఠులకు తగినది కాదు; స్వర్గాన్నీ ఇవ్వదు, కీర్తినీ ఇవ్వదు.",
  hi: "श्री भगवान ने कहा: हे अर्जुन! इस संकट की घड़ी में यह मोह तुम पर कहाँ से आ गया? यह श्रेष्ठ पुरुषों के योग्य नहीं है; यह न स्वर्ग देता है, न यश।"
},
"gita_ch2_v3": {
  en: "Do not give in to this unmanliness, Pārtha; it is not worthy of you. Shake off this petty weakness of heart and stand up, scorcher of foes!",
  te: "పార్థా! ఈ పిరికితనానికి లొంగిపోకు; ఇది నీకు తగదు. ఈ అల్పమైన హృదయ దౌర్బల్యాన్ని వదిలించుకుని లే, పరంతపా!",
  hi: "हे पार्थ! इस कायरता के वश में मत हो; यह तुम्हें शोभा नहीं देती। हृदय की इस तुच्छ दुर्बलता को त्यागकर उठ खड़े हो, हे परंतप!"
},
"gita_ch2_v4": {
  en: "Arjuna said: Madhusūdana, how can I fight back with arrows in battle against Bhīṣma and Droṇa, who are worthy of my worship?",
  te: "అర్జునుడు అన్నాడు: మధుసూదనా! పూజింపదగిన భీష్ముని, ద్రోణుని పైకి యుద్ధంలో నేను బాణాలతో ఎలా ఎదురు దాడి చేయగలను?",
  hi: "अर्जुन ने कहा: हे मधुसूदन! पूजा के योग्य भीष्म और द्रोण पर मैं युद्ध में बाणों से कैसे प्रहार करूँ?"
},
"gita_ch2_v5": {
  en: "Better to live in this world even by begging than to kill these noble elders. If I kill them, even the pleasures I enjoy here would be stained with their blood, however much I may gain.",
  te: "ఈ మహానుభావులైన గురువులను చంపడం కంటే ఈ లోకంలో భిక్షమెత్తుకుని బ్రతకడమే మేలు. వారిని చంపితే, నేను అనుభవించే సుఖాలన్నీ వారి రక్తంతో తడిసినవే అవుతాయి.",
  hi: "इन महान गुरुजनों को मारने से तो इस संसार में भीख माँगकर जीना भी अच्छा है। उन्हें मारकर जो भी सुख भोगूँगा, वे सब उनके रक्त से सने होंगे।"
},
"gita_ch2_v6": {
  en: "We do not even know which is better for us — that we win or that they win. The sons of Dhṛtarāṣṭra stand before us, and if we kill them we would not even wish to live.",
  te: "మనం గెలవడం మంచిదా, వాళ్ళు గెలవడం మంచిదా — ఏది శ్రేయస్కరమో కూడా మాకు తెలియడం లేదు. ఎవరిని చంపితే మేము బ్రతకాలని కూడా కోరుకోమో, ఆ ధృతరాష్ట్రుని కుమారులే మా ఎదుట నిలిచి ఉన్నారు.",
  hi: "हम यह भी नहीं जानते कि हमारे लिए क्या अच्छा है — हम जीतें या वे जीतें। जिन्हें मारकर हम जीना भी नहीं चाहेंगे, वही धृतराष्ट्र के पुत्र हमारे सामने खड़े हैं।"
},
"gita_ch2_v7": {
  en: "My natural strength is overpowered by weakness and my mind is confused about what is right. I ask You: tell me for certain what is best for me. I am Your disciple; I have taken refuge in You — teach me.",
  te: "దైన్యం నా సహజ స్వభావాన్ని కప్పేసింది; ఏది ధర్మమో తెలియక నా మనసు అయోమయంలో ఉంది. నిన్ను అడుగుతున్నాను — నాకు నిజంగా ఏది శ్రేయస్కరమో నిశ్చయంగా చెప్పు. నేను నీ శిష్యుణ్ణి, నిన్ను శరణు వేడాను — నాకు బోధించు.",
  hi: "दीनता ने मेरे स्वभाव को दबा लिया है और धर्म के विषय में मेरा मन उलझ गया है। मैं आपसे पूछता हूँ — जो निश्चित रूप से मेरे लिए कल्याणकारी हो, वह बताइए। मैं आपका शिष्य हूँ, आपकी शरण में आया हूँ — मुझे उपदेश दीजिए।"
},
"gita_ch2_v8": {
  en: "Even if I won an unrivalled, prosperous kingdom on earth, or even lordship over the gods, I see nothing that could remove this grief that is drying up my senses.",
  te: "భూమిపై ఎదురులేని, సంపన్నమైన రాజ్యం దక్కినా, దేవతలపై ఆధిపత్యం దక్కినా సరే — నా ఇంద్రియాలను ఎండిపోయేలా చేస్తున్న ఈ శోకాన్ని పోగొట్టేది ఏదీ నాకు కనిపించడం లేదు.",
  hi: "पृथ्वी पर निष्कंटक, समृद्ध राज्य मिल जाए या देवताओं का आधिपत्य भी — मुझे ऐसा कुछ नहीं दिखता जो मेरी इंद्रियों को सुखा देने वाले इस शोक को दूर कर सके।"
},
"gita_ch2_v9": {
  en: "Sañjaya said: Having spoken thus to Hṛṣīkeśa, Arjuna, the conqueror of sleep, said to Govinda, ‘I will not fight,’ and fell silent.",
  te: "సంజయుడు అన్నాడు: హృషీకేశునితో ఇలా చెప్పి, నిద్రను జయించిన అర్జునుడు గోవిందునితో ‘నేను యుద్ధం చేయను’ అని పలికి మౌనంగా ఉండిపోయాడు.",
  hi: "संजय ने कहा: हृषीकेश से ऐसा कहकर, निद्रा को जीतने वाले अर्जुन ने गोविंद से ‘मैं युद्ध नहीं करूँगा’ कहा और चुप हो गया।"
},
"gita_ch2_v10": {
  en: "Then, O Bhārata, between the two armies, Hṛṣīkeśa, as if smiling, spoke these words to the grieving Arjuna.",
  te: "భారతా! అప్పుడు రెండు సైన్యాల మధ్య, దుఃఖిస్తున్న అర్జునునితో హృషీకేశుడు చిరునవ్వు నవ్వుతున్నట్లుగా ఈ మాటలు అన్నాడు.",
  hi: "हे भारत! तब दोनों सेनाओं के बीच, शोक करते अर्जुन से हृषीकेश ने मानो मुस्कुराते हुए ये वचन कहे।"
},
"gita_ch2_v11": {
  en: "The Lord said: You grieve for those who need no grieving, and yet you speak words that sound wise. The truly wise grieve neither for the dead nor for the living.",
  te: "శ్రీ భగవానుడు అన్నాడు: దుఃఖించనక్కరలేని వారి కోసం నువ్వు దుఃఖిస్తున్నావు, అయినా జ్ఞానుల్లా మాట్లాడుతున్నావు. నిజమైన జ్ఞానులు చనిపోయినవారి కోసం గానీ, బ్రతికున్నవారి కోసం గానీ శోకించరు.",
  hi: "श्री भगवान ने कहा: तुम उनके लिए शोक कर रहे हो जो शोक के योग्य नहीं, और फिर भी ज्ञानियों जैसी बातें करते हो। सच्चे ज्ञानी न मरे हुओं के लिए शोक करते हैं, न जीवितों के लिए।"
},
"gita_ch2_v12": {
  en: "Never was there a time when I did not exist, nor you, nor these kings; nor will any of us ever cease to exist in the future.",
  te: "నేను లేని కాలం ఎప్పుడూ లేదు; నువ్వు గానీ, ఈ రాజులు గానీ లేని కాలమూ లేదు. ఇకముందు కూడా మనమెవ్వరం లేకుండా పోము.",
  hi: "ऐसा कभी नहीं था कि मैं न रहा हूँ, या तुम न रहे हो, या ये राजा न रहे हों; और न ही आगे कभी ऐसा होगा कि हम सब न रहें।"
},
"gita_ch2_v13": {
  en: "Just as the embodied soul passes through childhood, youth and old age in this body, so it passes into another body. The steady person is not confused by this.",
  te: "ఈ దేహంలో ఉన్న ఆత్మకు బాల్యం, యౌవనం, ముసలితనం ఎలా వస్తాయో, అలాగే మరో దేహం కూడా వస్తుంది. ధీరుడు దీనికి కలవరపడడు.",
  hi: "जैसे देहधारी आत्मा इस शरीर में बचपन, जवानी और बुढ़ापे से गुज़रती है, वैसे ही उसे दूसरा शरीर मिलता है। धीर पुरुष इससे मोहित नहीं होता।"
},
"gita_ch2_v14": {
  en: "Contact of the senses with their objects brings cold and heat, pleasure and pain. They come and go and do not last — bear them patiently, Arjuna.",
  te: "కౌంతేయా! ఇంద్రియాలు విషయాలను తాకినప్పుడు చలి-వేడి, సుఖ-దుఃఖాలు కలుగుతాయి. అవి వచ్చిపోయేవి, శాశ్వతం కానివి — భారతా, వాటిని ఓర్పుతో సహించు.",
  hi: "हे कौंतेय! इंद्रियों का विषयों से संपर्क सर्दी-गर्मी और सुख-दुःख देता है। ये आते-जाते हैं, स्थायी नहीं हैं — हे भारत, इन्हें धैर्य से सहन करो।"
},
"gita_ch2_v15": {
  en: "The steady person whom these do not disturb, who stays the same in pain and pleasure — that person, best of men, becomes fit for immortality.",
  te: "పురుషశ్రేష్ఠా! ఇవి ఎవరిని కలవరపెట్టవో, సుఖదుఃఖాలలో ఎవరు సమంగా, ధీరంగా ఉంటారో — ఆ మనిషే అమృతత్వానికి (మోక్షానికి) అర్హుడవుతాడు.",
  hi: "हे पुरुषश्रेष्ठ! जिसे ये व्याकुल नहीं करते, जो सुख-दुःख में समान और धीर रहता है — वही अमृतत्व (मोक्ष) के योग्य होता है।"
},
"gita_ch2_v16": {
  en: "The unreal has no lasting existence, and the real never ceases to be. Those who see the truth have understood the nature of both.",
  te: "అసత్యమైనదానికి ఉనికి లేదు; సత్యమైనదానికి నాశనం లేదు. తత్త్వం తెలిసినవారు ఈ రెండింటి నిజస్వరూపాన్నీ గ్రహించారు.",
  hi: "असत् का अस्तित्व नहीं है और सत् का अभाव नहीं है। तत्त्वदर्शियों ने इन दोनों का सच्चा स्वरूप जान लिया है।"
},
"gita_ch2_v17": {
  en: "Know that That which pervades this whole world is indestructible. No one can bring about the destruction of the imperishable.",
  te: "ఈ సమస్త జగత్తునూ వ్యాపించి ఉన్నది నాశనం లేనిదని తెలుసుకో. నాశనం లేని దానిని ఎవ్వరూ నాశనం చేయలేరు.",
  hi: "जिससे यह सारा जगत व्याप्त है, उसे अविनाशी जानो। उस अविनाशी का विनाश कोई नहीं कर सकता।"
},
"gita_ch2_v18": {
  en: "These bodies of the eternal, indestructible and immeasurable soul are said to have an end. Therefore, fight, O Bhārata.",
  te: "నిత్యమైన, నాశనం లేని, అంచనాకు అందని ఆత్మ ధరించిన ఈ దేహాలు మాత్రమే అంతమయ్యేవి. కాబట్టి భారతా, యుద్ధం చెయ్యి.",
  hi: "नित्य, अविनाशी और अपरिमेय आत्मा के ये शरीर नाशवान कहे गए हैं। इसलिए हे भारत, युद्ध करो।"
},
"gita_ch2_v19": {
  en: "One who thinks the soul is a killer, and one who thinks it is killed — both do not understand. The soul neither kills nor is killed.",
  te: "ఆత్మ చంపుతుందని అనుకునేవాడూ, ఆత్మ చంపబడుతుందని అనుకునేవాడూ — ఇద్దరూ నిజం తెలియనివారే. ఆత్మ ఎవరినీ చంపదు, చంపబడదు.",
  hi: "जो आत्मा को मारने वाला समझता है और जो उसे मरा हुआ मानता है — दोनों ही सत्य नहीं जानते। आत्मा न मारती है, न मारी जाती है।"
},
"gita_ch2_v20": {
  en: "The soul is never born and never dies; it did not come into being and will not cease to be. Unborn, eternal, everlasting and ancient, it is not killed when the body is killed.",
  te: "ఆత్మ ఎప్పుడూ పుట్టదు, ఎప్పుడూ చావదు; ఒకప్పుడు పుట్టి, మళ్ళీ లేకుండా పోయేది కాదు. పుట్టుక లేనిది, నిత్యమైనది, శాశ్వతమైనది, సనాతనమైనది — దేహం చంపబడినా ఇది చంపబడదు.",
  hi: "आत्मा न कभी जन्म लेती है, न मरती है; न यह होकर फिर न होने वाली है। यह अजन्मा, नित्य, शाश्वत और पुरातन है — शरीर के मारे जाने पर भी यह नहीं मरती।"
},
"gita_ch2_v21": {
  en: "Pārtha, one who knows the soul to be indestructible, eternal, unborn and unchanging — how can such a person kill anyone, or cause anyone to be killed?",
  te: "పార్థా! ఆత్మను నాశనం లేనిదిగా, నిత్యమైనదిగా, పుట్టుక లేనిదిగా, మార్పు లేనిదిగా తెలుసుకున్నవాడు ఎవరినైనా ఎలా చంపగలడు? ఎవరిని చంపించగలడు?",
  hi: "हे पार्थ! जो आत्मा को अविनाशी, नित्य, अजन्मा और अविकारी जानता है, वह किसे कैसे मार सकता है, या किसे मरवा सकता है?"
},
"gita_ch2_v22": {
  en: "Just as a person throws away worn-out clothes and puts on new ones, so the embodied soul leaves worn-out bodies and enters new ones.",
  te: "మనిషి పాతబడిన బట్టలను విడిచి కొత్త బట్టలు ఎలా ధరిస్తాడో, అలాగే దేహంలోని ఆత్మ పాతబడిన శరీరాలను విడిచి కొత్త శరీరాలను పొందుతుంది.",
  hi: "जैसे मनुष्य पुराने वस्त्र छोड़कर नए वस्त्र पहन लेता है, वैसे ही आत्मा जीर्ण शरीरों को छोड़कर नए शरीरों में प्रवेश करती है।"
},
"gita_ch2_v23": {
  en: "Weapons cannot cut the soul, fire cannot burn it, water cannot wet it, and wind cannot dry it.",
  te: "ఆయుధాలు ఆత్మను నరకలేవు, అగ్ని దీనిని కాల్చలేదు, నీరు తడపలేదు, గాలి ఎండబెట్టలేదు.",
  hi: "आत्मा को शस्त्र काट नहीं सकते, आग जला नहीं सकती, जल भिगो नहीं सकता और वायु सुखा नहीं सकती।"
},
"gita_ch2_v24": {
  en: "It cannot be cut, burnt, wetted or dried. It is eternal, present everywhere, stable, unmoving and timeless.",
  te: "ఇది నరకబడనిది, కాల్చబడనిది, తడపబడనిది, ఎండబడనిది. ఇది నిత్యమైనది, అంతటా ఉన్నది, స్థిరమైనది, కదలనిది, సనాతనమైనది.",
  hi: "यह न काटी जा सकती है, न जलाई, न भिगोई, न सुखाई। यह नित्य, सर्वव्यापी, स्थिर, अचल और सनातन है।"
},
"gita_ch2_v25": {
  en: "It is said to be unseen, beyond thought and unchanging. Knowing it to be so, you should not grieve.",
  te: "ఇది కంటికి కనిపించనిది, ఆలోచనకు అందనిది, మార్పు లేనిది అని చెబుతారు. దీనిని ఇలా తెలుసుకుని, నువ్వు శోకించకూడదు.",
  hi: "इसे अव्यक्त, अचिंत्य और अविकारी कहा जाता है। इसे ऐसा जानकर तुम्हें शोक नहीं करना चाहिए।"
},
"gita_ch2_v26": {
  en: "And even if you think the soul is constantly born and constantly dies, mighty-armed one, even then you should not grieve.",
  te: "మహాబాహూ! ఒకవేళ ఆత్మ ఎప్పుడూ పుడుతూ, ఎప్పుడూ చనిపోతూ ఉంటుందని నువ్వు అనుకున్నా సరే — అప్పుడు కూడా నువ్వు ఇలా దుఃఖించనక్కరలేదు.",
  hi: "हे महाबाहो! यदि तुम आत्मा को सदा जन्म लेने वाली और सदा मरने वाली भी मानो, तब भी तुम्हें इस प्रकार शोक नहीं करना चाहिए।"
},
"gita_ch2_v27": {
  en: "For death is certain for whatever is born, and birth is certain for whatever dies. So you should not grieve over what cannot be avoided.",
  te: "పుట్టినవానికి మరణం తప్పదు; మరణించినవానికి మళ్ళీ పుట్టుక తప్పదు. కాబట్టి తప్పించుకోలేని విషయం గురించి నువ్వు శోకించకూడదు.",
  hi: "जो जन्मा है उसकी मृत्यु निश्चित है, और जो मरा है उसका जन्म निश्चित है। इसलिए जो टल नहीं सकता, उस पर तुम्हें शोक नहीं करना चाहिए।"
},
"gita_ch2_v28": {
  en: "Beings are unseen before birth, seen in the middle, and unseen again after death, O Bhārata. What is there to lament in this?",
  te: "భారతా! ప్రాణులు పుట్టుకకు ముందు కనిపించవు, మధ్యలో కనిపిస్తాయి, మరణం తర్వాత మళ్ళీ కనిపించవు. ఇందులో విలపించడానికి ఏముంది?",
  hi: "हे भारत! प्राणी जन्म से पहले अप्रकट, बीच में प्रकट और मृत्यु के बाद फिर अप्रकट हो जाते हैं। इसमें विलाप की क्या बात है?"
},
"gita_ch2_v29": {
  en: "Some look upon the soul as a wonder, some speak of it as a wonder, and some hear of it as a wonder; yet even after hearing, no one truly knows it.",
  te: "కొందరు ఆత్మను ఒక అద్భుతంగా చూస్తారు; కొందరు అద్భుతంగా వర్ణిస్తారు; మరికొందరు అద్భుతంగా వింటారు. అయినా విన్న తర్వాత కూడా దీనిని పూర్తిగా తెలుసుకున్నవారు ఎవరూ లేరు.",
  hi: "कोई आत्मा को आश्चर्य की तरह देखता है, कोई आश्चर्य की तरह उसका वर्णन करता है, और कोई आश्चर्य की तरह सुनता है; फिर भी सुनकर भी कोई इसे पूरी तरह नहीं जानता।"
},
"gita_ch2_v30": {
  en: "The soul dwelling in every body can never be slain, O Bhārata. Therefore you should not grieve for any being.",
  te: "భారతా! అందరి దేహాల్లో ఉన్న ఆత్మ ఎప్పటికీ చంపబడదు. కాబట్టి ఏ ప్రాణి గురించీ నువ్వు శోకించకూడదు.",
  hi: "हे भारत! सबके शरीर में रहने वाली यह आत्मा सदा अवध्य है। इसलिए किसी भी प्राणी के लिए तुम्हें शोक नहीं करना चाहिए।"
},
"gita_ch2_v31": {
  en: "Looking at your own duty too, you should not waver. For a warrior there is nothing better than a righteous battle.",
  te: "నీ స్వధర్మాన్ని చూసుకున్నా కూడా నువ్వు తడబడకూడదు. క్షత్రియునికి ధర్మయుద్ధం కంటే శ్రేయస్కరమైనది మరొకటి లేదు.",
  hi: "अपने स्वधर्म को देखकर भी तुम्हें डगमगाना नहीं चाहिए। क्षत्रिय के लिए धर्मयुद्ध से बढ़कर कल्याणकारी और कुछ नहीं है।"
},
"gita_ch2_v32": {
  en: "Happy are the warriors, Pārtha, who meet such a battle that comes on its own, like an open door to heaven.",
  te: "పార్థా! తనంతట తానే వచ్చిన, తెరిచిన స్వర్గద్వారంలాంటి ఇలాంటి యుద్ధం అదృష్టవంతులైన క్షత్రియులకే లభిస్తుంది.",
  hi: "हे पार्थ! अपने आप आया हुआ, खुले स्वर्गद्वार जैसा ऐसा युद्ध भाग्यशाली क्षत्रियों को ही मिलता है।"
},
"gita_ch2_v33": {
  en: "But if you will not fight this righteous war, then you will abandon your duty and your good name, and you will incur sin.",
  te: "కానీ ఈ ధర్మయుద్ధాన్ని నువ్వు చేయకపోతే, నీ స్వధర్మాన్నీ, కీర్తినీ పోగొట్టుకుని పాపాన్ని పొందుతావు.",
  hi: "परंतु यदि तुम यह धर्मयुद्ध नहीं करोगे, तो अपना स्वधर्म और कीर्ति खोकर पाप के भागी बनोगे।"
},
"gita_ch2_v34": {
  en: "People will speak of your dishonour for ever. And for one who has been respected, dishonour is worse than death.",
  te: "లోకులు నీ అపకీర్తిని ఎప్పటికీ చెప్పుకుంటారు. గౌరవం పొందినవానికి అపకీర్తి మరణం కంటే ఘోరమైనది.",
  hi: "लोग सदा तुम्हारी अपकीर्ति की चर्चा करेंगे। और सम्मानित व्यक्ति के लिए अपकीर्ति मृत्यु से भी बढ़कर है।"
},
"gita_ch2_v35": {
  en: "The great chariot-warriors will think you withdrew from battle out of fear, and those who held you in high esteem will think little of you.",
  te: "నువ్వు భయంతో యుద్ధం నుండి వెనక్కి తగ్గావని మహారథులు అనుకుంటారు. నిన్ను ఎంతో గౌరవించినవారి దృష్టిలో నువ్వు చులకనైపోతావు.",
  hi: "महारथी समझेंगे कि तुम डरकर युद्ध से हट गए, और जो तुम्हें बहुत मानते थे, उनकी दृष्टि में तुम छोटे हो जाओगे।"
},
"gita_ch2_v36": {
  en: "Your enemies will say many unspeakable things, mocking your strength. What could be more painful than that?",
  te: "నీ శత్రువులు నీ సామర్థ్యాన్ని హేళన చేస్తూ, అనకూడని మాటలెన్నో అంటారు. అంతకంటే బాధాకరమైనది ఇంకేముంటుంది?",
  hi: "तुम्हारे शत्रु तुम्हारे सामर्थ्य की निंदा करते हुए बहुत-सी न कहने योग्य बातें कहेंगे। इससे बढ़कर दुःख और क्या होगा?"
},
"gita_ch2_v37": {
  en: "If you are killed, you will reach heaven; if you win, you will enjoy the earth. So rise, son of Kuntī, determined to fight.",
  te: "యుద్ధంలో చనిపోతే స్వర్గాన్ని పొందుతావు; గెలిస్తే భూమిని అనుభవిస్తావు. కాబట్టి కౌంతేయా, యుద్ధం చేయాలనే దృఢ నిశ్చయంతో లే.",
  hi: "मारे गए तो स्वर्ग पाओगे, जीत गए तो पृथ्वी का भोग करोगे। इसलिए हे कौंतेय, युद्ध का दृढ़ निश्चय करके उठो।"
},
"gita_ch2_v38": {
  en: "Treating pleasure and pain, gain and loss, victory and defeat as the same, get ready for battle. In this way you will not incur sin.",
  te: "సుఖదుఃఖాలనూ, లాభనష్టాలనూ, జయాపజయాలనూ సమానంగా భావించి యుద్ధానికి సిద్ధమవ్వు. ఇలా చేస్తే నీకు పాపం అంటదు.",
  hi: "सुख-दुःख, लाभ-हानि और जय-पराजय को समान मानकर युद्ध के लिए तैयार हो जाओ। ऐसा करने से तुम्हें पाप नहीं लगेगा।"
},
"gita_ch2_v39": {
  en: "So far I have taught you the wisdom of Sāṅkhya, knowledge of the Self. Now hear the wisdom of Yoga; joined with it, Pārtha, you will break free from the bondage of action.",
  te: "ఇంతవరకు నీకు సాంఖ్యజ్ఞానాన్ని (ఆత్మజ్ఞానాన్ని) చెప్పాను. ఇప్పుడు యోగబుద్ధిని గురించి విను. పార్థా, ఆ బుద్ధితో కూడితే కర్మబంధం నుండి విడుదలవుతావు.",
  hi: "अब तक मैंने तुम्हें सांख्य (आत्मज्ञान) की बुद्धि बताई। अब योग की बुद्धि सुनो; हे पार्थ, उससे युक्त होकर तुम कर्म के बंधन से छूट जाओगे।"
},
"gita_ch2_v40": {
  en: "On this path no effort is ever wasted and there is no harm from falling short. Even a little of this dharma protects one from great fear.",
  te: "ఈ మార్గంలో చేసిన ప్రయత్నం ఎప్పుడూ వృథా కాదు; అసంపూర్ణంగా ఆగిపోయినా హాని ఉండదు. ఈ ధర్మం కొంచెం ఆచరించినా గొప్ప భయం నుండి కాపాడుతుంది.",
  hi: "इस मार्ग में किया गया प्रयास कभी व्यर्थ नहीं जाता और अधूरा रहने पर भी कोई हानि नहीं होती। इस धर्म का थोड़ा-सा पालन भी बड़े भय से रक्षा करता है।"
},
"gita_ch2_v41": {
  en: "Here, joy of the Kurus, the resolute mind is single and focused; but the thoughts of the irresolute are many-branched and endless.",
  te: "కురునందనా! ఈ మార్గంలో నిశ్చయమైన బుద్ధి ఒక్కటే, ఏకాగ్రమైనది. నిశ్చయం లేనివారి ఆలోచనలు అనేక కొమ్మలుగా, అంతులేకుండా చీలిపోతాయి.",
  hi: "हे कुरुनंदन! इस मार्ग में निश्चयवाली बुद्धि एक ही होती है; पर अनिश्चयी लोगों की बुद्धियाँ अनेक शाखाओं वाली और अनंत होती हैं।"
},
"gita_ch2_v42": {
  en: "Pārtha, the unwise speak flowery words; they delight in the letter of the Vedas and say there is nothing beyond it —",
  te: "పార్థా! అవివేకులు పూలవంటి ఆకర్షణీయమైన మాటలు పలుకుతారు; వేదాల్లోని కర్మకాండ మాటలలోనే ఆనందిస్తూ, ఇంతకు మించి ఇంకేమీ లేదని అంటారు —",
  hi: "हे पार्थ! अज्ञानी लोग फूलों जैसी लुभावनी बातें करते हैं; वे वेदों के कर्मकांड वाले वचनों में ही रमे रहते हैं और कहते हैं कि इसके आगे कुछ नहीं है —"
},
"gita_ch2_v43": {
  en: "— full of desires, intent on heaven, they praise many special rituals that promise rebirth as the reward of action and aim at pleasure and power.",
  te: "— కోరికలతో నిండి, స్వర్గమే పరమ లక్ష్యంగా భావిస్తూ, భోగాలనూ ఐశ్వర్యాన్నీ ఇచ్చే, మళ్ళీ జన్మనే ఫలంగా ఇచ్చే ఎన్నో ప్రత్యేక కర్మలను వారు పొగుడుతారు.",
  hi: "— कामनाओं से भरे, स्वर्ग को ही परम मानने वाले वे भोग और ऐश्वर्य दिलाने वाले, और कर्मफल के रूप में फिर जन्म देने वाले अनेक विशेष कर्मकांडों का गुणगान करते हैं।"
},
"gita_ch2_v44": {
  en: "Those who cling to pleasure and power, whose minds are carried away by such words, do not attain the resolute mind that rests in meditation.",
  te: "భోగాలకూ ఐశ్వర్యానికీ అతుక్కుపోయి, ఆ మాటలకు మనసు కొట్టుకుపోయినవారికి సమాధిలో నిలిచే నిశ్చయమైన బుద్ధి కలగదు.",
  hi: "जो भोग और ऐश्वर्य में आसक्त हैं और जिनका मन उन वचनों से हर लिया गया है, उनकी निश्चयवाली बुद्धि समाधि में स्थिर नहीं होती।"
},
"gita_ch2_v45": {
  en: "The Vedas deal with the three guṇas; rise above the three guṇas, Arjuna. Be free from the pairs of opposites, always rooted in purity, unconcerned with getting and keeping, and centred in the Self.",
  te: "అర్జునా! వేదాలు త్రిగుణాలకు సంబంధించిన విషయాలను చెబుతాయి; నువ్వు త్రిగుణాలకు అతీతుడివి కా. ద్వంద్వాలకు అతీతంగా, ఎల్లప్పుడూ సత్త్వంలో నిలిచి, సంపాదించడం-కాపాడుకోవడం అనే చింత లేకుండా, ఆత్మనిష్ఠుడివై ఉండు.",
  hi: "हे अर्जुन! वेद तीन गुणों के विषयों का वर्णन करते हैं; तुम तीनों गुणों से ऊपर उठो। द्वंद्वों से मुक्त, सदा सत्त्व में स्थित, पाने और बचाने की चिंता से रहित और आत्मनिष्ठ बनो।"
},
"gita_ch2_v46": {
  en: "Whatever use there is for a small well when there is water flooding everywhere, that much use is there in all the Vedas for a brāhmaṇa who knows the truth.",
  te: "అంతటా నీళ్ళు నిండిపోయినప్పుడు చిన్న బావితో ఎంత ప్రయోజనమో, తత్త్వం తెలిసిన బ్రహ్మజ్ఞానికి వేదాలన్నిటితో అంతే ప్రయోజనం.",
  hi: "चारों ओर जल से भर जाने पर एक छोटे कुएँ का जितना प्रयोजन रहता है, सत्य को जानने वाले ब्रह्मज्ञानी के लिए सब वेदों का उतना ही प्रयोजन रहता है।"
},
"gita_ch2_v47": {
  en: "Your right is to the work alone, never to its fruits. Do not let the result be your motive, and do not be attached to doing nothing.",
  te: "నీకు కర్మ చేయడంలోనే అధికారం ఉంది, దాని ఫలాల మీద ఎప్పుడూ లేదు. ఫలం కోసమే పని చేసేవాడివి కాకు; అలాగని పని చేయకుండా ఉండటంపైనా ఆసక్తి పెట్టుకోకు.",
  hi: "तुम्हारा अधिकार केवल कर्म पर है, उसके फलों पर कभी नहीं। फल को कर्म का कारण मत बनाओ, और कर्म न करने में भी आसक्ति मत रखो।"
},
"gita_ch2_v48": {
  en: "Established in yoga, do your work, Dhanañjaya, giving up attachment and staying the same in success and failure. This evenness of mind is called yoga.",
  te: "ధనంజయా! యోగంలో నిలిచి, ఆసక్తిని విడిచిపెట్టి, విజయంలోనూ వైఫల్యంలోనూ సమంగా ఉంటూ కర్మలు చెయ్యి. ఈ సమత్వమే యోగం అనబడుతుంది.",
  hi: "हे धनंजय! योग में स्थित होकर, आसक्ति त्यागकर और सफलता-असफलता में समान रहकर कर्म करो। यही समत्व योग कहलाता है।"
},
"gita_ch2_v49": {
  en: "Action done for its rewards is far inferior to action done with this balanced understanding, Dhanañjaya. Take refuge in that understanding; pitiable are those who work only for results.",
  te: "ధనంజయా! సమత్వబుద్ధితో చేసే కర్మ కంటే ఫలం కోసం చేసే కర్మ చాలా తక్కువస్థాయిది. ఆ బుద్ధినే ఆశ్రయించు; ఫలం కోసమే పనిచేసేవారు దీనులు.",
  hi: "हे धनंजय! समत्व-बुद्धि से किए कर्म की तुलना में फल के लिए किया गया कर्म बहुत निम्न है। उसी बुद्धि की शरण लो; केवल फल के लिए कर्म करने वाले दयनीय हैं।"
},
"gita_ch2_v50": {
  en: "One joined with this wisdom leaves behind both good and bad deeds even here. So devote yourself to yoga — yoga is skill in action.",
  te: "సమత్వబుద్ధితో కూడినవాడు ఇక్కడే పుణ్యపాపాలు రెండింటినీ దాటిపోతాడు. కాబట్టి యోగాన్ని ఆశ్రయించు — కర్మలలో నైపుణ్యమే యోగం.",
  hi: "इस बुद्धि से युक्त व्यक्ति यहीं पुण्य और पाप दोनों से ऊपर उठ जाता है। इसलिए योग में लग जाओ — कर्मों में कुशलता ही योग है।"
},
"gita_ch2_v51": {
  en: "The wise, joined with this understanding, give up the fruits born of action; freed from the bondage of birth, they reach the state beyond all sorrow.",
  te: "ఈ బుద్ధితో కూడిన జ్ఞానులు కర్మల నుండి పుట్టే ఫలాన్ని విడిచిపెట్టి, జన్మబంధం నుండి విముక్తులై, ఏ దుఃఖమూ లేని పరమపదాన్ని చేరుకుంటారు.",
  hi: "इस बुद्धि से युक्त ज्ञानी कर्म से उत्पन्न फल को त्यागकर, जन्म के बंधन से मुक्त होकर, दुःखरहित परम पद को प्राप्त होते हैं।"
},
"gita_ch2_v52": {
  en: "When your understanding crosses beyond the thicket of delusion, you will become indifferent to all that you have heard and all that is yet to be heard.",
  te: "నీ బుద్ధి మోహమనే దట్టమైన పొదను దాటినప్పుడు, ఇంతవరకు విన్నదాని పట్లా, ఇకముందు వినబోయేదాని పట్లా నీకు వైరాగ్యం కలుగుతుంది.",
  hi: "जब तुम्हारी बुद्धि मोह की दलदल को पार कर लेगी, तब तुम सुने हुए और सुने जाने वाले सब विषयों से विरक्त हो जाओगे।"
},
"gita_ch2_v53": {
  en: "When your mind, now confused by many conflicting teachings, stands firm and unmoving in meditation, then you will attain yoga.",
  te: "రకరకాల శాస్త్రవాక్యాలు విని కలవరపడిన నీ బుద్ధి, ఎప్పుడు కదలకుండా స్థిరంగా సమాధిలో నిలుస్తుందో, అప్పుడు నువ్వు యోగాన్ని పొందుతావు.",
  hi: "अनेक प्रकार की बातें सुनकर भ्रमित हुई तुम्हारी बुद्धि जब समाधि में अचल और स्थिर हो जाएगी, तब तुम योग को प्राप्त करोगे।"
},
"gita_ch2_v54": {
  en: "Arjuna said: Keśava, what are the marks of one whose wisdom is steady, who is established in meditation? How does such a person speak, how do they sit, how do they walk?",
  te: "అర్జునుడు అన్నాడు: కేశవా! సమాధిలో నిలిచిన స్థితప్రజ్ఞుని లక్షణాలు ఏమిటి? స్థిరబుద్ధి గలవాడు ఎలా మాట్లాడతాడు, ఎలా కూర్చుంటాడు, ఎలా నడుచుకుంటాడు?",
  hi: "अर्जुन ने कहा: हे केशव! समाधि में स्थित स्थितप्रज्ञ के क्या लक्षण हैं? स्थिर बुद्धि वाला कैसे बोलता है, कैसे बैठता है, कैसे चलता है?"
},
"gita_ch2_v55": {
  en: "The Lord said: Pārtha, when a person gives up all the desires that arise in the mind and is content in the Self by the Self alone, then they are called one of steady wisdom.",
  te: "శ్రీ భగవానుడు అన్నాడు: పార్థా! మనసులో పుట్టే కోరికలన్నిటినీ విడిచిపెట్టి, తనలో తానే తృప్తిగా ఉండేవాడిని స్థితప్రజ్ఞుడు అంటారు.",
  hi: "श्री भगवान ने कहा: हे पार्थ! जब मनुष्य मन में उठने वाली सब कामनाओं को त्याग देता है और अपने आप में ही संतुष्ट रहता है, तब वह स्थितप्रज्ञ कहलाता है।"
},
"gita_ch2_v56": {
  en: "One whose mind is not shaken by sorrows, who does not crave pleasures, and who is free from attachment, fear and anger — such a sage is called one of steady mind.",
  te: "దుఃఖాలలో కలవరపడని మనసు గలవాడు, సుఖాల కోసం ఆరాటపడనివాడు, రాగం, భయం, కోపం లేనివాడు — అలాంటి మునిని స్థిరబుద్ధి గలవాడు అంటారు.",
  hi: "जिसका मन दुःखों में विचलित नहीं होता, जो सुखों की लालसा नहीं करता, और जो राग, भय और क्रोध से मुक्त है — वह मुनि स्थिरबुद्धि कहलाता है।"
},
"gita_ch2_v57": {
  en: "One who is unattached everywhere, who neither rejoices on getting what is pleasant nor hates what is unpleasant — that person's wisdom is firmly established.",
  te: "ఎక్కడా అతిగా అంటిపెట్టుకోనివాడు, మంచి జరిగినప్పుడు పొంగిపోనివాడు, చెడు జరిగినప్పుడు ద్వేషించనివాడు — అతని ప్రజ్ఞ స్థిరమైనది.",
  hi: "जो सब जगह आसक्ति रहित है, जो शुभ पाकर न हर्षित होता है और न अशुभ से द्वेष करता है — उसकी बुद्धि स्थिर है।"
},
"gita_ch2_v58": {
  en: "When one can withdraw the senses from their objects completely, as a tortoise draws in its limbs, then that person's wisdom is firmly established.",
  te: "తాబేలు తన అవయవాలను లోపలికి ముడుచుకున్నట్లు, ఎవరు తన ఇంద్రియాలను విషయాల నుండి పూర్తిగా వెనక్కి తీసుకోగలరో, వారి ప్రజ్ఞ స్థిరమైనది.",
  hi: "जैसे कछुआ अपने अंगों को भीतर समेट लेता है, वैसे ही जब मनुष्य अपनी इंद्रियों को विषयों से पूरी तरह हटा लेता है, तब उसकी बुद्धि स्थिर होती है।"
},
"gita_ch2_v59": {
  en: "When a person stops feeding the senses, the objects fall away, but the taste for them remains. Even that taste disappears once the Supreme is seen.",
  te: "ఇంద్రియాలకు ఆహారం ఇవ్వడం మానేస్తే విషయాలు దూరమవుతాయి, కానీ వాటిపై రుచి (ఆసక్తి) మిగిలే ఉంటుంది. పరమాత్మను దర్శించిన తర్వాత ఆ రుచి కూడా పోతుంది.",
  hi: "इंद्रियों को विषय न देने से विषय तो छूट जाते हैं, पर उनका रस (लालसा) बना रहता है। परमात्मा का दर्शन होने पर वह रस भी मिट जाता है।"
},
"gita_ch2_v60": {
  en: "Son of Kuntī, the turbulent senses forcibly carry away the mind even of a wise person who is striving.",
  te: "కౌంతేయా! ప్రయత్నిస్తున్న వివేకవంతుని మనసును కూడా అల్లకల్లోలం చేసే ఇంద్రియాలు బలవంతంగా లాక్కుపోతాయి.",
  hi: "हे कौंतेय! प्रयत्न करते हुए बुद्धिमान पुरुष के मन को भी ये उपद्रवी इंद्रियाँ बलपूर्वक हर ले जाती हैं।"
},
"gita_ch2_v61": {
  en: "Restraining them all, one should sit in yoga, devoted to Me. For one whose senses are under control, wisdom is firmly established.",
  te: "వాటన్నిటినీ అదుపులో పెట్టుకుని, నన్నే పరమంగా భావిస్తూ యోగంలో కూర్చోవాలి. ఎవరి ఇంద్రియాలు వశంలో ఉంటాయో, వారి ప్రజ్ఞ స్థిరమైనది.",
  hi: "उन सबको वश में करके, मुझे परम मानकर योग में बैठना चाहिए। जिसकी इंद्रियाँ वश में हैं, उसकी बुद्धि स्थिर है।"
},
"gita_ch2_v62": {
  en: "When a person keeps thinking about sense objects, attachment to them grows. From attachment comes desire, and from desire comes anger.",
  te: "విషయాల గురించే ఆలోచిస్తూ ఉండే మనిషికి వాటిపై ఆసక్తి పుడుతుంది. ఆసక్తి నుండి కోరిక పుడుతుంది; కోరిక నుండి కోపం పుడుతుంది.",
  hi: "विषयों का चिंतन करते रहने से मनुष्य को उनमें आसक्ति हो जाती है। आसक्ति से कामना पैदा होती है, और कामना से क्रोध।"
},
"gita_ch2_v63": {
  en: "From anger comes delusion; from delusion, loss of memory; from loss of memory, the ruin of judgement; and with judgement ruined, one is destroyed.",
  te: "కోపం నుండి మోహం (అవివేకం) కలుగుతుంది; మోహం నుండి జ్ఞాపకశక్తి చెదిరిపోతుంది; జ్ఞాపకం చెదిరితే బుద్ధి నశిస్తుంది; బుద్ధి నశిస్తే మనిషి పతనమవుతాడు.",
  hi: "क्रोध से मोह (भ्रम) होता है, मोह से स्मृति भ्रमित होती है, स्मृति भ्रष्ट होने से बुद्धि का नाश होता है, और बुद्धि के नाश से मनुष्य का पतन हो जाता है।"
},
"gita_ch2_v64": {
  en: "But one who moves among sense objects with senses under control, free from attraction and aversion, and who is self-disciplined, attains inner peace.",
  te: "కానీ రాగద్వేషాలు లేకుండా, తన వశంలో ఉన్న ఇంద్రియాలతో విషయాల మధ్య తిరుగుతూ, మనసును అదుపులో ఉంచుకున్నవాడు ప్రశాంతతను (ప్రసాదాన్ని) పొందుతాడు.",
  hi: "परंतु जो राग-द्वेष से रहित, वश में की हुई इंद्रियों से विषयों के बीच विचरता है और जिसका मन संयमित है, वह प्रसन्नता (आंतरिक शांति) प्राप्त करता है।"
},
"gita_ch2_v65": {
  en: "In that peace, all sorrows come to an end; for the mind of one who is at peace soon becomes steady.",
  te: "ఆ ప్రశాంతతలో అతని దుఃఖాలన్నీ తొలగిపోతాయి. ప్రసన్నమైన మనసు గలవాని బుద్ధి త్వరగా స్థిరపడుతుంది.",
  hi: "उस प्रसन्नता में उसके सब दुःखों का अंत हो जाता है; क्योंकि प्रसन्न चित्त वाले की बुद्धि शीघ्र ही स्थिर हो जाती है।"
},
"gita_ch2_v66": {
  en: "One who is not disciplined has no steady understanding and no deep contemplation. Without contemplation there is no peace, and without peace, how can there be happiness?",
  te: "మనసును అదుపులో పెట్టుకోనివానికి స్థిరమైన బుద్ధి ఉండదు, ధ్యానభావమూ ఉండదు. ధ్యానం లేనివానికి శాంతి లేదు; శాంతి లేనివానికి సుఖం ఎక్కడిది?",
  hi: "जो संयमी नहीं है, उसकी बुद्धि स्थिर नहीं होती और न ही उसमें ध्यान का भाव होता है। ध्यान के बिना शांति नहीं, और अशांत को सुख कहाँ?"
},
"gita_ch2_v67": {
  en: "When the mind follows the wandering senses, it carries away one's wisdom, just as the wind carries away a boat on the water.",
  te: "తిరుగుతున్న ఇంద్రియాల వెంట మనసు పరుగెత్తితే, గాలి నీటిలోని పడవను కొట్టుకుపోయేలా చేసినట్లు, అది మనిషి ప్రజ్ఞను లాక్కుపోతుంది.",
  hi: "जब मन भटकती इंद्रियों के पीछे चलता है, तो वह मनुष्य की बुद्धि को वैसे ही हर लेता है, जैसे हवा पानी में नाव को बहा ले जाती है।"
},
"gita_ch2_v68": {
  en: "Therefore, mighty-armed one, the one whose senses are fully withdrawn from their objects — that person's wisdom is firmly established.",
  te: "కాబట్టి మహాబాహూ! ఎవరి ఇంద్రియాలు విషయాల నుండి పూర్తిగా అదుపులో ఉంటాయో, వారి ప్రజ్ఞ స్థిరమైనది.",
  hi: "इसलिए हे महाबाहो! जिसकी इंद्रियाँ विषयों से पूरी तरह वश में हैं, उसकी बुद्धि स्थिर है।"
},
"gita_ch2_v69": {
  en: "What is night for all beings, the self-controlled one is awake in; and what all beings are awake in is night for the sage who sees.",
  te: "అందరికీ రాత్రిగా ఉన్నదానిలో సంయమి మేల్కొని ఉంటాడు; అందరూ మేల్కొని ఉన్నదానిని, తత్త్వం చూసే ముని రాత్రిగా భావిస్తాడు.",
  hi: "जो सब प्राणियों के लिए रात है, उसमें संयमी जागता है; और जिसमें सब प्राणी जागते हैं, वह तत्त्व को देखने वाले मुनि के लिए रात है।"
},
"gita_ch2_v70": {
  en: "As rivers flow into the ocean, which is ever being filled yet stays still within its bounds, so the one into whom all desires enter in the same way finds peace — not the one who chases desires.",
  te: "నదులు ఎన్ని వచ్చి చేరినా సముద్రం నిండుగా, తన హద్దుల్లో నిశ్చలంగా ఉంటుంది. అలాగే కోరికలన్నీ ఎవరిలోకి ప్రవేశించినా కదలకుండా ఉంటాడో, అతడే శాంతిని పొందుతాడు — కోరికల వెంట పరుగెత్తేవాడు కాదు.",
  hi: "जैसे नदियाँ उस समुद्र में आकर समा जाती हैं जो सब ओर से भरता रहकर भी अपनी मर्यादा में अचल रहता है, वैसे ही जिसमें सब कामनाएँ समा जाती हैं, वही शांति पाता है — कामनाओं के पीछे भागने वाला नहीं।"
},
"gita_ch2_v71": {
  en: "One who gives up all desires and moves about free from longing, without the sense of ‘mine’ and without ego, attains peace.",
  te: "కోరికలన్నిటినీ విడిచిపెట్టి, ఆశ లేకుండా, ‘నాది’ అనే మమకారం, ‘నేను’ అనే అహంకారం లేకుండా జీవించేవాడు శాంతిని పొందుతాడు.",
  hi: "जो मनुष्य सब कामनाओं को त्यागकर, लालसा रहित, ममता रहित और अहंकार रहित होकर विचरता है, वह शांति प्राप्त करता है।"
},
"gita_ch2_v72": {
  en: "This, Pārtha, is the state of Brahman. Having reached it, one is no longer deluded. Remaining in it even at the hour of death, one attains the freedom of Brahman.",
  te: "పార్థా! ఇదే బ్రాహ్మీ స్థితి. దీనిని పొందినవాడు మళ్ళీ మోహంలో పడడు. అంత్యకాలంలో కూడా ఈ స్థితిలో నిలిచినవాడు బ్రహ్మనిర్వాణాన్ని (మోక్షాన్ని) పొందుతాడు.",
  hi: "हे पार्थ! यही ब्राह्मी स्थिति है। इसे पाकर मनुष्य फिर मोहित नहीं होता। अंतकाल में भी इसमें स्थित रहकर वह ब्रह्मनिर्वाण (मोक्ष) प्राप्त करता है।"
},

// ── Chapter 3 · Karma Yoga ──
"gita_ch3_v1": {
  en: "Arjuna said: Janārdana, if You hold that understanding is better than action, then why, Keśava, do You push me into this terrible deed?",
  te: "అర్జునుడు అన్నాడు: జనార్దనా! కర్మ కంటే జ్ఞానమే శ్రేష్ఠమని నీ అభిప్రాయమైతే, కేశవా, మరి ఈ భయంకరమైన కర్మలో నన్నెందుకు దించుతున్నావు?",
  hi: "अर्जुन ने कहा: हे जनार्दन! यदि आपके मत में कर्म से ज्ञान श्रेष्ठ है, तो हे केशव, आप मुझे इस भयंकर कर्म में क्यों लगा रहे हैं?"
},
"gita_ch3_v2": {
  en: "Your mixed-sounding words seem to confuse my mind. So tell me clearly the one thing by which I may reach the highest good.",
  te: "కలగలిసినట్టున్న నీ మాటలతో నా బుద్ధి గందరగోళంలో పడుతోంది. నాకు శ్రేయస్సు కలిగే ఆ ఒక్క మార్గాన్ని నిశ్చయంగా చెప్పు.",
  hi: "आपके मिले-जुले से लगते वचनों से मेरी बुद्धि भ्रमित-सी हो रही है। इसलिए निश्चय करके वह एक बात बताइए जिससे मेरा कल्याण हो।"
},
"gita_ch3_v3": {
  en: "The Lord said: Sinless one, I have taught before that there are two paths in this world — the path of knowledge for those inclined to reflection, and the path of action for those inclined to work.",
  te: "శ్రీ భగవానుడు అన్నాడు: పాపరహితుడా! ఈ లోకంలో రెండు రకాల నిష్ఠలు ఉన్నాయని నేను ముందే చెప్పాను — విచారణ చేసేవారికి జ్ఞానయోగం, కర్మ చేసేవారికి కర్మయోగం.",
  hi: "श्री भगवान ने कहा: हे निष्पाप! इस संसार में दो प्रकार की निष्ठा मैंने पहले बताई है — चिंतनशील लोगों के लिए ज्ञानयोग और कर्मशील लोगों के लिए कर्मयोग।"
},
"gita_ch3_v4": {
  en: "A person does not reach freedom from action simply by not starting any work, nor does one attain perfection merely by giving things up.",
  te: "పని మొదలుపెట్టకుండా ఉండినంత మాత్రాన మనిషికి కర్మబంధం నుండి విముక్తి రాదు; కేవలం విడిచిపెట్టినంత మాత్రాన సిద్ధి కూడా లభించదు.",
  hi: "केवल कर्म आरंभ न करने से मनुष्य कर्म से मुक्त नहीं होता, और केवल त्याग कर देने से ही सिद्धि नहीं मिलती।"
},
"gita_ch3_v5": {
  en: "No one can remain even for a moment without doing something. Everyone is driven to act, whether they wish it or not, by the qualities born of nature.",
  te: "ఎవరూ ఒక్క క్షణమైనా ఏ పనీ చేయకుండా ఉండలేరు. ప్రకృతి నుండి పుట్టిన గుణాలు ప్రతి ఒక్కరినీ ఇష్టం ఉన్నా లేకపోయినా పని చేయిస్తాయి.",
  hi: "कोई भी एक क्षण भी बिना कुछ किए नहीं रह सकता। प्रकृति से उत्पन्न गुण हर किसी से, चाहे वह चाहे या न चाहे, कर्म करवाते हैं।"
},
"gita_ch3_v6": {
  en: "One who holds the organs of action still but sits dwelling in the mind on the objects of the senses is deluded, and is called a pretender.",
  te: "కర్మేంద్రియాలను బలవంతంగా ఆపి, మనసులో మాత్రం ఇంద్రియ విషయాలనే తలచుకుంటూ కూర్చునేవాడు మూఢుడు; వాణ్ణి కపటాచారి అంటారు.",
  hi: "जो कर्मेंद्रियों को रोककर बैठा रहता है पर मन में इंद्रियों के विषयों का ही चिंतन करता है, वह मूढ़ है और उसे पाखंडी कहा जाता है।"
},
"gita_ch3_v7": {
  en: "But one who controls the senses with the mind, Arjuna, and without attachment takes up the yoga of action with the organs of action — that person excels.",
  te: "కానీ అర్జునా! మనసుతో ఇంద్రియాలను అదుపులో ఉంచుకుని, ఆసక్తి లేకుండా కర్మేంద్రియాలతో కర్మయోగాన్ని ఆచరించేవాడే శ్రేష్ఠుడు.",
  hi: "परंतु हे अर्जुन! जो मन से इंद्रियों को वश में करके, आसक्ति के बिना कर्मेंद्रियों से कर्मयोग करता है, वही श्रेष्ठ है।"
},
"gita_ch3_v8": {
  en: "Do your prescribed duty, for action is better than inaction. Without action, even the upkeep of your body would not be possible.",
  te: "నీకు నిర్ణయించిన కర్తవ్యాన్ని చెయ్యి; పని చేయకపోవడం కంటే చేయడమే మేలు. పని లేకుండా నీ శరీర యాత్ర కూడా సాగదు.",
  hi: "तुम अपना नियत कर्म करो, क्योंकि कर्म न करने से कर्म करना श्रेष्ठ है। बिना कर्म के तो तुम्हारे शरीर का निर्वाह भी नहीं हो सकता।"
},
"gita_ch3_v9": {
  en: "This world is bound by action, except for action done as an offering (yajña). So, son of Kuntī, do your work for that purpose, free from attachment.",
  te: "యజ్ఞం కోసం (భగవదర్పణగా) చేసే కర్మ తప్ప మిగిలిన కర్మలన్నీ ఈ లోకాన్ని బంధిస్తాయి. కాబట్టి కౌంతేయా! ఆసక్తిని విడిచి ఆ భావంతోనే కర్మ చెయ్యి.",
  hi: "यज्ञ (अर्पण) के लिए किए गए कर्म के सिवा अन्य कर्मों से यह संसार बँधता है। इसलिए हे कौंतेय! आसक्ति छोड़कर उसी भाव से कर्म करो।"
},
"gita_ch3_v10": {
  en: "In the beginning, the Creator brought forth beings together with yajña and said: 'By this you shall prosper; let this be the giver of all you desire.'",
  te: "సృష్టి ప్రారంభంలో ప్రజాపతి యజ్ఞంతో పాటే ప్రజలను సృష్టించి ఇలా అన్నాడు: 'దీనివల్ల మీరు వృద్ధి చెందండి; ఇది మీరు కోరినవన్నీ ఇచ్చే కామధేనువు అగుగాక.'",
  hi: "सृष्टि के आरंभ में प्रजापति ने यज्ञ के साथ प्रजा को रचकर कहा: 'इससे तुम बढ़ो; यह तुम्हारी इच्छित वस्तुएँ देने वाली कामधेनु हो।'"
},
"gita_ch3_v11": {
  en: "'Nourish the gods with this, and let the gods nourish you. Nourishing one another, you will reach the highest good.'",
  te: "'దీనితో మీరు దేవతలను సంతోషపెట్టండి, ఆ దేవతలు మిమ్మల్ని పోషిస్తారు. ఇలా ఒకరినొకరు పోషించుకుంటూ మీరు పరమ శ్రేయస్సును పొందుతారు.'",
  hi: "'इससे तुम देवताओं को संतुष्ट करो और वे देवता तुम्हें संतुष्ट करें। इस प्रकार एक-दूसरे का पोषण करते हुए तुम परम कल्याण पाओगे।'"
},
"gita_ch3_v12": {
  en: "'Pleased by yajña, the gods will give you the enjoyments you desire.' One who enjoys their gifts without offering anything back to them is simply a thief.",
  te: "'యజ్ఞంతో సంతృప్తులైన దేవతలు మీరు కోరిన భోగాలను ఇస్తారు.' వారు ఇచ్చినవాటిని వారికి తిరిగి అర్పించకుండా తానే అనుభవించేవాడు నిజంగా దొంగే.",
  hi: "'यज्ञ से संतुष्ट देवता तुम्हें इच्छित भोग देंगे।' जो उनके दिए हुए को उन्हें अर्पित किए बिना स्वयं भोगता है, वह चोर ही है।"
},
"gita_ch3_v13": {
  en: "The good who eat what remains after the offering are freed from all wrongs. But the wicked who cook only for themselves eat sin.",
  te: "యజ్ఞం తర్వాత మిగిలినదాన్ని తినే సజ్జనులు అన్ని పాపాల నుండి విముక్తులవుతారు. కేవలం తమ కోసమే వండుకునే పాపులు పాపాన్నే తింటారు.",
  hi: "यज्ञ से बचा हुआ अन्न खाने वाले सज्जन सब पापों से छूट जाते हैं। पर जो केवल अपने लिए पकाते हैं, वे पापी पाप ही खाते हैं।"
},
"gita_ch3_v14": {
  en: "Living beings come from food; food comes from rain; rain comes from yajña; and yajña is born of action.",
  te: "అన్నం వల్ల ప్రాణులు పుడతాయి; వర్షం వల్ల అన్నం పండుతుంది; యజ్ఞం వల్ల వర్షం కురుస్తుంది; యజ్ఞం కర్మ నుండి పుడుతుంది.",
  hi: "अन्न से प्राणी उत्पन्न होते हैं; वर्षा से अन्न होता है; यज्ञ से वर्षा होती है; और यज्ञ कर्म से उत्पन्न होता है।"
},
"gita_ch3_v15": {
  en: "Know that action comes from the Veda, and the Veda comes from the Imperishable. Therefore the all-pervading Brahman is always present in yajña.",
  te: "కర్మ వేదం నుండి పుట్టిందని, వేదం అక్షర పరబ్రహ్మ నుండి వచ్చిందని తెలుసుకో. కాబట్టి సర్వవ్యాపకమైన బ్రహ్మం ఎల్లప్పుడూ యజ్ఞంలో నిలిచి ఉంది.",
  hi: "जानो कि कर्म वेद से उत्पन्न है और वेद अविनाशी परमात्मा से। इसलिए सर्वव्यापी ब्रह्म सदा यज्ञ में प्रतिष्ठित है।"
},
"gita_ch3_v16": {
  en: "One who does not help turn this wheel that has been set in motion, Pārtha, but lives for sensual pleasure in a sinful way, lives in vain.",
  te: "పార్థా! ఇలా తిరుగుతున్న ఈ చక్రాన్ని అనుసరించకుండా, ఇంద్రియ సుఖాలలోనే మునిగి పాపపు జీవితం గడిపేవాడి బ్రతుకు వ్యర్థం.",
  hi: "हे पार्थ! जो इस प्रकार चलाए गए चक्र के अनुसार नहीं चलता और इंद्रियों के सुख में डूबा पापमय जीवन जीता है, उसका जीना व्यर्थ है।"
},
"gita_ch3_v17": {
  en: "But for the person who delights only in the Self, is content in the Self and fully satisfied in the Self alone, there is no duty left to do.",
  te: "కానీ ఆత్మలోనే ఆనందించేవాడు, ఆత్మలోనే తృప్తి పొందేవాడు, ఆత్మలోనే సంతుష్టుడైన మనిషికి చేయవలసిన కర్తవ్యం అంటూ ఏదీ ఉండదు.",
  hi: "परंतु जो मनुष्य आत्मा में ही रमता है, आत्मा में ही तृप्त है और आत्मा में ही संतुष्ट है, उसके लिए कोई कर्तव्य शेष नहीं रहता।"
},
"gita_ch3_v18": {
  en: "Such a person gains nothing by acting and loses nothing by not acting in this world, and depends on no being for anything.",
  te: "అలాంటివాడికి ఈ లోకంలో పని చేయడం వల్ల పొందేదీ లేదు, చేయకపోవడం వల్ల పోయేదీ లేదు. ఏ ప్రాణిపైనా అతడు దేనికోసమూ ఆధారపడడు.",
  hi: "ऐसे व्यक्ति को इस संसार में न कर्म करने से कुछ पाना है, न न करने से कुछ खोना है; और उसे किसी प्राणी पर किसी बात के लिए निर्भर नहीं रहना पड़ता।"
},
"gita_ch3_v19": {
  en: "Therefore, always do the work that has to be done, without attachment. By working without attachment, a person reaches the Supreme.",
  te: "కాబట్టి ఆసక్తి లేకుండా చేయవలసిన పనిని ఎల్లప్పుడూ చక్కగా చెయ్యి. ఆసక్తి లేకుండా కర్మ చేసే మనిషి పరమాత్మను చేరుకుంటాడు.",
  hi: "इसलिए आसक्ति के बिना सदा अपना कर्तव्य कर्म भली-भाँति करो। आसक्ति रहित होकर कर्म करने वाला मनुष्य परमात्मा को पाता है।"
},
"gita_ch3_v20": {
  en: "Janaka and others reached perfection through action alone. And even just for the good and guidance of the world, you should act.",
  te: "జనకుడు మొదలైనవారు కర్మ ద్వారానే సిద్ధిని పొందారు. లోకహితం (లోకసంగ్రహం) దృష్టిలో ఉంచుకుని అయినా నువ్వు కర్మ చేయాలి.",
  hi: "जनक आदि ने कर्म के द्वारा ही सिद्धि प्राप्त की थी। लोक-कल्याण (लोकसंग्रह) को देखते हुए भी तुम्हें कर्म करना चाहिए।"
},
"gita_ch3_v21": {
  en: "Whatever a great person does, others follow. Whatever standard such a person sets, the world goes by it.",
  te: "శ్రేష్ఠుడు ఏది ఆచరిస్తాడో మిగిలినవారూ అదే చేస్తారు. అతడు దేనిని ప్రమాణంగా పెడతాడో లోకం దానినే అనుసరిస్తుంది.",
  hi: "श्रेष्ठ व्यक्ति जो-जो आचरण करता है, दूसरे लोग भी वैसा ही करते हैं। वह जो मानक स्थापित करता है, संसार उसी का अनुसरण करता है।"
},
"gita_ch3_v22": {
  en: "Pārtha, in all the three worlds there is nothing I have to do, nothing I lack and nothing I need to gain — and yet I go on working.",
  te: "పార్థా! మూడు లోకాలలోనూ నేను చేయవలసినది ఏదీ లేదు; నాకు లేనిదీ, పొందవలసినదీ ఏదీ లేదు — అయినా నేను కర్మలో నిమగ్నమై ఉంటాను.",
  hi: "हे पार्थ! तीनों लोकों में मेरा कोई कर्तव्य नहीं है, न कोई वस्तु अप्राप्त है जिसे मुझे पाना हो — फिर भी मैं कर्म में लगा रहता हूँ।"
},
"gita_ch3_v23": {
  en: "For if I ever stopped working tirelessly, Pārtha, people everywhere would follow my path.",
  te: "పార్థా! నేను ఎప్పుడైనా అలసట లేకుండా కర్మ చేయడం మానేస్తే, మనుషులందరూ అన్ని విధాలా నా మార్గాన్నే అనుసరిస్తారు.",
  hi: "हे पार्थ! यदि मैं कभी आलस्य छोड़कर कर्म में न लगा रहूँ, तो मनुष्य सब प्रकार से मेरे ही मार्ग का अनुसरण करेंगे।"
},
"gita_ch3_v24": {
  en: "If I did not act, these worlds would fall into ruin; I would be the cause of confusion and disorder, and would bring harm to all these beings.",
  te: "నేను కర్మ చేయకపోతే ఈ లోకాలన్నీ నశిస్తాయి; అస్తవ్యస్తతకు నేనే కారణమవుతాను, ఈ ప్రజలందరినీ నాశనం చేసినవాడినవుతాను.",
  hi: "यदि मैं कर्म न करूँ तो ये सब लोक नष्ट हो जाएँ; मैं अव्यवस्था (संकर) का कारण बनूँ और इन सब प्रजाओं का नाश करने वाला हो जाऊँ।"
},
"gita_ch3_v25": {
  en: "Bhārata, just as the unwise work with attachment, the wise should work just as hard, but without attachment, wishing for the good of the world.",
  te: "భారతా! అజ్ఞానులు ఆసక్తితో ఎలా కర్మ చేస్తారో, జ్ఞాని కూడా లోకహితాన్ని కోరుతూ, ఆసక్తి లేకుండా అలాగే కర్మ చేయాలి.",
  hi: "हे भारत! जैसे अज्ञानी आसक्त होकर कर्म करते हैं, वैसे ही ज्ञानी को लोक-कल्याण की इच्छा से, आसक्ति रहित होकर कर्म करना चाहिए।"
},
"gita_ch3_v26": {
  en: "The wise should not unsettle the minds of the unknowing who are attached to their work. Instead, working steadily themselves, they should inspire others to do all their duties well.",
  te: "కర్మలపై ఆసక్తి ఉన్న అజ్ఞానుల బుద్ధిని జ్ఞాని కలవరపెట్టకూడదు. తానే యోగయుక్తుడై చక్కగా కర్మలు చేస్తూ, వారితోనూ అన్ని కర్మలను ప్రీతిగా చేయించాలి.",
  hi: "ज्ञानी को कर्म में आसक्त अज्ञानियों की बुद्धि में भ्रम नहीं पैदा करना चाहिए। बल्कि स्वयं योगयुक्त होकर अच्छी तरह कर्म करते हुए उन्हें भी सब कर्मों में लगाए रखना चाहिए।"
},
"gita_ch3_v27": {
  en: "All actions are in truth carried out by the qualities (guṇas) of nature. But one whose mind is clouded by ego thinks, 'I am the doer.'",
  te: "నిజానికి అన్ని కర్మలూ ప్రకృతి గుణాల చేతనే జరుగుతున్నాయి. కానీ అహంకారంతో మోహితుడైనవాడు 'నేనే కర్తను' అనుకుంటాడు.",
  hi: "वास्तव में सब कर्म प्रकृति के गुणों द्वारा किए जाते हैं। परंतु अहंकार से मोहित व्यक्ति मानता है कि 'मैं कर्ता हूँ'।"
},
"gita_ch3_v28": {
  en: "But one who knows the truth about the guṇas and their workings, mighty-armed one, understands that it is the guṇas acting among the guṇas, and so is not attached.",
  te: "కానీ మహాబాహూ! గుణాల గురించి, వాటి కర్మల విభాగం గురించి తత్త్వం తెలిసినవాడు 'గుణాలు గుణాలలోనే వర్తిస్తున్నాయి' అని గ్రహించి ఆసక్తుడు కాడు.",
  hi: "परंतु हे महाबाहो! गुणों और कर्मों के विभाग का तत्त्व जानने वाला समझता है कि 'गुण ही गुणों में बरत रहे हैं', और इसलिए आसक्त नहीं होता।"
},
"gita_ch3_v29": {
  en: "Those deluded by the guṇas of nature get attached to the works of the guṇas. One who knows the whole truth should not disturb these people of partial understanding.",
  te: "ప్రకృతి గుణాలతో మోహితులైనవారు గుణకర్మలలో ఆసక్తులవుతారు. అన్నీ తెలిసిన జ్ఞాని, సగం మాత్రమే తెలిసిన ఆ మందబుద్ధులను కలవరపెట్టకూడదు.",
  hi: "प्रकृति के गुणों से मोहित लोग गुणों के कर्मों में आसक्त होते हैं। पूरा सत्य जानने वाला ज्ञानी उन अधूरी समझ वाले लोगों को विचलित न करे।"
},
"gita_ch3_v30": {
  en: "Offer all your actions to Me, with your mind on the Self. Free from craving and from 'mine', and with the fever of grief gone, fight.",
  te: "ఆత్మ మీద మనసు నిలిపి, నీ కర్మలన్నిటినీ నాకు అర్పించు. ఆశ లేకుండా, 'నాది' అనే మమకారం లేకుండా, మనోవ్యాకులత విడిచి యుద్ధం చెయ్యి.",
  hi: "अपना मन आत्मा में लगाकर सारे कर्म मुझे अर्पित कर दो। आशा और ममता से रहित होकर, और मन का संताप छोड़कर युद्ध करो।"
},
"gita_ch3_v31": {
  en: "Those who always follow this teaching of Mine with faith and without finding fault are also freed from the bondage of action.",
  te: "శ్రద్ధతో, దోషదృష్టి లేకుండా నా ఈ ఉపదేశాన్ని నిత్యం ఆచరించే మనుషులు కూడా కర్మబంధం నుండి విముక్తులవుతారు.",
  hi: "जो मनुष्य श्रद्धा के साथ और दोष देखे बिना मेरे इस मत का सदा पालन करते हैं, वे भी कर्मों के बंधन से छूट जाते हैं।"
},
"gita_ch3_v32": {
  en: "But those who find fault with this teaching and do not follow it — know them to be confused about all knowledge, without discernment, and lost.",
  te: "కానీ నా ఈ బోధలో దోషాలు వెతుకుతూ దానిని ఆచరించనివారు — వారు సర్వజ్ఞానం విషయంలో మూఢులని, వివేకం లేనివారని, నశించినవారని తెలుసుకో.",
  hi: "परंतु जो इस मत में दोष निकालते हुए इसका पालन नहीं करते — उन्हें सब ज्ञान में भ्रमित, विवेकहीन और नष्ट हुआ जानो।"
},
"gita_ch3_v33": {
  en: "Even a wise person acts according to their own nature. All beings follow their nature — what will mere suppression achieve?",
  te: "జ్ఞాని కూడా తన స్వభావానికి తగినట్టే ప్రవర్తిస్తాడు. ప్రాణులన్నీ తమ ప్రకృతినే అనుసరిస్తాయి — బలవంతంగా అణచిపెడితే ఏం లాభం?",
  hi: "ज्ञानी भी अपनी प्रकृति के अनुसार ही चेष्टा करता है। सभी प्राणी अपनी प्रकृति के अनुसार चलते हैं — केवल दबाने से क्या होगा?"
},
"gita_ch3_v34": {
  en: "Liking and disliking lie in wait in every sense for its objects. Do not come under their power, for they are enemies on one's path.",
  te: "ప్రతి ఇంద్రియానికీ దాని విషయాల పట్ల ఇష్టం, అయిష్టం (రాగద్వేషాలు) పొంచి ఉంటాయి. వాటికి లొంగిపోకు; అవి మనిషి దారిలో అడ్డుపడే శత్రువులు.",
  hi: "हर इंद्रिय के अपने विषयों में राग और द्वेष छिपे रहते हैं। उनके वश में मत होओ, क्योंकि वे मनुष्य के मार्ग के शत्रु हैं।"
},
"gita_ch3_v35": {
  en: "Better is one's own duty, even done imperfectly, than another's duty done well. Better even to die in one's own duty; the duty of another is full of fear.",
  te: "చక్కగా చేసిన పరధర్మం కంటే, లోపాలతో చేసినా స్వధర్మమే మేలు. స్వధర్మంలో మరణించినా శ్రేయస్కరమే; పరధర్మం భయాన్ని కలిగిస్తుంది.",
  hi: "भली-भाँति किए गए पराए धर्म से, कमियों वाला अपना धर्म श्रेष्ठ है। अपने धर्म में मरना भी कल्याणकारी है; पराया धर्म भय देने वाला है।"
},
"gita_ch3_v36": {
  en: "Arjuna said: Then what drives a person to do wrong, Vārṣṇeya, even against their own wish, as if pushed by force?",
  te: "అర్జునుడు అన్నాడు: వార్ష్ణేయా! మరి మనిషి తనకు ఇష్టం లేకపోయినా, ఎవరో బలవంతంగా నెట్టినట్టు, దేని ప్రేరణతో పాపం చేస్తాడు?",
  hi: "अर्जुन ने कहा: हे वार्ष्णेय! तो फिर मनुष्य न चाहते हुए भी, मानो बलपूर्वक लगाया गया हो, किसकी प्रेरणा से पाप करता है?"
},
"gita_ch3_v37": {
  en: "The Lord said: It is desire, it is anger, born of the quality of rajas — all-devouring and greatly sinful. Know this to be the enemy here.",
  te: "శ్రీ భగవానుడు అన్నాడు: అది కామమే, అది క్రోధమే — రజోగుణం నుండి పుట్టినది. ఎంత తిన్నా తీరని, మహాపాపకారి అయిన దీనినే ఇక్కడ శత్రువుగా తెలుసుకో.",
  hi: "श्री भगवान ने कहा: यह काम है, यह क्रोध है, जो रजोगुण से उत्पन्न होता है। यह कभी तृप्त न होने वाला और महापापी है — इसे ही यहाँ शत्रु जानो।"
},
"gita_ch3_v38": {
  en: "As fire is covered by smoke, a mirror by dust, and an unborn child by the womb, so is this (knowledge) covered by desire.",
  te: "పొగతో అగ్ని, దుమ్ముతో అద్దం, మావితో గర్భంలోని శిశువు ఎలా కప్పబడి ఉంటాయో, అలాగే కామంతో ఈ జ్ఞానం కప్పబడి ఉంది.",
  hi: "जैसे धुएँ से अग्नि, धूल से दर्पण और झिल्ली से गर्भ ढका रहता है, वैसे ही काम से यह (ज्ञान) ढका रहता है।"
},
"gita_ch3_v39": {
  en: "Son of Kuntī, the wisdom of even the wise is covered by this constant enemy in the form of desire, which is like a fire that can never be filled.",
  te: "కౌంతేయా! ఎన్నటికీ నిండని అగ్ని లాంటి, జ్ఞానులకు నిత్య శత్రువైన ఈ కామరూపం చేత జ్ఞానుల జ్ఞానం కూడా కప్పబడి ఉంటుంది.",
  hi: "हे कौंतेय! कभी तृप्त न होने वाली अग्नि के समान, ज्ञानियों के नित्य शत्रु इस कामरूप से ज्ञानियों का ज्ञान भी ढका रहता है।"
},
"gita_ch3_v40": {
  en: "The senses, the mind and the intellect are said to be its hiding places. Through them it covers knowledge and deludes the embodied soul.",
  te: "ఇంద్రియాలు, మనసు, బుద్ధి — ఇవే దీని నివాస స్థానాలని చెబుతారు. వీటి ద్వారానే ఇది జ్ఞానాన్ని కప్పి దేహంలో ఉన్న జీవుణ్ణి మోహింపజేస్తుంది.",
  hi: "इंद्रियाँ, मन और बुद्धि इसके निवास-स्थान कहे जाते हैं। इन्हीं के द्वारा यह ज्ञान को ढककर देहधारी जीव को मोहित करता है।"
},
"gita_ch3_v41": {
  en: "Therefore, best of the Bharatas, first bring your senses under control, and then strike down this sinful thing that destroys knowledge and wisdom.",
  te: "కాబట్టి భరతశ్రేష్ఠా! ముందుగా ఇంద్రియాలను అదుపులోకి తెచ్చుకుని, జ్ఞానవిజ్ఞానాలను నాశనం చేసే ఈ పాపిష్ఠి కామాన్ని నిర్మూలించు.",
  hi: "इसलिए हे भरतश्रेष्ठ! पहले इंद्रियों को वश में करके ज्ञान और विज्ञान का नाश करने वाले इस पापी काम को मार डालो।"
},
"gita_ch3_v42": {
  en: "The senses are said to be higher than the body; the mind is higher than the senses; the intellect is higher than the mind; and higher than the intellect is He — the Self.",
  te: "శరీరం కంటే ఇంద్రియాలు గొప్పవి అంటారు; ఇంద్రియాల కంటే మనసు గొప్పది; మనసు కంటే బుద్ధి గొప్పది; బుద్ధి కంటే గొప్పది ఆత్మ.",
  hi: "कहते हैं कि इंद्रियाँ (शरीर से) सूक्ष्म और श्रेष्ठ हैं; इंद्रियों से मन श्रेष्ठ है; मन से बुद्धि श्रेष्ठ है; और जो बुद्धि से भी परे है, वह आत्मा है।"
},
"gita_ch3_v43": {
  en: "Thus knowing the Self to be beyond the intellect, and steadying the mind by the Self, mighty-armed one, slay this enemy in the form of desire, so hard to overcome.",
  te: "ఇలా బుద్ధి కంటే అతీతమైన ఆత్మను తెలుసుకుని, ఆత్మబలంతో మనసును స్థిరపరచుకుని, మహాబాహూ! జయించడానికి కష్టమైన కామరూపమనే ఈ శత్రువును సంహరించు.",
  hi: "इस प्रकार बुद्धि से परे आत्मा को जानकर, आत्मा के बल से मन को स्थिर करके, हे महाबाहो! इस कठिनाई से जीते जाने वाले कामरूपी शत्रु को मार डालो।"
},

// ── Chapter 4 · Jñāna Yoga ──
"gita_ch4_v1": {
  en: "The Lord said: I taught this imperishable yoga to Vivasvān, the Sun; Vivasvān passed it on to Manu, and Manu told it to Ikṣvāku.",
  te: "శ్రీ భగవానుడు అన్నాడు: నాశనం లేని ఈ యోగాన్ని నేను సూర్యుడైన వివస్వంతునికి ఉపదేశించాను; వివస్వంతుడు మనువుకు చెప్పాడు, మనువు ఇక్ష్వాకునికి చెప్పాడు.",
  hi: "श्री भगवान ने कहा: यह अविनाशी योग मैंने सूर्यदेव विवस्वान को सिखाया; विवस्वान ने इसे मनु को बताया और मनु ने इक्ष्वाकु को।"
},
"gita_ch4_v2": {
  en: "Handed down in this way from one to the next, the royal sages knew it. But over a very long stretch of time, Parantapa, this yoga was lost to the world.",
  te: "ఇలా గురుశిష్య పరంపరగా వచ్చిన ఈ యోగాన్ని రాజర్షులు తెలుసుకున్నారు. కానీ పరంతపా, చాలా కాలం గడిచేసరికి ఈ లోకంలో ఈ యోగం కనుమరుగైపోయింది.",
  hi: "इस प्रकार परंपरा से मिले इस योग को राजर्षियों ने जाना। परंतु हे परंतप, बहुत लंबा समय बीतने पर यह योग इस संसार में लुप्त हो गया।"
},
"gita_ch4_v3": {
  en: "That same ancient yoga I have taught you today, because you are My devotee and My friend. This is indeed the highest secret.",
  te: "అదే ప్రాచీనమైన యోగాన్ని ఈ రోజు నేను నీకు చెప్పాను, ఎందుకంటే నువ్వు నా భక్తుడివి, నా స్నేహితుడివి. ఇది నిజంగా అత్యుత్తమమైన రహస్యం.",
  hi: "वही प्राचीन योग आज मैंने तुम्हें बताया है, क्योंकि तुम मेरे भक्त और मित्र हो। यह सचमुच उत्तम रहस्य है।"
},
"gita_ch4_v4": {
  en: "Arjuna said: Your birth is recent, and Vivasvān's birth was long ago. How am I to understand that You taught it to him in the beginning?",
  te: "అర్జునుడు అన్నాడు: నీ జన్మ ఇటీవలిది, వివస్వంతుని జన్మ ఎప్పుడో పూర్వకాలానిది. మరి మొదట్లో నువ్వే అతనికి చెప్పావని నేనెలా అర్థం చేసుకోవాలి?",
  hi: "अर्जुन ने कहा: आपका जन्म तो अभी हाल का है और विवस्वान का जन्म बहुत पहले हुआ। फिर मैं कैसे समझूँ कि आपने ही आरंभ में उन्हें यह बताया था?"
},
"gita_ch4_v5": {
  en: "The Lord said: Many births of Mine have passed, Arjuna, and many of yours as well. I know them all, but you do not know them, Parantapa.",
  te: "శ్రీ భగవానుడు అన్నాడు: అర్జునా, నాకూ నీకూ ఎన్నో జన్మలు గడిచిపోయాయి. అవన్నీ నాకు తెలుసు; కానీ పరంతపా, నీకు అవి తెలియవు.",
  hi: "श्री भगवान ने कहा: हे अर्जुन, मेरे और तुम्हारे भी बहुत से जन्म बीत चुके हैं। मैं उन सबको जानता हूँ, पर हे परंतप, तुम उन्हें नहीं जानते।"
},
"gita_ch4_v6": {
  en: "Though I am unborn and My Self never perishes, though I am the Lord of all beings, I take My stand on My own nature and come into being through My own divine power.",
  te: "నేను పుట్టుక లేనివాడినైనా, నాశనం లేని ఆత్మస్వరూపుడినైనా, సర్వ ప్రాణులకూ ప్రభువునైనా — నా ప్రకృతిని ఆధారంగా చేసుకొని నా స్వంత మాయాశక్తితో అవతరిస్తాను.",
  hi: "यद्यपि मैं अजन्मा हूँ, मेरा स्वरूप अविनाशी है और मैं सब प्राणियों का ईश्वर हूँ, फिर भी अपनी प्रकृति को अधीन रखकर अपनी ही दिव्य शक्ति से प्रकट होता हूँ।"
},
"gita_ch4_v7": {
  en: "Whenever dharma declines and adharma rises up, Bhārata, then I bring Myself forth.",
  te: "భారతా! ఎప్పుడెప్పుడు ధర్మం క్షీణించి అధర్మం పెచ్చుమీరుతుందో, అప్పుడప్పుడు నన్ను నేను సృష్టించుకుంటాను.",
  hi: "हे भारत! जब-जब धर्म की हानि होती है और अधर्म बढ़ता है, तब-तब मैं स्वयं को प्रकट करता हूँ।"
},
"gita_ch4_v8": {
  en: "To protect the good, to destroy those who do evil, and to firmly re-establish dharma, I come into being age after age.",
  te: "సజ్జనులను రక్షించడానికి, దుష్టులను నాశనం చేయడానికి, ధర్మాన్ని మళ్ళీ స్థిరంగా నిలబెట్టడానికి నేను యుగయుగాన అవతరిస్తాను.",
  hi: "सज्जनों की रक्षा के लिए, दुष्टों के विनाश के लिए और धर्म को फिर से स्थापित करने के लिए मैं युग-युग में प्रकट होता हूँ।"
},
"gita_ch4_v9": {
  en: "Whoever truly understands My divine birth and actions, Arjuna, does not take birth again after leaving the body — that person comes to Me.",
  te: "అర్జునా! నా దివ్యమైన జన్మను, కర్మలను ఉన్నది ఉన్నట్టుగా తెలుసుకున్నవాడు శరీరం విడిచిన తర్వాత మళ్ళీ పుట్టడు — నన్నే చేరుకుంటాడు.",
  hi: "हे अर्जुन! जो मेरे दिव्य जन्म और कर्म को तत्त्व से जान लेता है, वह शरीर छोड़ने के बाद फिर जन्म नहीं लेता — वह मुझे ही प्राप्त होता है।"
},
"gita_ch4_v10": {
  en: "Free from craving, fear and anger, absorbed in Me and taking refuge in Me, many have been purified by the discipline of knowledge and have reached My state of being.",
  te: "రాగం, భయం, కోపం విడిచిపెట్టి, నాలోనే లీనమై, నన్నే ఆశ్రయించిన ఎంతోమంది జ్ఞానమనే తపస్సుతో పవిత్రులై నా స్వరూపాన్ని పొందారు.",
  hi: "आसक्ति, भय और क्रोध से रहित, मुझमें मन लगाए और मेरी शरण में आए अनेक लोग ज्ञानरूपी तप से पवित्र होकर मेरे स्वरूप को प्राप्त हुए हैं।"
},
"gita_ch4_v11": {
  en: "In whatever way people approach Me, in that same way I respond to them. Everywhere, Pārtha, people are following My path.",
  te: "ఎవరు నన్ను ఏ విధంగా ఆశ్రయిస్తారో, వారిని నేను అదే విధంగా అనుగ్రహిస్తాను. పార్థా, మనుషులందరూ అన్ని విధాలా నా మార్గాన్నే అనుసరిస్తున్నారు.",
  hi: "जो लोग जिस भाव से मेरी शरण लेते हैं, मैं उन्हें उसी भाव से अपनाता हूँ। हे पार्थ, सब मनुष्य हर प्रकार से मेरे ही मार्ग पर चलते हैं।"
},
"gita_ch4_v12": {
  en: "Those who want success in their works worship the gods here, because in the human world success born of action comes quickly.",
  te: "కర్మలకు ఫలం కోరుకునేవారు ఇక్కడ దేవతలను పూజిస్తారు, ఎందుకంటే మనుషుల లోకంలో కర్మల వల్ల కలిగే ఫలం త్వరగా లభిస్తుంది.",
  hi: "जो कर्मों का फल चाहते हैं वे यहाँ देवताओं की पूजा करते हैं, क्योंकि मनुष्य-लोक में कर्म से मिलने वाली सफलता जल्दी मिलती है।"
},
"gita_ch4_v13": {
  en: "The fourfold order of society was created by Me according to people's qualities and work. Though I am its maker, know Me as the changeless one who does not act.",
  te: "గుణాలను, కర్మలను బట్టి నాలుగు వర్ణాల వ్యవస్థను నేనే సృష్టించాను. దానికి కర్తనైనా, నన్ను మార్పులేని, అకర్తగా తెలుసుకో.",
  hi: "गुणों और कर्मों के विभाग के अनुसार चार वर्णों की व्यवस्था मैंने ही रची है। उसका कर्ता होकर भी मुझे अविनाशी और अकर्ता ही जानो।"
},
"gita_ch4_v14": {
  en: "Actions do not stain Me, nor do I long for their fruits. One who knows Me in this way is not bound by actions.",
  te: "కర్మలు నన్ను అంటవు; కర్మఫలంపై నాకు కోరిక లేదు. నన్ను ఈ విధంగా తెలుసుకున్నవాడు కర్మలతో బంధింపబడడు.",
  hi: "कर्म मुझे लिप्त नहीं करते और न मुझे कर्मफल की इच्छा है। जो मुझे इस प्रकार जानता है, वह कर्मों से नहीं बँधता।"
},
"gita_ch4_v15": {
  en: "Knowing this, the seekers of freedom in olden times also did their work. So you too should act, just as the ancients did long before.",
  te: "ఇది తెలుసుకొనే పూర్వకాలంలో ముక్తిని కోరినవారు కూడా కర్మలు చేశారు. అందుచేత నువ్వు కూడా పూర్వికులు చేసినట్లే కర్మ చెయ్యి.",
  hi: "यह जानकर प्राचीन काल के मुक्ति चाहने वालों ने भी कर्म किया। इसलिए तुम भी वैसे ही कर्म करो जैसे पूर्वजों ने पहले किया था।"
},
"gita_ch4_v16": {
  en: "What is action and what is inaction? Even the wise are puzzled here. So I will explain action to you; knowing it, you will be freed from all harm.",
  te: "కర్మ అంటే ఏమిటి, అకర్మ అంటే ఏమిటి? ఈ విషయంలో జ్ఞానులు కూడా తికమకపడతారు. అందుకే కర్మ గురించి నీకు చెబుతాను; అది తెలుసుకొని నువ్వు అశుభం నుండి విడుదల పొందుతావు.",
  hi: "कर्म क्या है और अकर्म क्या है? इस विषय में ज्ञानी भी भ्रमित हो जाते हैं। इसलिए मैं तुम्हें कर्म के बारे में बताऊँगा, जिसे जानकर तुम अशुभ से मुक्त हो जाओगे।"
},
"gita_ch4_v17": {
  en: "One must understand what right action is, what wrong action is, and what inaction is — for the way of action is deep and hard to grasp.",
  te: "కర్మ ఏమిటో తెలుసుకోవాలి, వికర్మ (తప్పు కర్మ) ఏమిటో తెలుసుకోవాలి, అకర్మ ఏమిటో కూడా తెలుసుకోవాలి — ఎందుకంటే కర్మ యొక్క గతి చాలా లోతైనది.",
  hi: "कर्म को समझना चाहिए, विकर्म (गलत कर्म) को भी समझना चाहिए और अकर्म को भी — क्योंकि कर्म की गति बड़ी गहन है।"
},
"gita_ch4_v18": {
  en: "One who sees inaction in action and action in inaction is truly wise among people. Such a person is steady in yoga, even while doing all kinds of work.",
  te: "కర్మలో అకర్మను, అకర్మలో కర్మను చూడగలిగినవాడే మనుషులలో బుద్ధిమంతుడు. అన్ని పనులూ చేస్తున్నా అతను యోగంలో స్థిరంగా ఉంటాడు.",
  hi: "जो कर्म में अकर्म और अकर्म में कर्म देखता है, वही मनुष्यों में बुद्धिमान है। सब कर्म करते हुए भी वह योग में स्थित रहता है।"
},
"gita_ch4_v19": {
  en: "One whose every undertaking is free from selfish desire and scheming, whose actions are burned up in the fire of knowledge — the wise call that person truly learned.",
  te: "ఎవరు మొదలుపెట్టే ప్రతి పనిలోనూ కోరికలు, స్వార్థపు ఆలోచనలు ఉండవో, ఎవరి కర్మలు జ్ఞానమనే అగ్నిలో కాలిపోయాయో — అతన్నే జ్ఞానులు పండితుడని అంటారు.",
  hi: "जिसके सभी कार्य कामना और स्वार्थी संकल्प से रहित हैं, जिसके कर्म ज्ञान की अग्नि में जल चुके हैं — ज्ञानीजन उसी को पंडित कहते हैं।"
},
"gita_ch4_v20": {
  en: "Giving up attachment to the fruits of action, always content, depending on nothing outside, such a person does nothing at all, even while fully engaged in work.",
  te: "కర్మఫలంపై ఆసక్తిని విడిచి, ఎప్పుడూ తృప్తిగా, దేనిమీదా ఆధారపడకుండా ఉండేవాడు — పనుల్లో పూర్తిగా నిమగ్నమైనా నిజానికి ఏమీ చేయనట్లే.",
  hi: "कर्मफल की आसक्ति छोड़कर, सदा संतुष्ट और किसी पर निर्भर न रहने वाला व्यक्ति काम में पूरी तरह लगा रहकर भी वास्तव में कुछ नहीं करता।"
},
"gita_ch4_v21": {
  en: "Expecting nothing, with mind and body under control, letting go of all possessiveness, doing only what the body needs to do — such a person incurs no sin.",
  te: "ఏ ఆశా లేకుండా, మనస్సును శరీరాన్ని అదుపులో ఉంచుకొని, ‘నాది’ అనే పట్టు అంతా వదిలి, శరీరానికి అవసరమైన పనులు మాత్రమే చేసేవాడికి పాపం అంటదు.",
  hi: "जो कुछ नहीं चाहता, जिसने मन और शरीर को वश में किया है, सब संग्रह-भाव छोड़ दिया है और केवल शरीर के लिए आवश्यक कर्म करता है — उसे पाप नहीं लगता।"
},
"gita_ch4_v22": {
  en: "Content with whatever comes on its own, beyond the pairs of opposites, free from envy, the same in success and failure — even when acting, such a person is not bound.",
  te: "అనుకోకుండా లభించినదానితో తృప్తిపడేవాడు, ద్వంద్వాలకు అతీతుడు, అసూయ లేనివాడు, విజయంలోనూ అపజయంలోనూ ఒకేలా ఉండేవాడు — పనులు చేసినా బంధింపబడడు.",
  hi: "जो अपने आप मिले उसी में संतुष्ट है, द्वंद्वों से परे है, ईर्ष्या से रहित है और सफलता-असफलता में समान है — वह कर्म करके भी नहीं बँधता।"
},
"gita_ch4_v23": {
  en: "For one who is free of attachment and liberated, whose mind is settled in knowledge, and who works as an offering, all action melts away completely.",
  te: "ఆసక్తి లేనివాడు, విముక్తుడు, జ్ఞానంలో మనసు నిలిపినవాడు, యజ్ఞంగా (అర్పణగా) పనులు చేసేవాడు — అతని కర్మలన్నీ పూర్తిగా కరిగిపోతాయి.",
  hi: "जो आसक्ति-रहित और मुक्त है, जिसका मन ज्ञान में स्थित है और जो यज्ञ-भाव से कर्म करता है, उसके सारे कर्म पूरी तरह विलीन हो जाते हैं।"
},
"gita_ch4_v24": {
  en: "The act of offering is Brahman, the offering is Brahman, poured by Brahman into the fire that is Brahman. One who sees Brahman in every action surely reaches Brahman.",
  te: "అర్పించడం బ్రహ్మం, అర్పించే హవిస్సు బ్రహ్మం, బ్రహ్మమనే అగ్నిలో బ్రహ్మమే హోమం చేస్తున్నాడు. ప్రతి కర్మలోనూ బ్రహ్మాన్నే చూసేవాడు తప్పకుండా బ్రహ్మాన్నే చేరుకుంటాడు.",
  hi: "अर्पण ब्रह्म है, हवि ब्रह्म है, ब्रह्मरूपी अग्नि में ब्रह्म द्वारा ही आहुति दी जाती है। जो हर कर्म में ब्रह्म को देखता है, वह निश्चय ही ब्रह्म को प्राप्त होता है।"
},
"gita_ch4_v25": {
  en: "Some yogīs perform sacrifice by worshipping the gods; others offer the self as sacrifice into the fire of Brahman.",
  te: "కొందరు యోగులు దేవతలను పూజించడమనే యజ్ఞం చేస్తారు; మరికొందరు బ్రహ్మమనే అగ్నిలో తమను తామే యజ్ఞంగా అర్పిస్తారు.",
  hi: "कुछ योगी देवताओं की उपासना रूपी यज्ञ करते हैं; दूसरे ब्रह्मरूपी अग्नि में स्वयं को ही यज्ञ के रूप में अर्पित करते हैं।"
},
"gita_ch4_v26": {
  en: "Some offer hearing and the other senses into the fires of restraint; others offer sound and the other sense objects into the fires of the senses.",
  te: "కొందరు చెవి మొదలైన ఇంద్రియాలను నిగ్రహమనే అగ్నిలో హోమం చేస్తారు; మరికొందరు శబ్దం మొదలైన విషయాలను ఇంద్రియాలనే అగ్నిలో హోమం చేస్తారు.",
  hi: "कुछ लोग कान आदि इंद्रियों को संयम की अग्नि में होम करते हैं; दूसरे शब्द आदि विषयों को इंद्रियों की अग्नि में होम करते हैं।"
},
"gita_ch4_v27": {
  en: "Others offer all the workings of the senses and of the life-breath into the fire of self-control, kindled by knowledge.",
  te: "మరికొందరు ఇంద్రియాల పనులన్నిటినీ, ప్రాణశక్తి పనులన్నిటినీ జ్ఞానంతో వెలిగిన ఆత్మసంయమమనే యోగాగ్నిలో హోమం చేస్తారు.",
  hi: "कुछ अन्य लोग इंद्रियों और प्राणों के सभी कार्यों को ज्ञान से प्रज्वलित आत्मसंयम रूपी योग-अग्नि में होम करते हैं।"
},
"gita_ch4_v28": {
  en: "Some offer wealth as their sacrifice, some austerity, some the practice of yoga; and earnest seekers of firm vows offer the study of scripture and knowledge.",
  te: "కొందరు ధనాన్ని యజ్ఞంగా అర్పిస్తారు, కొందరు తపస్సును, కొందరు యోగసాధనను; కఠినమైన వ్రతాలు పాటించే సాధకులు స్వాధ్యాయాన్ని, జ్ఞానాన్ని యజ్ఞంగా చేస్తారు.",
  hi: "कुछ लोग धन का यज्ञ करते हैं, कुछ तप का, कुछ योग का; और दृढ़ व्रत वाले साधक स्वाध्याय और ज्ञान का यज्ञ करते हैं।"
},
"gita_ch4_v29": {
  en: "Others, devoted to breath control, offer the outgoing breath into the incoming and the incoming into the outgoing, holding the flow of both.",
  te: "ప్రాణాయామంలో నిష్ఠ గలవారు కొందరు అపానంలో ప్రాణాన్ని, ప్రాణంలో అపానాన్ని హోమం చేస్తూ, ఉచ్ఛ్వాస నిశ్వాసాల గతిని నిలిపివేస్తారు.",
  hi: "प्राणायाम में लगे कुछ लोग अपान में प्राण का और प्राण में अपान का होम करते हैं, और दोनों की गति को रोक लेते हैं।"
},
"gita_ch4_v30": {
  en: "Still others, eating in measure, offer the life-breaths into the life-breaths. All of these know what sacrifice is, and through sacrifice their impurities are washed away.",
  te: "మరికొందరు మితాహారం తీసుకుంటూ ప్రాణాలను ప్రాణాలలోనే హోమం చేస్తారు. వీరందరూ యజ్ఞాన్ని తెలిసినవారే; యజ్ఞంతో వారి పాపాలు తొలగిపోతాయి.",
  hi: "कुछ अन्य लोग नियमित आहार करते हुए प्राणों को प्राणों में ही होम करते हैं। ये सभी यज्ञ को जानने वाले हैं और यज्ञ से इनके पाप धुल जाते हैं।"
},
"gita_ch4_v31": {
  en: "Those who enjoy the nectar that remains after sacrifice reach the eternal Brahman. Even this world is not for one who makes no sacrifice — how then the next, best of the Kurus?",
  te: "యజ్ఞం తర్వాత మిగిలిన అమృతాన్ని అనుభవించేవారు సనాతనమైన బ్రహ్మాన్ని చేరుకుంటారు. కురుశ్రేష్ఠా, యజ్ఞం చేయనివాడికి ఈ లోకమే దక్కదు — ఇక పరలోకం ఎక్కడ?",
  hi: "यज्ञ से बचे अमृत का सेवन करने वाले सनातन ब्रह्म को प्राप्त होते हैं। हे कुरुश्रेष्ठ, यज्ञ न करने वाले के लिए यह लोक भी नहीं है, तो परलोक कैसे होगा?"
},
"gita_ch4_v32": {
  en: "Many such sacrifices are laid out in the Veda. Know that all of them are born of action; knowing this, you will be set free.",
  te: "ఇలా ఎన్నో రకాల యజ్ఞాలు వేదంలో వివరించబడ్డాయి. అవన్నీ కర్మ నుండి పుట్టినవే అని తెలుసుకో; ఇది తెలిస్తే నువ్వు విముక్తుడవుతావు.",
  hi: "इस प्रकार के अनेक यज्ञ वेद में विस्तार से बताए गए हैं। जान लो कि वे सब कर्म से उत्पन्न होते हैं; यह जानकर तुम मुक्त हो जाओगे।"
},
"gita_ch4_v33": {
  en: "The sacrifice of knowledge is greater than any sacrifice of material things, Parantapa. All action without exception, Pārtha, finds its fulfilment in knowledge.",
  te: "పరంతపా! ద్రవ్యాలతో చేసే యజ్ఞం కంటే జ్ఞానయజ్ఞం శ్రేష్ఠమైనది. పార్థా, కర్మలన్నీ చివరికి జ్ఞానంలోనే పరిపూర్ణమవుతాయి.",
  hi: "हे परंतप! द्रव्य से किए यज्ञ से ज्ञानयज्ञ श्रेष्ठ है। हे पार्थ, सभी कर्म अंत में ज्ञान में ही पूर्ण होते हैं।"
},
"gita_ch4_v34": {
  en: "Learn it by bowing down humbly, by sincere questioning, and by service. The wise who have seen the truth will teach you that knowledge.",
  te: "వినయంగా నమస్కరించి, శ్రద్ధగా ప్రశ్నించి, సేవ చేసి ఆ జ్ఞానాన్ని తెలుసుకో. సత్యాన్ని దర్శించిన జ్ఞానులు నీకు ఆ జ్ఞానాన్ని ఉపదేశిస్తారు.",
  hi: "विनम्रता से प्रणाम करके, सच्चे मन से प्रश्न पूछकर और सेवा करके उस ज्ञान को जानो। तत्त्व को देख चुके ज्ञानी तुम्हें वह ज्ञान सिखाएँगे।"
},
"gita_ch4_v35": {
  en: "Knowing that, Pāṇḍava, you will not fall into confusion like this again. Through it you will see all beings, without exception, in your own Self and then in Me.",
  te: "పాండవా! అది తెలుసుకున్నాక నువ్వు మళ్ళీ ఇలాంటి మోహంలో పడవు. దానితో సమస్త ప్రాణులనూ నీలోనూ, తర్వాత నాలోనూ చూస్తావు.",
  hi: "हे पांडव! उसे जानकर तुम फिर इस प्रकार मोह में नहीं पड़ोगे। उससे तुम सभी प्राणियों को अपने भीतर और फिर मुझमें देखोगे।"
},
"gita_ch4_v36": {
  en: "Even if you were the worst of all sinners, you would cross over all wrongdoing by the boat of knowledge alone.",
  te: "నువ్వు పాపులందరిలోకీ అత్యంత పాపివైనా సరే, జ్ఞానమనే పడవతోనే పాపసముద్రాన్నంతా దాటేస్తావు.",
  hi: "यदि तुम सब पापियों में सबसे बड़े पापी भी हो, तो भी ज्ञान की नाव से ही सारे पाप-सागर को पार कर जाओगे।"
},
"gita_ch4_v37": {
  en: "Just as a blazing fire turns firewood to ash, Arjuna, so the fire of knowledge turns all actions to ash.",
  te: "అర్జునా! బాగా మండుతున్న అగ్ని కట్టెలను బూడిద చేసినట్లే, జ్ఞానమనే అగ్ని కర్మలన్నిటినీ బూడిద చేస్తుంది.",
  hi: "हे अर्जुन! जैसे धधकती आग लकड़ियों को राख कर देती है, वैसे ही ज्ञान की अग्नि सब कर्मों को राख कर देती है।"
},
"gita_ch4_v38": {
  en: "Truly, nothing in this world purifies like knowledge. One who has become perfect in yoga finds it within, in the Self, in due time.",
  te: "ఈ లోకంలో జ్ఞానంతో సమానమైన పవిత్రమైనది మరేదీ లేదు. యోగంలో సిద్ధి పొందినవాడు కాలక్రమంలో దాన్ని తనలోనే తెలుసుకుంటాడు.",
  hi: "इस संसार में ज्ञान के समान पवित्र करने वाला कुछ भी नहीं है। योग में सिद्ध हुआ व्यक्ति समय आने पर उसे अपने भीतर ही पा लेता है।"
},
"gita_ch4_v39": {
  en: "One who has faith, who is devoted to it, and who has mastered the senses gains knowledge; and having gained knowledge, soon reaches the highest peace.",
  te: "శ్రద్ధ గలవాడు, దానిలోనే నిమగ్నమైనవాడు, ఇంద్రియాలను జయించినవాడు జ్ఞానాన్ని పొందుతాడు; జ్ఞానం పొందాక త్వరలోనే పరమశాంతిని పొందుతాడు.",
  hi: "श्रद्धावान, उसी में लगा हुआ और इंद्रियों को वश में रखने वाला व्यक्ति ज्ञान पाता है; और ज्ञान पाकर शीघ्र ही परम शांति प्राप्त करता है।"
},
"gita_ch4_v40": {
  en: "But one who lacks knowledge and faith, and whose nature is to doubt everything, is ruined. For the doubting soul there is neither this world, nor the next, nor any happiness.",
  te: "కానీ జ్ఞానం లేనివాడు, శ్రద్ధ లేనివాడు, ప్రతిదాన్నీ సందేహించే స్వభావం గలవాడు నశిస్తాడు. సందేహించే మనిషికి ఈ లోకమూ లేదు, పరలోకమూ లేదు, సుఖమూ లేదు.",
  hi: "परंतु जो अज्ञानी है, श्रद्धाहीन है और हर बात पर संदेह करता है, वह नष्ट हो जाता है। संशय करने वाले के लिए न यह लोक है, न परलोक, न सुख।"
},
"gita_ch4_v41": {
  en: "One who has given up action through yoga, whose doubts are cut away by knowledge, and who is centred in the Self — actions do not bind such a person, Dhanañjaya.",
  te: "ధనంజయా! యోగంతో కర్మలను (వాటి ఫలాలను) అర్పించినవాడు, జ్ఞానంతో సందేహాలను తెంచుకున్నవాడు, ఆత్మలో స్థిరంగా ఉన్నవాడు — అతన్ని కర్మలు బంధించవు.",
  hi: "हे धनंजय! जिसने योग द्वारा कर्मों को अर्पित कर दिया है, जिसके संशय ज्ञान से कट गए हैं और जो आत्मा में स्थित है — उसे कर्म नहीं बाँधते।"
},
"gita_ch4_v42": {
  en: "So, with the sword of knowledge, cut away this doubt in your heart that was born of ignorance. Take your stand in yoga — arise, Bhārata!",
  te: "కాబట్టి భారతా! అజ్ఞానం వల్ల పుట్టి నీ హృదయంలో ఉన్న ఈ సందేహాన్ని జ్ఞానమనే ఖడ్గంతో ఛేదించు. యోగాన్ని ఆశ్రయించు — లే, నిలబడు!",
  hi: "इसलिए हे भारत! अज्ञान से उत्पन्न, अपने हृदय में बसे इस संशय को ज्ञान की तलवार से काट डालो। योग में स्थित हो जाओ — उठो!"
},

// ── Chapter 5 · Karma Sannyāsa Yoga ──
"gita_ch5_v1": {
  en: "Arjuna said: Kṛṣṇa, You praise renouncing action, and then again You praise the yoga of action. Of these two, tell me clearly and for certain which one is better.",
  te: "అర్జునుడు అన్నాడు: కృష్ణా! నువ్వు కర్మలను వదిలిపెట్టడాన్ని (సన్యాసాన్ని) పొగుడుతున్నావు, మళ్ళీ కర్మయోగాన్నీ పొగుడుతున్నావు. ఈ రెండింటిలో ఏది శ్రేయస్కరమో దాన్ని నిశ్చయంగా నాకు చెప్పు.",
  hi: "अर्जुन ने कहा: हे कृष्ण! आप कर्मों के संन्यास की प्रशंसा करते हैं और फिर कर्मयोग की भी। इन दोनों में जो एक निश्चित रूप से श्रेष्ठ हो, वह मुझे स्पष्ट बताइए।"
},
"gita_ch5_v2": {
  en: "The Lord said: Renouncing action and the yoga of action both lead to the highest good. But of the two, the yoga of action is better than renouncing action.",
  te: "శ్రీ భగవానుడు అన్నాడు: కర్మసన్యాసం, కర్మయోగం — రెండూ పరమ శ్రేయస్సును ఇస్తాయి. కానీ ఈ రెండింటిలో కర్మసన్యాసం కంటే కర్మయోగమే గొప్పది.",
  hi: "श्री भगवान ने कहा: कर्म-संन्यास और कर्मयोग — दोनों ही परम कल्याण देने वाले हैं। परंतु इन दोनों में कर्म-संन्यास से कर्मयोग श्रेष्ठ है।"
},
"gita_ch5_v3": {
  en: "Know that person to be a true renunciate who neither hates nor craves. Free from the pairs of opposites, mighty-armed one, such a person is easily set free from bondage.",
  te: "మహాబాహూ! దేన్నీ ద్వేషించనివాడు, దేన్నీ కోరనివాడు — అతడే నిత్య సన్యాసి అని తెలుసుకో. ద్వంద్వాలకు అతీతుడైన అలాంటివాడు బంధం నుండి సులభంగా విడుదల పొందుతాడు.",
  hi: "हे महाबाहो! जो न द्वेष करता है, न कामना करता है, उसे सदा संन्यासी ही जानो। द्वंद्वों से मुक्त ऐसा व्यक्ति सहज ही बंधन से छूट जाता है।"
},
"gita_ch5_v4": {
  en: "It is the immature, not the wise, who speak of the path of knowledge (Sāṅkhya) and the path of action (Yoga) as different. One who is truly established in even one of them gains the fruit of both.",
  te: "జ్ఞానమార్గం (సాంఖ్యం), కర్మమార్గం (యోగం) వేరువేరని చెప్పేది అమాయకులే గానీ పండితులు కారు. వాటిలో ఒక్కదానిలో సరిగ్గా నిలిచినవాడు రెండింటి ఫలాన్నీ పొందుతాడు.",
  hi: "ज्ञानमार्ग (सांख्य) और कर्ममार्ग (योग) को अलग-अलग बच्चे (नासमझ) कहते हैं, ज्ञानी नहीं। जो इनमें से किसी एक में भी ठीक से स्थित हो जाता है, वह दोनों का फल पा लेता है।"
},
"gita_ch5_v5": {
  en: "The state reached by those on the path of knowledge is reached also by those on the path of action. One who sees knowledge and action as one truly sees.",
  te: "జ్ఞానమార్గంలో ఉన్నవారు ఏ స్థానాన్ని పొందుతారో, కర్మయోగులూ అదే స్థానాన్ని పొందుతారు. సాంఖ్యాన్నీ యోగాన్నీ ఒక్కటిగా చూసేవాడే నిజంగా చూస్తున్నవాడు.",
  hi: "ज्ञानमार्गी जिस स्थान को पाते हैं, कर्मयोगी भी वहीं पहुँचते हैं। जो सांख्य और योग को एक देखता है, वही वास्तव में देखता है।"
},
"gita_ch5_v6": {
  en: "But renunciation is hard to attain without yoga, mighty-armed one. The sage who is joined in yoga reaches Brahman before long.",
  te: "మహాబాహూ! కర్మయోగం లేకుండా సన్యాసం పొందడం కష్టం. యోగంతో కూడిన ముని త్వరలోనే బ్రహ్మను చేరుకుంటాడు.",
  hi: "परंतु हे महाबाहो! योग के बिना संन्यास पाना कठिन है। योग से युक्त मुनि शीघ्र ही ब्रह्म को प्राप्त कर लेता है।"
},
"gita_ch5_v7": {
  en: "One who is joined in yoga, pure in heart, master of the mind and senses, and who sees their own Self as the Self of all beings — such a person is not tainted, even while acting.",
  te: "యోగంతో కూడినవాడు, శుద్ధమైన మనసు గలవాడు, మనసునూ ఇంద్రియాలనూ జయించినవాడు, సర్వ ప్రాణుల ఆత్మనే తన ఆత్మగా చూసేవాడు — పనులు చేస్తున్నా వాటికి అంటుకోడు.",
  hi: "जो योग से युक्त है, शुद्ध मन वाला है, मन और इंद्रियों को जीत चुका है, और सब प्राणियों की आत्मा को अपनी ही आत्मा देखता है — वह कर्म करते हुए भी लिप्त नहीं होता।"
},
"gita_ch5_v8": {
  en: "One who knows the truth, steady in yoga, thinks, \"I do nothing at all\" — while seeing, hearing, touching, smelling, eating, walking, sleeping, breathing —",
  te: "తత్త్వం తెలిసిన యోగి చూస్తూ, వింటూ, తాకుతూ, వాసన చూస్తూ, తింటూ, నడుస్తూ, నిద్రపోతూ, ఊపిరి తీస్తూ కూడా ‘నేనేమీ చేయడం లేదు’ అని భావిస్తాడు —",
  hi: "तत्त्व को जानने वाला योगी देखते, सुनते, छूते, सूँघते, खाते, चलते, सोते, साँस लेते हुए भी यही मानता है कि 'मैं कुछ भी नहीं करता' —"
},
"gita_ch5_v9": {
  en: "— speaking, letting go, taking hold, even opening and closing the eyes — understanding that it is only the senses moving among their objects.",
  te: "— మాట్లాడుతూ, విసర్జిస్తూ, పట్టుకుంటూ, కనురెప్పలు తెరుస్తూ మూస్తూ కూడా — ఇంద్రియాలు తమ విషయాలలో తిరుగుతున్నాయి అంతే అని అర్థం చేసుకుంటాడు.",
  hi: "— बोलते, त्यागते, ग्रहण करते, आँखें खोलते और मूँदते हुए भी — यह समझता है कि केवल इंद्रियाँ अपने विषयों में बरत रही हैं।"
},
"gita_ch5_v10": {
  en: "One who acts by offering all actions to Brahman, giving up attachment, is not touched by sin — just as a lotus leaf is not wetted by water.",
  te: "కర్మలన్నీ బ్రహ్మకు అర్పించి, ఆసక్తిని వదిలి పని చేసేవాడిని పాపం అంటదు — తామరాకును నీరు అంటనట్లు.",
  hi: "जो सारे कर्म ब्रह्म को अर्पित करके, आसक्ति छोड़कर कर्म करता है, वह पाप से लिप्त नहीं होता — जैसे कमल का पत्ता जल से नहीं भीगता।"
},
"gita_ch5_v11": {
  en: "Yogīs do their work with the body, the mind, the intellect, even with the senses alone, giving up attachment — for the purification of the heart.",
  te: "యోగులు ఆసక్తిని వదిలిపెట్టి, శరీరంతో, మనసుతో, బుద్ధితో, కేవలం ఇంద్రియాలతో కూడా — మనసు శుద్ధి కోసం కర్మలు చేస్తారు.",
  hi: "योगी आसक्ति छोड़कर शरीर से, मन से, बुद्धि से और केवल इंद्रियों से भी — अंतःकरण की शुद्धि के लिए कर्म करते हैं।"
},
"gita_ch5_v12": {
  en: "The one steady in yoga gives up the fruit of action and attains lasting peace. The one not steady, driven by desire and clinging to the fruit, is bound.",
  te: "యోగంలో నిలిచినవాడు కర్మఫలాన్ని వదిలి శాశ్వతమైన శాంతిని పొందుతాడు. యోగం లేనివాడు కోరికతో నడిచి, ఫలానికి అంటుకొని బంధింపబడతాడు.",
  hi: "योग में स्थित व्यक्ति कर्मफल को छोड़कर स्थायी शांति पाता है। जो योग में नहीं है, वह कामना से प्रेरित होकर, फल में आसक्त होकर बँध जाता है।"
},
"gita_ch5_v13": {
  en: "Having inwardly let go of all actions with the mind, the self-controlled embodied soul rests happily in the city of nine gates, neither acting nor causing action.",
  te: "మనసులో కర్మలన్నిటినీ వదిలిపెట్టి, తనను తాను అదుపులో ఉంచుకున్న జీవుడు తొమ్మిది ద్వారాల పట్టణమైన ఈ శరీరంలో సుఖంగా ఉంటాడు — తాను చేయడు, ఇతరులతో చేయించడు.",
  hi: "मन से सब कर्मों का त्याग करके, संयमी देहधारी आत्मा नौ द्वारों वाले नगर (शरीर) में सुखपूर्वक रहता है — न स्वयं कुछ करता है, न करवाता है।"
},
"gita_ch5_v14": {
  en: "The Lord does not create the sense of being a doer for people, nor their actions, nor the link between action and its fruit. It is nature (svabhāva) that carries all this on.",
  te: "ప్రభువు లోకుల కోసం ‘నేను చేస్తున్నాను’ అనే భావాన్ని గానీ, కర్మలను గానీ, కర్మకూ ఫలానికీ ఉండే సంబంధాన్ని గానీ సృష్టించడు. ఇవన్నీ స్వభావమే (ప్రకృతే) నడుపుతుంది.",
  hi: "प्रभु लोगों के लिए न कर्तापन रचते हैं, न कर्म, न कर्म और फल का संयोग। यह सब स्वभाव (प्रकृति) ही चलाता है।"
},
"gita_ch5_v15": {
  en: "The all-pervading Lord does not take on anyone's sin or anyone's good deed. Knowledge is covered by ignorance, and that is why living beings are deluded.",
  te: "సర్వవ్యాపి అయిన ప్రభువు ఎవరి పాపాన్నీ తీసుకోడు, ఎవరి పుణ్యాన్నీ తీసుకోడు. జ్ఞానం అజ్ఞానంతో కప్పబడి ఉంది — అందుకే ప్రాణులు మోహంలో పడుతున్నాయి.",
  hi: "सर्वव्यापी प्रभु न किसी का पाप लेते हैं, न किसी का पुण्य। ज्ञान अज्ञान से ढका हुआ है — इसी से जीव मोहित होते हैं।"
},
"gita_ch5_v16": {
  en: "But for those whose ignorance has been destroyed by knowledge of the Self, that knowledge, like the sun, lights up the Supreme.",
  te: "కానీ ఎవరి అజ్ఞానం ఆత్మజ్ఞానంతో నశించిందో, వారికి ఆ జ్ఞానం సూర్యునిలా ప్రకాశించి పరమాత్మను చూపిస్తుంది.",
  hi: "परंतु जिनका अज्ञान आत्मज्ञान से नष्ट हो गया है, उनका वह ज्ञान सूर्य की तरह परमतत्त्व को प्रकाशित कर देता है।"
},
"gita_ch5_v17": {
  en: "Their minds fixed on That, their whole being in That, devoted to That, holding That as the highest goal, their impurities washed away by knowledge — they go to the state from which there is no return.",
  te: "బుద్ధి దానిలోనే, మనసు దానిలోనే, నిష్ఠ దానిలోనే, దాన్నే పరమ గమ్యంగా భావించి, జ్ఞానంతో పాపాలు కడిగివేయబడినవారు — తిరిగి రాని స్థితిని పొందుతారు.",
  hi: "जिनकी बुद्धि उसी में है, मन उसी में है, निष्ठा उसी में है, जो उसी को परम लक्ष्य मानते हैं और जिनके दोष ज्ञान से धुल गए हैं — वे उस स्थिति को पाते हैं जहाँ से लौटना नहीं होता।"
},
"gita_ch5_v18": {
  en: "The wise see with an equal eye a learned and humble brāhmaṇa, a cow, an elephant, a dog, and even one who eats dog-meat.",
  te: "విద్యా వినయాలు గల బ్రాహ్మణుడిలో, ఆవులో, ఏనుగులో, కుక్కలో, కుక్కమాంసం తినేవాడిలో కూడా పండితులు సమదృష్టితో చూస్తారు.",
  hi: "ज्ञानी लोग विद्या और विनय से संपन्न ब्राह्मण, गाय, हाथी, कुत्ते और कुत्ते का मांस खाने वाले में भी समान दृष्टि रखते हैं।"
},
"gita_ch5_v19": {
  en: "Even here in this life, the cycle of birth is conquered by those whose minds rest in equality. Brahman is flawless and the same in all; therefore they are established in Brahman.",
  te: "ఎవరి మనసు సమత్వంలో నిలిచి ఉంటుందో, వారు ఈ జన్మలోనే సంసారాన్ని జయించారు. బ్రహ్మం దోషం లేనిది, అన్నిటిలో సమంగా ఉన్నది; కాబట్టి వారు బ్రహ్మంలోనే నిలిచి ఉన్నారు.",
  hi: "जिनका मन समता में स्थित है, उन्होंने यहीं इसी जीवन में संसार को जीत लिया। ब्रह्म निर्दोष और सब में सम है; इसलिए वे ब्रह्म में ही स्थित हैं।"
},
"gita_ch5_v20": {
  en: "One who knows Brahman and rests in Brahman, steady of mind and free from delusion, does not rejoice on getting what is pleasant, nor become upset on getting what is unpleasant.",
  te: "బ్రహ్మను తెలుసుకొని బ్రహ్మంలో నిలిచినవాడు, స్థిరమైన బుద్ధి గలవాడు, మోహం లేనివాడు — ఇష్టమైనది దొరికితే పొంగిపోడు, అయిష్టమైనది వస్తే కలవరపడడు.",
  hi: "जो ब्रह्म को जानकर ब्रह्म में स्थित है, स्थिर बुद्धि वाला और मोह से रहित है — वह प्रिय मिलने पर फूलता नहीं और अप्रिय मिलने पर घबराता नहीं।"
},
"gita_ch5_v21": {
  en: "One who is not attached to outer sense-contacts finds the joy that is within the Self. United with Brahman through yoga, that person enjoys a happiness that never decays.",
  te: "బయటి ఇంద్రియ సుఖాలకు అంటుకోనివాడు తనలోనే ఉన్న ఆనందాన్ని పొందుతాడు. యోగంతో బ్రహ్మంలో ఐక్యమైన అతడు ఎప్పటికీ తరగని సుఖాన్ని అనుభవిస్తాడు.",
  hi: "जो बाहरी इंद्रिय-विषयों में आसक्त नहीं है, वह आत्मा में ही सुख पाता है। योग द्वारा ब्रह्म से जुड़ा वह व्यक्ति कभी न घटने वाला सुख भोगता है।"
},
"gita_ch5_v22": {
  en: "The pleasures born from contact with sense-objects are really sources of sorrow. They have a beginning and an end, Kaunteya; the wise do not delight in them.",
  te: "కౌంతేయా! ఇంద్రియ స్పర్శ వల్ల పుట్టే భోగాలు నిజానికి దుఃఖానికే మూలాలు. వాటికి మొదలూ ఉంది, ముగింపూ ఉంది; జ్ఞానులు వాటిలో రమించరు.",
  hi: "हे कौंतेय! इंद्रियों के संपर्क से पैदा होने वाले भोग वास्तव में दुःख के ही कारण हैं। उनका आदि और अंत है; बुद्धिमान उनमें रमता नहीं।"
},
"gita_ch5_v23": {
  en: "One who, here in this life, before leaving the body, is able to withstand the rush of desire and anger — that person is a yogī; that person is happy.",
  te: "శరీరం విడిచిపెట్టక ముందే, ఈ జన్మలోనే, కామక్రోధాల నుండి పుట్టే వేగాన్ని తట్టుకోగలిగినవాడే యోగి; అతడే సుఖి.",
  hi: "जो इसी जीवन में, शरीर छूटने से पहले, काम और क्रोध से उठने वाले वेग को सह सकता है — वही योगी है, वही सुखी मनुष्य है।"
},
"gita_ch5_v24": {
  en: "One whose happiness is within, who delights within, and whose light is within — that yogī, becoming one with Brahman, attains the peace of Brahman (brahma-nirvāṇa).",
  te: "ఎవరి సుఖం లోపలే ఉందో, ఎవరి ఆనందం లోపలే ఉందో, ఎవరి వెలుగు లోపలే ఉందో — ఆ యోగి బ్రహ్మస్వరూపుడై బ్రహ్మనిర్వాణాన్ని పొందుతాడు.",
  hi: "जिसका सुख भीतर है, जो भीतर ही रमता है, और जिसका प्रकाश भीतर ही है — वह योगी ब्रह्मरूप होकर ब्रह्मनिर्वाण को प्राप्त करता है।"
},
"gita_ch5_v25": {
  en: "Sages whose impurities are worn away, whose doubts are cut, who are self-controlled and who delight in the welfare of all beings — they attain the peace of Brahman.",
  te: "పాపాలు నశించినవారు, సందేహాలు తెగినవారు, మనసును అదుపులో ఉంచుకున్నవారు, సర్వ ప్రాణుల హితంలో ఆనందించేవారు అయిన ఋషులు బ్రహ్మనిర్వాణాన్ని పొందుతారు.",
  hi: "जिनके दोष क्षीण हो गए हैं, जिनके संशय कट गए हैं, जो संयमी हैं और सब प्राणियों के हित में लगे रहते हैं — वे ऋषि ब्रह्मनिर्वाण पाते हैं।"
},
"gita_ch5_v26": {
  en: "For the disciplined seekers who are free from desire and anger, who have mastered their minds and know the Self, the peace of Brahman is near on every side.",
  te: "కామక్రోధాలు లేనివారు, మనసును జయించినవారు, ఆత్మను తెలుసుకున్నవారు అయిన యతులకు బ్రహ్మనిర్వాణం అన్ని వైపులా దగ్గరలోనే ఉంటుంది.",
  hi: "जो यति काम और क्रोध से मुक्त हैं, जिन्होंने मन को वश में किया है और आत्मा को जाना है — उनके लिए ब्रह्मनिर्वाण चारों ओर, निकट ही है।"
},
"gita_ch5_v27": {
  en: "Shutting out the outside world of sense-objects, fixing the gaze between the eyebrows, making even the in-breath and out-breath that move through the nostrils —",
  te: "బయటి విషయాలను బయటే ఉంచి, చూపును కనుబొమల మధ్య నిలిపి, ముక్కు లోపల సంచరించే ప్రాణ అపాన వాయువులను (ఉచ్ఛ్వాస నిశ్వాసాలను) సమంగా చేసి —",
  hi: "बाहरी विषयों को बाहर ही छोड़कर, दृष्टि को भौंहों के बीच टिकाकर, नासिका में चलने वाली प्राण और अपान वायु (श्वास-प्रश्वास) को सम करके —"
},
"gita_ch5_v28": {
  en: "— with senses, mind and intellect under control, the sage intent on liberation, free from desire, fear and anger — such a one is forever free.",
  te: "— ఇంద్రియాలనూ మనసునూ బుద్ధినీ అదుపులో ఉంచుకొని, మోక్షమే లక్ష్యంగా గల ముని, కోరిక భయం కోపం లేనివాడు — అతడు ఎల్లప్పుడూ ముక్తుడే.",
  hi: "— इंद्रियाँ, मन और बुद्धि वश में करके, मोक्ष को ही लक्ष्य मानने वाला, इच्छा, भय और क्रोध से रहित मुनि — वह सदा मुक्त ही है।"
},
"gita_ch5_v29": {
  en: "Knowing Me as the one who receives all sacrifices and austerities, the great Lord of all the worlds, and the loving friend of every being — one attains peace.",
  te: "అన్ని యజ్ఞాలనూ తపస్సులనూ స్వీకరించేవాడిగా, సర్వలోకాలకూ మహేశ్వరుడిగా, సర్వ ప్రాణులకూ ఆత్మీయ మిత్రుడిగా నన్ను తెలుసుకున్నవాడు శాంతిని పొందుతాడు.",
  hi: "मुझे सब यज्ञों और तपों का भोक्ता, सब लोकों का महान ईश्वर और सब प्राणियों का सुहृद (हितैषी मित्र) जानकर मनुष्य शांति पाता है।"
},

// ── Chapter 6 · Ātma Saṃyama Yoga ──
"gita_ch6_v1": {
  en: "The Lord said: One who does the work that ought to be done, without depending on its fruit, is a renunciate and a yogī — not the one who merely gives up the sacred fire or stops all activity.",
  te: "శ్రీ భగవానుడు అన్నాడు: కర్మఫలంపై ఆధారపడకుండా, చేయవలసిన కర్మను చేసేవాడే సన్యాసి, అతడే యోగి — అగ్నిహోత్రాన్ని విడిచినవాడో, పనులన్నీ మానేసినవాడో కాదు.",
  hi: "श्री भगवान ने कहा: जो कर्मफल का आश्रय लिए बिना करने योग्य कर्म करता है, वही संन्यासी है और वही योगी — न कि वह जिसने केवल अग्नि छोड़ दी या सब कर्म त्याग दिए।"
},
"gita_ch6_v2": {
  en: "What people call renunciation, know that to be yoga, Pāṇḍava. For no one becomes a yogī without giving up selfish intentions (saṅkalpa).",
  te: "పాండవా! దేన్ని సన్యాసం అంటారో, దాన్నే యోగమని తెలుసుకో. స్వార్థపూరితమైన సంకల్పాలను వదలనివాడు ఎవడూ యోగి కాలేడు.",
  hi: "हे पांडव! जिसे संन्यास कहते हैं, उसी को योग जानो। क्योंकि स्वार्थी संकल्पों को त्यागे बिना कोई भी योगी नहीं बनता।"
},
"gita_ch6_v3": {
  en: "For the sage who wishes to climb to yoga, action is said to be the means. For the same person, once they have reached yoga, calmness is said to be the means.",
  te: "యోగాన్ని అధిరోహించాలనుకునే మునికి కర్మే సాధనం అని చెబుతారు. యోగాన్ని అధిరోహించిన తర్వాత అదే వ్యక్తికి శాంతి (శమం) సాధనం అని చెబుతారు.",
  hi: "योग पर चढ़ना चाहने वाले मुनि के लिए कर्म को साधन कहा गया है। योग पर आरूढ़ हो जाने पर उसी के लिए शांति (शम) को साधन कहा गया है।"
},
"gita_ch6_v4": {
  en: "When a person is no longer attached to sense-objects or to actions, and has given up all selfish intentions, then that person is said to have climbed to yoga.",
  te: "ఎప్పుడు మనిషి ఇంద్రియ విషయాలకూ కర్మలకూ అంటుకోకుండా, సంకల్పాలన్నిటినీ వదిలేస్తాడో, అప్పుడు అతడిని యోగారూఢుడు అంటారు.",
  hi: "जब मनुष्य न इंद्रियों के विषयों में आसक्त होता है, न कर्मों में, और सब संकल्पों का त्याग कर देता है, तब उसे योगारूढ़ कहा जाता है।"
},
"gita_ch6_v5": {
  en: "Lift yourself up by your own self; do not let yourself sink down. For the self alone is one's own friend, and the self alone is one's own enemy.",
  te: "నిన్ను నువ్వే ఉద్ధరించుకోవాలి; నిన్ను నువ్వు కిందికి దిగజార్చుకోకూడదు. మనకు మన మనసే బంధువు, మన మనసే శత్రువు.",
  hi: "अपने द्वारा अपना उद्धार करो; अपने को नीचे न गिराओ। क्योंकि मनुष्य स्वयं ही अपना मित्र है और स्वयं ही अपना शत्रु।"
},
"gita_ch6_v6": {
  en: "For one who has conquered the self by the self, the self is a friend. But for one who has not mastered the self, that very self behaves like an enemy.",
  te: "తనను తానే జయించినవాడికి తన మనసే బంధువు. కానీ తనను తాను అదుపులో ఉంచుకోలేనివాడికి అదే మనసు శత్రువులా ప్రవర్తిస్తుంది.",
  hi: "जिसने अपने द्वारा अपने को जीत लिया है, उसके लिए उसका मन मित्र है। परंतु जिसने अपने को वश में नहीं किया, उसके लिए वही मन शत्रु की तरह बरतता है।"
},
"gita_ch6_v7": {
  en: "For one who has conquered the self and is deeply at peace, the Supreme Self stays steadily present — in cold and heat, in pleasure and pain, in honour and dishonour.",
  te: "మనసును జయించి, పూర్తిగా ప్రశాంతంగా ఉన్నవాడిలో పరమాత్మ స్థిరంగా నిలిచి ఉంటాడు — చలి వేడిలలో, సుఖదుఃఖాలలో, మానావమానాలలో కూడా.",
  hi: "जिसने अपने मन को जीत लिया है और जो पूर्णतः शांत है, उसमें परमात्मा स्थिर रूप से विराजमान रहते हैं — सर्दी-गर्मी, सुख-दुःख और मान-अपमान में भी।"
},
"gita_ch6_v8": {
  en: "The yogī who is content in knowledge and wisdom, unshaken like an anvil, master of the senses, and to whom a lump of earth, a stone and gold are the same — is said to be steady in yoga.",
  te: "జ్ఞాన విజ్ఞానాలతో తృప్తి పొందినవాడు, దాగలిలా చలించనివాడు (కూటస్థుడు), ఇంద్రియాలను జయించినవాడు, మట్టిముద్దనూ రాయినీ బంగారాన్నీ సమానంగా చూసేవాడు — అలాంటి యోగిని యుక్తుడు అంటారు.",
  hi: "जो ज्ञान और विज्ञान से तृप्त है, निहाई की तरह अडिग है, इंद्रियों को जीत चुका है, और जिसके लिए मिट्टी का ढेला, पत्थर और सोना समान हैं — वह योगी युक्त कहलाता है।"
},
"gita_ch6_v9": {
  en: "Even more distinguished is one who has an equal mind towards well-wishers, friends, enemies, the indifferent, the neutral, the hateful and relatives — and even towards the good and the wicked.",
  te: "శ్రేయోభిలాషులు, మిత్రులు, శత్రువులు, ఉదాసీనులు, మధ్యస్థులు, ద్వేషించేవారు, బంధువులు — సాధువులు, పాపులు అందరి పట్లా సమబుద్ధి గలవాడు ఇంకా శ్రేష్ఠుడు.",
  hi: "जो हितैषी, मित्र, शत्रु, उदासीन, मध्यस्थ, द्वेषी और बंधुओं के प्रति — और साधुओं तथा पापियों के प्रति भी — समबुद्धि रखता है, वह और भी श्रेष्ठ है।"
},
"gita_ch6_v10": {
  en: "The yogī should constantly practise focusing the mind, staying in a solitary place, alone, with mind and body under control, free from longing and from possessiveness.",
  te: "యోగి ఏకాంత ప్రదేశంలో, ఒంటరిగా ఉండి, మనసునూ శరీరాన్నీ అదుపులో ఉంచుకొని, ఆశలు లేకుండా, సంగ్రహించాలనే బుద్ధి లేకుండా నిరంతరం మనసును యోగంలో నిలపాలి.",
  hi: "योगी को एकांत स्थान में, अकेले रहकर, मन और शरीर को वश में करके, आशा और परिग्रह से रहित होकर, निरंतर मन को योग में लगाना चाहिए।"
},
"gita_ch6_v11": {
  en: "In a clean place, setting up a firm seat for oneself — neither too high nor too low — covered with cloth, a deerskin and kuśa grass, one over the other —",
  te: "శుభ్రమైన ప్రదేశంలో, మరీ ఎత్తుగా కాకుండా మరీ తక్కువగా కాకుండా, దర్భ, జింక చర్మం, వస్త్రం ఒకదానిపై ఒకటి పరిచిన స్థిరమైన ఆసనాన్ని ఏర్పాటు చేసుకొని —",
  hi: "पवित्र स्थान में, न बहुत ऊँचा न बहुत नीचा, कुश, मृगछाला और वस्त्र एक के ऊपर एक बिछाकर अपना स्थिर आसन जमाकर —"
},
"gita_ch6_v12": {
  en: "— sitting there on that seat, making the mind one-pointed and controlling the activity of mind and senses, one should practise yoga for the purification of the self.",
  te: "— ఆ ఆసనంపై కూర్చుని, మనసును ఏకాగ్రం చేసి, మనసు ఇంద్రియాల చలనాన్ని అదుపులో ఉంచుకొని, ఆత్మశుద్ధి కోసం యోగాన్ని అభ్యసించాలి.",
  hi: "— उस आसन पर बैठकर, मन को एकाग्र करके, चित्त और इंद्रियों की क्रियाओं को वश में करके, आत्मशुद्धि के लिए योग का अभ्यास करना चाहिए।"
},
"gita_ch6_v13": {
  en: "Holding the body, head and neck straight and still, steady, gazing at the tip of one's own nose and not looking around in any direction —",
  te: "శరీరం, తల, మెడ ఒకే వరుసలో నిటారుగా, కదలకుండా ఉంచి, స్థిరంగా ఉండి, తన ముక్కు కొనను చూస్తూ, దిక్కుల వైపు చూడకుండా —",
  hi: "शरीर, सिर और गर्दन को सीधा और अचल रखकर, स्थिर होकर, अपनी नासिका के अग्रभाग को देखते हुए और दिशाओं की ओर न देखते हुए —"
},
"gita_ch6_v14": {
  en: "— serene and fearless, firm in the vow of self-restraint, controlling the mind, with thoughts fixed on Me, one should sit in yoga, holding Me as the highest goal.",
  te: "— ప్రశాంతమైన మనసుతో, భయం లేకుండా, బ్రహ్మచర్య వ్రతంలో స్థిరంగా ఉండి, మనసును అదుపు చేసి, చిత్తాన్ని నా యందే నిలిపి, నన్నే పరమ లక్ష్యంగా భావించి యోగంలో కూర్చోవాలి.",
  hi: "— शांत चित्त और निर्भय होकर, ब्रह्मचर्य व्रत में स्थित रहकर, मन को संयमित करके, मुझमें चित्त लगाकर, मुझे ही परम लक्ष्य मानकर योग में बैठना चाहिए।"
},
"gita_ch6_v15": {
  en: "Practising like this always, the yogī with a disciplined mind attains peace — the supreme peace of liberation that rests in Me.",
  te: "ఈ విధంగా ఎల్లప్పుడూ మనసును యోగంలో నిలిపే, మనసును నియమించుకున్న యోగి నాలో నెలకొన్న, నిర్వాణమే పరమమైన శాంతిని పొందుతాడు.",
  hi: "इस प्रकार सदा अपने को योग में लगाते हुए, नियंत्रित मन वाला योगी मुझमें स्थित परम निर्वाणरूपी शांति को प्राप्त करता है।"
},
"gita_ch6_v16": {
  en: "Yoga is not for one who eats too much, nor for one who does not eat at all; not for one who sleeps too much, nor for one who stays awake too long, Arjuna.",
  te: "అర్జునా! అతిగా తినేవాడికీ, అసలు తిననివాడికీ యోగం సిద్ధించదు; అతిగా నిద్రపోయేవాడికీ, అతిగా మేలుకొని ఉండేవాడికీ కూడా సిద్ధించదు.",
  hi: "हे अर्जुन! यह योग न बहुत खाने वाले का सिद्ध होता है, न बिल्कुल न खाने वाले का; न बहुत सोने वाले का, न बहुत जागने वाले का।"
},
"gita_ch6_v17": {
  en: "For one who is moderate in eating and recreation, balanced in effort at work, and regulated in sleep and waking, yoga becomes the destroyer of sorrow.",
  te: "తిండిలో, విహారంలో మితంగా ఉండేవాడికి, పనులలో తగినంత ప్రయత్నం చేసేవాడికి, నిద్రలో మెలకువలో క్రమం పాటించేవాడికి యోగం దుఃఖాన్ని పోగొడుతుంది.",
  hi: "जो आहार और विहार में संयमित है, कर्मों में उचित प्रयास करता है, और सोने-जागने में नियमित है, उसके लिए योग दुःखों का नाश करने वाला बन जाता है।"
},
"gita_ch6_v18": {
  en: "When the well-controlled mind rests in the Self alone, free from craving for any object of desire, then one is said to be steady in yoga.",
  te: "బాగా నియమించబడిన మనసు ఆత్మలోనే నిలిచి ఉండి, ఏ కోరికపైనా ఆశ లేకుండా ఉన్నప్పుడు, అప్పుడు అతడిని యుక్తుడు (యోగంలో నిలిచినవాడు) అంటారు.",
  hi: "जब भली-भाँति वश में किया हुआ चित्त आत्मा में ही स्थित हो जाता है और सब कामनाओं से निःस्पृह हो जाता है, तब उसे योगयुक्त कहा जाता है।"
},
"gita_ch6_v19": {
  en: "\"Like a lamp in a windless place that does not flicker\" — that is the comparison used for the controlled mind of a yogī practising yoga of the Self.",
  te: "‘గాలి లేని చోట ఉన్న దీపం కదలనట్లు’ — ఆత్మయోగాన్ని అభ్యసిస్తూ మనసును అదుపులో ఉంచుకున్న యోగి చిత్తానికి ఇదే ఉపమానంగా చెబుతారు.",
  hi: "'जैसे वायुरहित स्थान में रखा दीपक नहीं डगमगाता' — आत्मयोग का अभ्यास करने वाले, संयमित चित्त वाले योगी के लिए यही उपमा कही गई है।"
},
"gita_ch6_v20": {
  en: "When the mind, restrained by the practice of yoga, comes to rest; when, seeing the Self by the Self, one is content in the Self —",
  te: "యోగాభ్యాసంతో నిరోధించబడిన చిత్తం ఎప్పుడు ఉపశమిస్తుందో, ఆత్మతో ఆత్మను చూస్తూ ఆత్మలోనే ఎప్పుడు తృప్తి పొందుతాడో —",
  hi: "जब योग के अभ्यास से रोका हुआ चित्त शांत हो जाता है, और जब मनुष्य आत्मा द्वारा आत्मा को देखकर आत्मा में ही संतुष्ट रहता है —"
},
"gita_ch6_v21": {
  en: "— when one knows that boundless joy which is grasped by the purified intellect and lies beyond the senses, and, established there, never moves away from the truth —",
  te: "— ఇంద్రియాలకు అతీతమైనది, శుద్ధమైన బుద్ధికి మాత్రమే అందేది అయిన ఆ అనంతమైన సుఖాన్ని ఎప్పుడు తెలుసుకుంటాడో, దానిలో నిలిచి తత్త్వం నుండి ఎప్పుడూ చలించడో —",
  hi: "— जब वह उस अनंत सुख को जानता है जो इंद्रियों से परे है और केवल शुद्ध बुद्धि से ग्रहण होता है, और उसमें स्थित होकर तत्त्व से कभी विचलित नहीं होता —"
},
"gita_ch6_v22": {
  en: "— having gained which, one thinks there is no greater gain, and established in which, one is not shaken even by the heaviest sorrow —",
  te: "— దేన్ని పొందిన తర్వాత దానికంటే గొప్ప లాభం మరొకటి లేదని భావిస్తాడో, దేనిలో నిలిచినవాడు ఎంత పెద్ద దుఃఖం వచ్చినా చలించడో —",
  hi: "— जिसे पाकर वह उससे बढ़कर कोई दूसरा लाभ नहीं मानता, और जिसमें स्थित होकर भारी से भारी दुःख से भी विचलित नहीं होता —"
},
"gita_ch6_v23": {
  en: "— know that to be yoga: the breaking of all contact with sorrow. This yoga should be practised with determination and an undiscouraged mind.",
  te: "— దుఃఖంతో ఉన్న సంబంధాన్ని తెంచివేసేదే యోగం అని తెలుసుకో. ఆ యోగాన్ని నిశ్చయంతో, విసుగు చెందని మనసుతో అభ్యసించాలి.",
  hi: "— उसी को योग जानो: दुःख के संयोग से वियोग। इस योग का अभ्यास दृढ़ निश्चय और बिना ऊबे, अथक मन से करना चाहिए।"
},
"gita_ch6_v24": {
  en: "Giving up completely all desires born of selfish imagining, and reining in the whole crowd of senses from every side with the mind itself —",
  te: "సంకల్పం నుండి పుట్టే కోరికలన్నిటినీ పూర్తిగా వదిలిపెట్టి, ఇంద్రియాల సమూహాన్ని మనసుతోనే అన్ని వైపుల నుండి అదుపులోకి తెచ్చుకొని —",
  hi: "संकल्प से उत्पन्न होने वाली सब कामनाओं को पूरी तरह छोड़कर, मन से ही इंद्रियों के समूह को सब ओर से वश में करके —"
},
"gita_ch6_v25": {
  en: "— little by little one should become still, with an intellect held firm by steadiness; fixing the mind in the Self, one should not think of anything else.",
  te: "— ధైర్యంతో (ధృతితో) పట్టుకున్న బుద్ధితో మెల్లమెల్లగా ఉపశమించాలి; మనసును ఆత్మలో నిలిపి, ఇంకేమీ ఆలోచించకూడదు.",
  hi: "— धैर्य से पकड़ी हुई बुद्धि द्वारा धीरे-धीरे शांत होना चाहिए; मन को आत्मा में स्थिर करके और कुछ भी नहीं सोचना चाहिए।"
},
"gita_ch6_v26": {
  en: "Wherever the restless, unsteady mind wanders off, from there one should draw it back and bring it under control in the Self alone.",
  te: "చంచలమైన, స్థిరం లేని మనసు ఎక్కడెక్కడికి పరుగెడుతుందో, అక్కడక్కడి నుండి దాన్ని వెనక్కి లాగి, ఆత్మలోనే వశం చేసుకోవాలి.",
  hi: "चंचल और अस्थिर मन जहाँ-जहाँ भटककर जाए, वहाँ-वहाँ से उसे खींचकर आत्मा में ही वश में करना चाहिए।"
},
"gita_ch6_v27": {
  en: "Supreme joy comes to this yogī whose mind is at peace, whose restlessness has settled, who is free from impurity and has become one with Brahman.",
  te: "మనసు ప్రశాంతమైనవాడు, రజోగుణం (చంచలత్వం) శాంతించినవాడు, పాపం లేనివాడు, బ్రహ్మస్వరూపుడైనవాడు అయిన ఈ యోగికి ఉత్తమమైన సుఖం లభిస్తుంది.",
  hi: "जिसका मन शांत है, जिसका रजोगुण (चंचलता) शांत हो गया है, जो निष्पाप है और ब्रह्मरूप हो गया है — उस योगी को उत्तम सुख प्राप्त होता है।"
},
"gita_ch6_v28": {
  en: "Practising like this always, the yogī, freed from impurity, easily enjoys the boundless joy of contact with Brahman.",
  te: "ఈ విధంగా ఎల్లప్పుడూ మనసును యోగంలో నిలుపుతూ, పాపాల నుండి విముక్తుడైన యోగి బ్రహ్మస్పర్శ వల్ల కలిగే అనంతమైన సుఖాన్ని సులభంగా అనుభవిస్తాడు.",
  hi: "इस प्रकार सदा अपने को योग में लगाता हुआ, दोषों से मुक्त योगी सहज ही ब्रह्म के स्पर्श से मिलने वाले अनंत सुख का अनुभव करता है।"
},
"gita_ch6_v29": {
  en: "One whose self is united in yoga sees the Self dwelling in all beings and all beings in the Self, seeing the same everywhere.",
  te: "యోగంతో కూడిన మనసు గలవాడు అన్నిచోట్లా సమదృష్టితో, సర్వ ప్రాణులలో ఆత్మనూ, ఆత్మలో సర్వ ప్రాణులనూ చూస్తాడు.",
  hi: "योग से युक्त आत्मा वाला, सर्वत्र समदृष्टि रखने वाला व्यक्ति आत्मा को सब प्राणियों में और सब प्राणियों को आत्मा में देखता है।"
},
"gita_ch6_v30": {
  en: "One who sees Me everywhere and sees everything in Me — I am never lost to that person, and that person is never lost to Me.",
  te: "అన్నిచోట్లా నన్ను చూసేవాడికి, అన్నిటినీ నాలో చూసేవాడికి నేను ఎప్పుడూ దూరం కాను; అతడూ నాకు ఎప్పుడూ దూరం కాడు.",
  hi: "जो मुझे सर्वत्र देखता है और सब कुछ मुझमें देखता है, उसके लिए मैं कभी ओझल नहीं होता और वह मेरे लिए कभी ओझल नहीं होता।"
},
"gita_ch6_v31": {
  en: "The yogī who, established in oneness, worships Me as dwelling in all beings — however that person lives, they live in Me.",
  te: "ఏకత్వంలో నిలిచి, సర్వ ప్రాణులలో ఉన్న నన్ను భజించే యోగి — ఏ విధంగా జీవిస్తున్నా నాలోనే జీవిస్తున్నాడు.",
  hi: "जो योगी एकत्व में स्थित होकर सब प्राणियों में स्थित मुझे भजता है, वह किसी भी प्रकार से रहते हुए मुझमें ही रहता है।"
},
"gita_ch6_v32": {
  en: "One who, taking oneself as the measure, sees everything as equal — whether it is joy or sorrow — that yogī is considered the highest, Arjuna.",
  te: "అర్జునా! తనతో పోల్చుకొని, ఇతరుల సుఖాన్నైనా దుఃఖాన్నైనా తనదానిలాగే సమంగా చూసేవాడు — ఆ యోగి అత్యుత్తముడని నా అభిప్రాయం.",
  hi: "हे अर्जुन! जो अपनी उपमा से सब जगह समान देखता है — चाहे सुख हो या दुःख — वह योगी परम श्रेष्ठ माना गया है।"
},
"gita_ch6_v33": {
  en: "Arjuna said: Madhusūdana, this yoga of evenness that You have taught — I do not see how it can last steadily, because the mind is so restless.",
  te: "అర్జునుడు అన్నాడు: మధుసూదనా! నువ్వు చెప్పిన ఈ సమత్వ యోగం — మనసు చంచలమైనది కాబట్టి — అది స్థిరంగా నిలుస్తుందని నాకు అనిపించడం లేదు.",
  hi: "अर्जुन ने कहा: हे मधुसूदन! आपने समता का जो यह योग बताया, मन की चंचलता के कारण मुझे इसकी स्थिर स्थिति दिखाई नहीं देती।"
},
"gita_ch6_v34": {
  en: "For the mind is restless, Kṛṣṇa — turbulent, powerful and stubborn. To control it, I think, is as hard as controlling the wind.",
  te: "కృష్ణా! మనసు నిజంగా చంచలమైనది, అల్లకల్లోలం చేసేది, బలమైనది, మొండిది. దాన్ని నిగ్రహించడం గాలిని పట్టుకున్నంత కష్టమని నాకు అనిపిస్తుంది.",
  hi: "हे कृष्ण! मन बड़ा चंचल, मथ डालने वाला, बलवान और हठी है। इसे वश में करना मुझे वायु को रोकने के समान अत्यंत कठिन लगता है।"
},
"gita_ch6_v35": {
  en: "The Lord said: No doubt, mighty-armed one, the mind is restless and hard to control. But, Kaunteya, it can be held by steady practice and by detachment.",
  te: "శ్రీ భగవానుడు అన్నాడు: మహాబాహూ! మనసు చంచలమైనదనీ, నిగ్రహించడం కష్టమనీ సందేహం లేదు. కానీ కౌంతేయా! అభ్యాసంతో, వైరాగ్యంతో దాన్ని వశం చేసుకోవచ్చు.",
  hi: "श्री भगवान ने कहा: हे महाबाहो! निःसंदेह मन चंचल है और कठिनाई से वश में होता है। परंतु हे कौंतेय! अभ्यास और वैराग्य से यह वश में किया जा सकता है।"
},
"gita_ch6_v36": {
  en: "For one whose mind is not controlled, yoga is hard to attain — this is My view. But one who has mastered the mind and keeps striving by the right means can attain it.",
  te: "మనసును అదుపులో ఉంచుకోనివాడికి యోగం సిద్ధించడం కష్టం — ఇది నా అభిప్రాయం. కానీ మనసును వశం చేసుకొని, సరైన ఉపాయాలతో ప్రయత్నించేవాడు దాన్ని పొందగలడు.",
  hi: "जिसका मन वश में नहीं है, उसके लिए योग पाना कठिन है — यह मेरा मत है। परंतु जिसने मन को वश में किया है और उचित उपायों से प्रयत्न करता है, वह इसे पा सकता है।"
},
"gita_ch6_v37": {
  en: "Arjuna said: Kṛṣṇa, what happens to one who has faith but does not strive enough, whose mind slips away from yoga, and who fails to reach perfection in yoga? Where does that person go?",
  te: "అర్జునుడు అన్నాడు: కృష్ణా! శ్రద్ధ ఉన్నా తగినంత ప్రయత్నం లేనివాడు, మనసు యోగం నుండి జారిపోయినవాడు, యోగసిద్ధిని పొందలేకపోయినవాడు — ఏ గతిని పొందుతాడు?",
  hi: "अर्जुन ने कहा: हे कृष्ण! जो श्रद्धा से युक्त है पर पूरा प्रयत्न नहीं करता, जिसका मन योग से विचलित हो गया और जो योग की सिद्धि नहीं पा सका — वह किस गति को जाता है?"
},
"gita_ch6_v38": {
  en: "Mighty-armed one, fallen from both, without support and confused on the path to Brahman — doesn't such a person perish like a scattered cloud?",
  te: "మహాబాహూ! రెండింటి నుండీ జారిపోయి, ఆధారం లేకుండా, బ్రహ్మమార్గంలో దారి తప్పినవాడు చెదిరిపోయిన మేఘంలా నశించిపోడా?",
  hi: "हे महाबाहो! दोनों ओर से भ्रष्ट हुआ, आश्रयहीन और ब्रह्म के मार्ग में मोहित हुआ वह व्यक्ति क्या छिन्न-भिन्न बादल की तरह नष्ट तो नहीं हो जाता?"
},
"gita_ch6_v39": {
  en: "Kṛṣṇa, please remove this doubt of mine completely. Other than You, there is no one who can clear away this doubt.",
  te: "కృష్ణా! నా ఈ సందేహాన్ని పూర్తిగా తొలగించడానికి నువ్వే తగినవాడివి. నువ్వు తప్ప ఈ సందేహాన్ని తీర్చగలవారు మరెవరూ లేరు.",
  hi: "हे कृष्ण! मेरे इस संशय को पूरी तरह मिटाने में आप ही समर्थ हैं। आपके सिवा इस संशय को दूर करने वाला कोई और नहीं हो सकता।"
},
"gita_ch6_v40": {
  en: "The Lord said: Pārtha, there is no destruction for that person, either in this world or the next. For no one who does good, My dear friend, ever comes to a bad end.",
  te: "శ్రీ భగవానుడు అన్నాడు: పార్థా! అతనికి ఈ లోకంలో గానీ పరలోకంలో గానీ నాశనం లేదు. నాయనా! మంచి చేసే ఎవడూ దుర్గతి పాలు కాడు.",
  hi: "श्री भगवान ने कहा: हे पार्थ! उसका न इस लोक में नाश होता है, न परलोक में। क्योंकि हे तात! भलाई करने वाला कोई भी दुर्गति को प्राप्त नहीं होता।"
},
"gita_ch6_v41": {
  en: "One who has fallen from yoga reaches the worlds of the virtuous, lives there for very many years, and is then born in the home of pure and prosperous people.",
  te: "యోగభ్రష్టుడు పుణ్యాత్ములు పొందే లోకాలను చేరి, అక్కడ ఎన్నో సంవత్సరాలు నివసించి, ఆ తర్వాత పవిత్రులైన, సంపన్నులైన వారి ఇంట్లో జన్మిస్తాడు.",
  hi: "योग से भ्रष्ट हुआ व्यक्ति पुण्यात्माओं के लोकों को पाकर, वहाँ बहुत वर्षों तक रहकर, फिर पवित्र और समृद्ध लोगों के घर में जन्म लेता है।"
},
"gita_ch6_v42": {
  en: "Or else they are born into a family of wise yogīs. But a birth like this is even harder to gain in this world.",
  te: "లేదా జ్ఞానవంతులైన యోగుల కుటుంబంలోనే జన్మిస్తాడు. కానీ ఇలాంటి జన్మ ఈ లోకంలో పొందడం ఇంకా దుర్లభం.",
  hi: "अथवा वह बुद्धिमान योगियों के कुल में ही जन्म लेता है। परंतु ऐसा जन्म इस संसार में और भी दुर्लभ है।"
},
"gita_ch6_v43": {
  en: "There, they regain the wisdom they had gained in their previous body, and from that point they strive once more for perfection, joy of the Kurus.",
  te: "కురునందనా! అక్కడ అతడు పూర్వ దేహంలో పొందిన బుద్ధి సంస్కారాన్ని తిరిగి పొందుతాడు; అక్కడి నుండి సిద్ధి కోసం మళ్ళీ ఇంకా ఎక్కువగా ప్రయత్నిస్తాడు.",
  hi: "हे कुरुनंदन! वहाँ वह पिछले शरीर में प्राप्त बुद्धि के संस्कार को फिर से पा लेता है, और वहाँ से सिद्धि के लिए और भी अधिक प्रयत्न करता है।"
},
"gita_ch6_v44": {
  en: "By that very past practice they are carried forward, even without trying. Even one who merely wishes to know about yoga goes beyond the mere rituals of the Vedas.",
  te: "ఆ పూర్వ అభ్యాసమే అతన్ని తనకు తెలియకుండానే ముందుకు లాగుతుంది. యోగం గురించి తెలుసుకోవాలని కోరుకున్నవాడు కూడా వేదాలలోని కేవల కర్మకాండను దాటిపోతాడు.",
  hi: "उसी पूर्व अभ्यास से वह विवश-सा होकर आगे खिंचता चला जाता है। योग को जानने की इच्छा रखने वाला भी वेदों के केवल कर्मकांड से आगे निकल जाता है।"
},
"gita_ch6_v45": {
  en: "But the yogī who strives with great effort, cleansed of all impurity and perfected over many births, then reaches the highest goal.",
  te: "కానీ పట్టుదలతో ప్రయత్నించే యోగి, పాపాలన్నిటి నుండి శుద్ధుడై, అనేక జన్మలలో సిద్ధి పొంది, ఆ తర్వాత పరమ గతిని చేరుకుంటాడు.",
  hi: "परंतु जो योगी प्रयत्नपूर्वक साधना करता है, सब दोषों से शुद्ध होकर, अनेक जन्मों में सिद्ध होकर, फिर परम गति को प्राप्त होता है।"
},
"gita_ch6_v46": {
  en: "The yogī is greater than those who practise austerities, greater even than those with mere book-learning, and greater than those who perform rituals for rewards. Therefore, Arjuna, be a yogī.",
  te: "తపస్సు చేసేవారికంటే యోగి గొప్పవాడు; కేవలం శాస్త్రజ్ఞానం ఉన్నవారికంటే కూడా గొప్పవాడని నా అభిప్రాయం; ఫలాపేక్షతో కర్మలు చేసేవారికంటే కూడా యోగి గొప్పవాడు. కాబట్టి అర్జునా! నువ్వు యోగివి అవ్వు.",
  hi: "योगी तपस्वियों से श्रेष्ठ है, केवल शास्त्रज्ञानियों से भी श्रेष्ठ माना गया है, और सकाम कर्म करने वालों से भी श्रेष्ठ है। इसलिए हे अर्जुन! तुम योगी बनो।"
},
"gita_ch6_v47": {
  en: "And of all yogīs, the one who worships Me with faith, with the inner self absorbed in Me — that one I consider the most closely united with Me.",
  te: "యోగులందరిలోనూ, తన అంతరాత్మను నాలోనే లీనం చేసి, శ్రద్ధతో నన్ను భజించేవాడే నాతో అత్యంత ఐక్యమైనవాడని నా అభిప్రాయం.",
  hi: "और सब योगियों में भी, जो श्रद्धा के साथ अपने अंतरात्मा को मुझमें लगाकर मुझे भजता है — उसे मैं सबसे श्रेष्ठ योगी (युक्ततम) मानता हूँ।"
},

// ── Chapter 7 · Jñāna Vijñāna Yoga ──
"gita_ch7_v1": {
  en: "The Lord said: Pārtha, with your mind attached to Me, practising yoga and taking refuge in Me — hear how you will know Me completely, without any doubt.",
  te: "శ్రీ భగవానుడు అన్నాడు: పార్థా! మనసును నా యందే లగ్నం చేసి, నన్నే ఆశ్రయించి యోగాన్ని అభ్యసిస్తూ, సందేహం లేకుండా నన్ను సంపూర్ణంగా ఎలా తెలుసుకుంటావో విను.",
  hi: "श्री भगवान ने कहा: हे पार्थ! मुझमें मन लगाकर, मेरा आश्रय लेकर योग का अभ्यास करते हुए, तुम मुझे बिना संशय के पूर्ण रूप से कैसे जानोगे — वह सुनो।"
},
"gita_ch7_v2": {
  en: "I will teach you this knowledge in full, together with its direct realisation. Once you know it, nothing more remains to be known here.",
  te: "అనుభవంతో కూడిన ఈ జ్ఞానాన్ని నీకు పూర్తిగా చెబుతాను. దీన్ని తెలుసుకున్న తర్వాత ఈ లోకంలో తెలుసుకోవలసినది ఇంకేమీ మిగలదు.",
  hi: "मैं तुम्हें अनुभव सहित यह ज्ञान पूरा-पूरा बताऊँगा, जिसे जान लेने के बाद यहाँ और कुछ जानने को शेष नहीं रहता।"
},
"gita_ch7_v3": {
  en: "Among thousands of people, hardly one strives for perfection; and even among those who strive and succeed, hardly one knows Me as I truly am.",
  te: "వేలాది మనుషుల్లో ఏ ఒక్కరో సిద్ధి కోసం ప్రయత్నిస్తారు; అలా ప్రయత్నించి సిద్ధి పొందినవారిలో కూడా ఏ ఒక్కరో నన్ను యథార్థంగా తెలుసుకుంటారు.",
  hi: "हज़ारों मनुष्यों में कोई एक सिद्धि के लिए प्रयास करता है, और प्रयास करने वाले सिद्धों में भी कोई एक ही मुझे तत्त्व से जानता है।"
},
"gita_ch7_v4": {
  en: "Earth, water, fire, air, space, mind, intellect and the sense of 'I' — these are the eight parts into which My material nature is divided.",
  te: "భూమి, నీరు, అగ్ని, వాయువు, ఆకాశం, మనసు, బుద్ధి, అహంకారం — ఇలా ఎనిమిది విధాలుగా విభజించబడినది నా ప్రకృతి.",
  hi: "पृथ्वी, जल, अग्नि, वायु, आकाश, मन, बुद्धि और अहंकार — ये आठ प्रकार से बँटी हुई मेरी प्रकृति है।"
},
"gita_ch7_v5": {
  en: "That is My lower nature. But know, mighty-armed one, that I have another, higher nature — the life-principle, the living beings — by which this whole world is sustained.",
  te: "ఇది నా అపర (తక్కువ) ప్రకృతి. మహాబాహూ! దీనికి భిన్నంగా, జీవరూపమైన నా పర (శ్రేష్ఠ) ప్రకృతి ఒకటి ఉందని తెలుసుకో — దాని వల్లే ఈ జగత్తు నిలిచి ఉంది.",
  hi: "यह मेरी अपरा (निचली) प्रकृति है। हे महाबाहो! इससे भिन्न मेरी एक परा (श्रेष्ठ) प्रकृति भी जानो, जो जीवरूप है और जिससे यह सारा जगत धारण किया जाता है।"
},
"gita_ch7_v6": {
  en: "Understand that all beings come from these two natures. I am the origin of the entire universe, and also its dissolution.",
  te: "సమస్త ప్రాణులూ ఈ రెండు ప్రకృతుల నుంచే పుడతాయని గ్రహించు. ఈ సమస్త జగత్తుకూ పుట్టుకనూ, లయాన్నీ నేనే.",
  hi: "समझ लो कि सब प्राणी इन्हीं दोनों प्रकृतियों से उत्पन्न होते हैं। सारे जगत की उत्पत्ति और प्रलय मैं ही हूँ।"
},
"gita_ch7_v7": {
  en: "Dhanañjaya, there is nothing whatsoever higher than Me. All this is strung on Me, like pearls on a thread.",
  te: "ధనంజయా! నాకంటే శ్రేష్ఠమైనది మరేదీ లేదు. దారంలో గుచ్చిన ముత్యాల్లాగా ఇదంతా నా యందే గుచ్చబడి ఉంది.",
  hi: "हे धनंजय! मुझसे बढ़कर दूसरा कुछ भी नहीं है। यह सब कुछ मुझमें वैसे ही पिरोया हुआ है जैसे धागे में मोती।"
},
"gita_ch7_v8": {
  en: "Kaunteya, I am the taste in water, the light of the moon and the sun, the sacred syllable Om in all the Vedas, the sound in space and the strength of manhood in people.",
  te: "కౌంతేయా! నీటిలో రుచిని నేను; చంద్రసూర్యుల్లో కాంతిని నేను; వేదాలన్నిటిలో ఓంకారాన్ని నేను; ఆకాశంలో శబ్దాన్ని, మనుషుల్లో పౌరుషాన్ని నేనే.",
  hi: "हे कौंतेय! जल में रस मैं हूँ, चंद्रमा और सूर्य में प्रकाश मैं हूँ, सब वेदों में ओंकार, आकाश में शब्द और मनुष्यों में पुरुषार्थ मैं हूँ।"
},
"gita_ch7_v9": {
  en: "I am the pure fragrance of the earth and the brilliance of fire; I am the life in all beings and the austerity of those who practise austerity.",
  te: "భూమిలోని పవిత్రమైన సువాసనను నేను, అగ్నిలోని తేజస్సును నేను; సర్వ ప్రాణుల్లో జీవాన్ని, తపస్వుల్లో తపస్సును నేనే.",
  hi: "पृथ्वी में पवित्र गंध और अग्नि में तेज मैं हूँ; सब प्राणियों में जीवन और तपस्वियों में तप मैं हूँ।"
},
"gita_ch7_v10": {
  en: "Pārtha, know Me as the eternal seed of all beings. I am the intelligence of the intelligent and the radiance of the radiant.",
  te: "పార్థా! సర్వ ప్రాణులకూ శాశ్వతమైన బీజాన్ని నేనే అని తెలుసుకో. బుద్ధిమంతుల్లో బుద్ధిని, తేజస్వుల్లో తేజస్సును నేనే.",
  hi: "हे पार्थ! मुझे सब प्राणियों का सनातन बीज जानो। बुद्धिमानों की बुद्धि और तेजस्वियों का तेज मैं हूँ।"
},
"gita_ch7_v11": {
  en: "Of the strong, I am the strength that is free from craving and attachment. And in beings, best of the Bharatas, I am the desire that is not against dharma.",
  te: "బలవంతుల్లో కోరికా, ఆసక్తీ లేని బలాన్ని నేను. భరతశ్రేష్ఠా! ప్రాణుల్లో ధర్మానికి విరుద్ధం కాని కామాన్ని నేనే.",
  hi: "बलवानों में कामना और आसक्ति से रहित बल मैं हूँ। हे भरतश्रेष्ठ! प्राणियों में धर्म के अनुकूल काम (इच्छा) मैं हूँ।"
},
"gita_ch7_v12": {
  en: "Whatever states of being there are — pure (sāttvic), restless (rājasic) or dull (tāmasic) — know that they all come from Me alone. Yet I am not in them; they are in Me.",
  te: "సాత్త్విక, రాజస, తామస భావాలు ఏవైనా — అవన్నీ నా నుంచే పుట్టాయని తెలుసుకో. అయితే నేను వాటిలో లేను; అవే నాలో ఉన్నాయి.",
  hi: "जो भी सात्त्विक, राजसिक और तामसिक भाव हैं, उन सबको मुझसे ही उत्पन्न जानो। परंतु मैं उनमें नहीं हूँ, वे मुझमें हैं।"
},
"gita_ch7_v13": {
  en: "Deluded by these three kinds of qualities, this whole world does not recognise Me, who am beyond them and imperishable.",
  te: "ఈ మూడు గుణాలతో కూడిన భావాల వల్ల మోహంలో పడిన ఈ లోకమంతా, వాటికి అతీతుడనూ, నాశనం లేనివాడనూ అయిన నన్ను గుర్తించడం లేదు.",
  hi: "इन तीन गुणों वाले भावों से मोहित होकर यह सारा जगत, इनसे परे और अविनाशी मुझको नहीं पहचानता।"
},
"gita_ch7_v14": {
  en: "This divine māyā of Mine, made of the three qualities, is very hard to cross. But those who take refuge in Me alone cross over it.",
  te: "త్రిగుణాలతో కూడిన ఈ నా దైవీ మాయను దాటడం చాలా కష్టం. కానీ నన్నే శరణు పొందినవారు ఈ మాయను దాటిపోతారు.",
  hi: "यह मेरी त्रिगुणमयी दैवी माया बड़ी कठिनाई से पार होने वाली है। परंतु जो केवल मेरी शरण लेते हैं, वे इस माया को पार कर जाते हैं।"
},
"gita_ch7_v15": {
  en: "Evil-doers, the deluded and the lowest of people do not come to Me — their understanding is stolen away by māyā, and they cling to a demonic nature.",
  te: "దుష్కర్మలు చేసేవారు, మూఢులు, నరాధములు నన్ను శరణు పొందరు — మాయ వారి జ్ఞానాన్ని హరించింది; వారు ఆసుర స్వభావాన్ని ఆశ్రయించారు.",
  hi: "दुष्कर्म करने वाले, मूढ़ और अधम मनुष्य मेरी शरण नहीं लेते — माया ने उनका ज्ञान हर लिया है और वे आसुरी स्वभाव का आश्रय लिए हुए हैं।"
},
"gita_ch7_v16": {
  en: "Arjuna, four kinds of good people worship Me: the one in distress, the one who seeks knowledge, the one who seeks wealth or welfare, and the wise one, best of the Bharatas.",
  te: "అర్జునా! నాలుగు రకాల పుణ్యాత్ములు నన్ను భజిస్తారు — కష్టాల్లో ఉన్నవాడు, తెలుసుకోవాలనుకునేవాడు, ఏదైనా కోరి వచ్చేవాడు, జ్ఞాని.",
  hi: "हे अर्जुन! चार प्रकार के पुण्यात्मा मुझे भजते हैं — दुखी (आर्त), जिज्ञासु, कुछ पाने की इच्छा वाला (अर्थार्थी) और ज्ञानी, हे भरतश्रेष्ठ।"
},
"gita_ch7_v17": {
  en: "Of them the wise one, ever united with Me and devoted to Me alone, stands out. I am exceedingly dear to the wise, and the wise one is dear to Me.",
  te: "వారిలో ఎల్లప్పుడూ నాతో కూడి ఉండి, నా మీదే ఏకాగ్ర భక్తి కలిగిన జ్ఞాని శ్రేష్ఠుడు. జ్ఞానికి నేను అత్యంత ప్రియుణ్ణి; అతడూ నాకు ప్రియుడే.",
  hi: "उनमें सदा मुझसे जुड़ा हुआ, केवल मेरी भक्ति करने वाला ज्ञानी श्रेष्ठ है। ज्ञानी को मैं अत्यंत प्रिय हूँ और वह मुझे प्रिय है।"
},
"gita_ch7_v18": {
  en: "All of these are noble, but the wise one I consider My very Self. With a steady mind, he rests in Me alone as the highest goal.",
  te: "వీరందరూ ఉదారులే; కానీ జ్ఞాని నా ఆత్మయే అని నా అభిప్రాయం. ఎందుకంటే స్థిరమైన మనసుతో అతడు నన్నే అత్యుత్తమ గమ్యంగా ఆశ్రయించి ఉంటాడు.",
  hi: "ये सभी उदार हैं, परंतु ज्ञानी को मैं अपना आत्मा ही मानता हूँ। क्योंकि स्थिर मन वाला वह मुझे ही सर्वोत्तम गति मानकर मुझमें स्थित रहता है।"
},
"gita_ch7_v19": {
  en: "At the end of many births, the wise one comes to Me, realising 'Vāsudeva is everything'. Such a great soul is very hard to find.",
  te: "ఎన్నో జన్మల చివర, ‘వాసుదేవుడే సర్వమూ’ అని గ్రహించిన జ్ఞాని నన్ను చేరుకుంటాడు. అలాంటి మహాత్ముడు దొరకడం చాలా అరుదు.",
  hi: "अनेक जन्मों के अंत में ज्ञानी ‘वासुदेव ही सब कुछ है’ — ऐसा जानकर मेरी शरण आता है। ऐसा महात्मा अत्यंत दुर्लभ है।"
},
"gita_ch7_v20": {
  en: "Those whose understanding is carried away by this desire or that turn to other deities, following various rules, led by their own nature.",
  te: "రకరకాల కోరికల వల్ల జ్ఞానం హరించబడినవారు, తమ తమ స్వభావానికి లోబడి, ఆయా నియమాలను పాటిస్తూ ఇతర దేవతలను ఆశ్రయిస్తారు.",
  hi: "जिनका ज्ञान तरह-तरह की कामनाओं ने हर लिया है, वे अपने-अपने स्वभाव से प्रेरित होकर, उन-उन नियमों को अपनाकर अन्य देवताओं की शरण लेते हैं।"
},
"gita_ch7_v21": {
  en: "Whatever form a devotee wishes to worship with faith, I make that very faith of his firm and steady.",
  te: "ఏ భక్తుడు ఏ రూపాన్ని శ్రద్ధతో పూజించాలనుకుంటాడో, అతని ఆ శ్రద్ధనే నేను స్థిరంగా నిలుపుతాను.",
  hi: "जो-जो भक्त जिस-जिस रूप को श्रद्धा से पूजना चाहता है, उस-उस भक्त की उसी श्रद्धा को मैं स्थिर कर देता हूँ।"
},
"gita_ch7_v22": {
  en: "Endowed with that faith, he worships that form and from it gains what he desires — but those wishes are in truth granted by Me alone.",
  te: "ఆ శ్రద్ధతో కూడి అతడు ఆ దేవతను ఆరాధిస్తాడు, దాని ద్వారా తన కోరికలను పొందుతాడు — కానీ నిజానికి ఆ ఫలాలను ఇచ్చేది నేనే.",
  hi: "उस श्रद्धा से युक्त होकर वह उस देवता की आराधना करता है और उससे अपनी कामनाएँ पाता है — परंतु वे फल वास्तव में मेरे द्वारा ही दिए जाते हैं।"
},
"gita_ch7_v23": {
  en: "But the fruit gained by those of small understanding is perishable. Worshippers of the gods go to the gods; My devotees come to Me.",
  te: "అల్పబుద్ధులైన వారు పొందే ఆ ఫలం నశించిపోయేదే. దేవతలను పూజించేవారు దేవతలను చేరుకుంటారు; నా భక్తులు నన్నే చేరుకుంటారు.",
  hi: "परंतु उन अल्पबुद्धि लोगों को मिलने वाला वह फल नाशवान होता है। देवताओं को पूजने वाले देवताओं को प्राप्त होते हैं, मेरे भक्त मुझे ही प्राप्त होते हैं।"
},
"gita_ch7_v24": {
  en: "The unwise think of Me, the Unmanifest, as having merely taken on a visible form, not knowing My supreme nature, which is imperishable and unsurpassed.",
  te: "అవివేకులు, అవ్యక్తుడనైన నన్ను కేవలం ఒక వ్యక్త రూపం పొందినవాడిగా భావిస్తారు — నాశనం లేని, అత్యుత్తమమైన నా పరమ స్వరూపాన్ని వారు ఎరుగరు.",
  hi: "अज्ञानी लोग मुझ अव्यक्त को केवल व्यक्त रूप में आया हुआ मानते हैं; वे मेरे अविनाशी और सर्वोत्तम परम स्वरूप को नहीं जानते।"
},
"gita_ch7_v25": {
  en: "Veiled by My yoga-māyā, I am not revealed to everyone. This deluded world does not know Me, the unborn and unchanging.",
  te: "నా యోగమాయతో కప్పబడి ఉండటం వల్ల నేను అందరికీ కనిపించను. మోహంలో ఉన్న ఈ లోకం, పుట్టుక లేనివాడనూ, మార్పు లేనివాడనూ అయిన నన్ను తెలుసుకోదు.",
  hi: "अपनी योगमाया से ढका होने के कारण मैं सबके सामने प्रकट नहीं होता। यह मोहित संसार मुझ अजन्मा और अविनाशी को नहीं जानता।"
},
"gita_ch7_v26": {
  en: "Arjuna, I know all beings — those of the past, the present and those yet to come. But no one knows Me.",
  te: "అర్జునా! గతించిన, ఇప్పుడు ఉన్న, ఇకపై రాబోయే ప్రాణులందరినీ నేను ఎరుగుదును. కానీ నన్ను మాత్రం ఎవరూ ఎరుగరు.",
  hi: "हे अर्जुन! भूतकाल के, वर्तमान के और भविष्य के सब प्राणियों को मैं जानता हूँ, परंतु मुझे कोई नहीं जानता।"
},
"gita_ch7_v27": {
  en: "Bhārata, scorcher of foes, from birth itself all beings fall into confusion through the delusion of opposites that arises from liking and disliking.",
  te: "భారతా! పరంతపా! ఇష్టం, ద్వేషం నుంచి పుట్టే ద్వంద్వ మోహం వల్ల, సమస్త ప్రాణులూ పుట్టుకతోనే మోహంలో పడిపోతాయి.",
  hi: "हे भारत! हे परंतप! इच्छा और द्वेष से उत्पन्न द्वंद्व-मोह के कारण सब प्राणी जन्म से ही मोह में पड़ जाते हैं।"
},
"gita_ch7_v28": {
  en: "But people of good deeds, whose wrongdoing has come to an end, are freed from the delusion of opposites and worship Me with firm resolve.",
  te: "కానీ పుణ్యకర్మలు చేసి, పాపాలు అంతమైపోయినవారు ద్వంద్వ మోహం నుంచి విముక్తులై, దృఢ వ్రతంతో నన్ను భజిస్తారు.",
  hi: "परंतु जिन पुण्यकर्मी लोगों के पाप समाप्त हो गए हैं, वे द्वंद्व-मोह से मुक्त होकर दृढ़ निश्चय के साथ मुझे भजते हैं।"
},
"gita_ch7_v29": {
  en: "Those who take refuge in Me and strive for freedom from old age and death come to know Brahman fully, the inner Self, and all about action.",
  te: "నన్ను ఆశ్రయించి, ముసలితనం, మరణం నుంచి విముక్తి కోసం ప్రయత్నించేవారు — ఆ బ్రహ్మాన్నీ, అధ్యాత్మాన్నీ, సమస్త కర్మనూ సంపూర్ణంగా తెలుసుకుంటారు.",
  hi: "जो मेरा आश्रय लेकर बुढ़ापे और मृत्यु से छूटने का प्रयत्न करते हैं, वे उस ब्रह्म को, संपूर्ण अध्यात्म को और सारे कर्म को जान लेते हैं।"
},
"gita_ch7_v30": {
  en: "Those who know Me as the ground of all beings (adhibhūta), of the gods (adhidaiva) and of sacrifice (adhiyajña) — with minds united in Me, they know Me even at the time of departing from this world.",
  te: "అధిభూతంగా, అధిదైవంగా, అధియజ్ఞంగా నన్ను తెలుసుకున్నవారు — నాతో కూడిన మనసుతో, ఈ లోకాన్ని విడిచే సమయంలో కూడా నన్ను తెలుసుకునే ఉంటారు.",
  hi: "जो मुझे अधिभूत, अधिदैव और अधियज्ञ सहित जानते हैं, वे मुझमें लगे चित्त वाले लोग प्रयाणकाल (मृत्यु के समय) में भी मुझे जानते हैं।"
},

// ── Chapter 8 · Akṣara Brahma Yoga ──
"gita_ch8_v1": {
  en: "Arjuna said: Puruṣottama, what is that Brahman? What is the inner Self (adhyātma)? What is action? What is said to be the ground of beings (adhibhūta), and what is called the ground of the gods (adhidaiva)? —",
  te: "అర్జునుడు అన్నాడు: పురుషోత్తమా! ఆ బ్రహ్మం ఏది? అధ్యాత్మం అంటే ఏమిటి? కర్మ అంటే ఏమిటి? అధిభూతం అని దేన్ని అంటారు? అధిదైవం అని దేన్ని చెబుతారు? —",
  hi: "अर्जुन ने कहा: हे पुरुषोत्तम! वह ब्रह्म क्या है? अध्यात्म क्या है? कर्म क्या है? अधिभूत किसे कहा गया है और अधिदैव किसे कहते हैं? —"
},
"gita_ch8_v2": {
  en: "— Madhusūdana, who is the Lord of sacrifice (adhiyajña) here in this body, and how does He dwell in it? And at the time of death, how are You to be known by those whose minds are disciplined?",
  te: "— మధుసూదనా! ఈ శరీరంలో అధియజ్ఞుడు ఎవరు, ఆయన ఇందులో ఎలా ఉన్నాడు? మనసును నిగ్రహించుకున్నవారు మరణ సమయంలో నిన్ను ఎలా తెలుసుకుంటారు?",
  hi: "— हे मधुसूदन! इस शरीर में अधियज्ञ कौन है और वह इसमें कैसे है? और संयमित मन वाले लोग मृत्यु के समय आपको कैसे जानते हैं?"
},
"gita_ch8_v3": {
  en: "The Lord said: The Imperishable, the Supreme, is Brahman. Its presence as one's own being is called adhyātma. The creative offering that brings beings into existence is called action (karma).",
  te: "శ్రీ భగవానుడు అన్నాడు: నాశనం లేని పరమ తత్త్వమే బ్రహ్మం. ప్రతి జీవిలో దాని స్వభావంగా ఉండటాన్ని అధ్యాత్మం అంటారు. ప్రాణుల పుట్టుకకు కారణమైన సృష్టి కార్యాన్ని కర్మ అంటారు.",
  hi: "श्री भगवान ने कहा: अविनाशी परम तत्त्व ब्रह्म है। प्रत्येक जीव में उसका अपना स्वभाव अध्यात्म कहलाता है। प्राणियों को उत्पन्न करने वाला सृष्टि-कार्य कर्म कहलाता है।"
},
"gita_ch8_v4": {
  en: "The perishable world of things is adhibhūta; the cosmic Person is adhidaiva; and I Myself, dwelling here in the body, am adhiyajña, O best of the embodied.",
  te: "నశించిపోయే పదార్థ ప్రపంచమే అధిభూతం; విశ్వ పురుషుడే అధిదైవం; దేహధారుల్లో శ్రేష్ఠుడా! ఈ శరీరంలోనే ఉన్న నేనే అధియజ్ఞుణ్ణి.",
  hi: "नाशवान पदार्थ-जगत अधिभूत है; विश्व-पुरुष अधिदैव है; और हे देहधारियों में श्रेष्ठ! इस शरीर में रहने वाला मैं ही अधियज्ञ हूँ।"
},
"gita_ch8_v5": {
  en: "And whoever, at the end, leaves the body remembering Me alone, reaches My state of being — of this there is no doubt.",
  te: "అంత్యకాలంలో నన్నే స్మరిస్తూ శరీరాన్ని విడిచి వెళ్ళేవాడు నా స్వరూపాన్నే పొందుతాడు — ఇందులో సందేహం లేదు.",
  hi: "और जो अंत समय में मेरा ही स्मरण करते हुए शरीर छोड़कर जाता है, वह मेरे भाव को प्राप्त होता है — इसमें कोई संशय नहीं।"
},
"gita_ch8_v6": {
  en: "Kaunteya, whatever state of being a person remembers at the end while leaving the body, that very state he attains — because he has always been absorbed in it.",
  te: "కౌంతేయా! అంత్యకాలంలో ఏ భావాన్ని స్మరిస్తూ మనిషి శరీరాన్ని విడుస్తాడో, ఆ భావాన్నే పొందుతాడు — ఎందుకంటే ఎల్లప్పుడూ అతడు ఆ భావంలోనే మునిగి ఉన్నాడు.",
  hi: "हे कौंतेय! अंत समय में मनुष्य जिस-जिस भाव का स्मरण करते हुए शरीर छोड़ता है, उसी-उसी को प्राप्त होता है — क्योंकि वह सदा उसी भाव में रँगा रहा है।"
},
"gita_ch8_v7": {
  en: "Therefore remember Me at all times — and fight. With your mind and intellect offered to Me, you will surely come to Me.",
  te: "కాబట్టి అన్ని సమయాల్లోనూ నన్ను స్మరించు — యుద్ధం చెయ్యి. మనసునూ బుద్ధినీ నాకు అర్పించినవాడివై, నువ్వు నిస్సందేహంగా నన్నే చేరుకుంటావు.",
  hi: "इसलिए हर समय मेरा स्मरण करो — और युद्ध करो। मन और बुद्धि मुझे अर्पित करके तुम निःसंदेह मुझे ही प्राप्त होगे।"
},
"gita_ch8_v8": {
  en: "Pārtha, with a mind trained by steady practice that does not wander elsewhere, constantly thinking of the supreme divine Person, one reaches Him.",
  te: "పార్థా! అభ్యాసయోగంతో కూడి, వేరే వైపుకు పోని మనసుతో, దివ్యుడైన పరమ పురుషుణ్ణి నిరంతరం చింతించేవాడు ఆయననే చేరుకుంటాడు.",
  hi: "हे पार्थ! अभ्यास-योग से युक्त, कहीं और न भटकने वाले मन से दिव्य परम पुरुष का निरंतर चिंतन करने वाला उसी को प्राप्त होता है।"
},
"gita_ch8_v9": {
  en: "One should meditate on Him who is all-knowing, ancient, the ruler of all, subtler than the subtlest, the sustainer of everything, of a form beyond thought, shining like the sun and beyond all darkness —",
  te: "సర్వజ్ఞుడూ, పురాతనుడూ, అందరినీ శాసించేవాడూ, అణువుకంటే సూక్ష్మమైనవాడూ, అన్నిటినీ ధరించేవాడూ, ఊహకు అందని రూపం కలవాడూ, సూర్యుడిలా ప్రకాశించేవాడూ, చీకటికి అతీతుడూ అయిన ఆయనను స్మరించాలి —",
  hi: "जो सर्वज्ञ, सनातन, सबका शासक, सूक्ष्म से भी सूक्ष्म, सबको धारण करने वाला, अचिंत्य रूप वाला, सूर्य के समान प्रकाशमान और अंधकार से परे है — उसका स्मरण करना चाहिए —"
},
"gita_ch8_v10": {
  en: "— at the time of departure, with an unwavering mind, filled with devotion and by the strength of yoga, drawing the life-breath fully between the eyebrows, he reaches that supreme divine Person.",
  te: "— ప్రయాణ సమయంలో చలించని మనసుతో, భక్తితో, యోగబలంతో, ప్రాణాన్ని కనుబొమల మధ్య సరిగ్గా నిలిపి, అతడు ఆ దివ్యమైన పరమ పురుషుణ్ణి చేరుకుంటాడు.",
  hi: "— प्रयाणकाल में अचल मन से, भक्ति और योगबल से युक्त होकर, प्राण को भौंहों के बीच भली-भाँति स्थापित करके, वह उस दिव्य परम पुरुष को प्राप्त होता है।"
},
"gita_ch8_v11": {
  en: "That which knowers of the Veda call the Imperishable, which the self-controlled, free from passion, enter, and desiring which people live a life of brahmacarya — that goal I will briefly explain to you.",
  te: "వేదవేత్తలు దేన్ని అక్షరం అంటారో, రాగం లేని యతులు దేనిలో ప్రవేశిస్తారో, దేన్ని కోరి బ్రహ్మచర్యాన్ని పాటిస్తారో — ఆ పదాన్ని నీకు సంక్షిప్తంగా చెబుతాను.",
  hi: "वेद के जानकार जिसे अक्षर कहते हैं, रागरहित यति जिसमें प्रवेश करते हैं, और जिसकी इच्छा से लोग ब्रह्मचर्य का पालन करते हैं — उस पद को मैं तुम्हें संक्षेप में बताऊँगा।"
},
"gita_ch8_v12": {
  en: "Closing all the gates of the senses, holding the mind within the heart, placing the life-breath at the top of the head and established in yogic concentration —",
  te: "ఇంద్రియ ద్వారాలన్నిటినీ మూసి, మనసును హృదయంలో నిలిపి, ప్రాణాన్ని శిరస్సులో ఉంచి, యోగధారణలో స్థిరంగా ఉండి —",
  hi: "इंद्रियों के सब द्वारों को रोककर, मन को हृदय में स्थिर करके, प्राण को मस्तक में स्थापित करके, योग-धारणा में स्थित होकर —"
},
"gita_ch8_v13": {
  en: "— uttering Om, the one syllable that is Brahman, and remembering Me, whoever departs leaving the body reaches the highest goal.",
  te: "— బ్రహ్మస్వరూపమైన ‘ఓం’ అనే ఏకాక్షరాన్ని ఉచ్చరిస్తూ, నన్ను స్మరిస్తూ శరీరాన్ని విడిచి వెళ్ళేవాడు పరమ గతిని పొందుతాడు.",
  hi: "— ब्रह्मरूप एक अक्षर ‘ॐ’ का उच्चारण करते हुए और मेरा स्मरण करते हुए जो शरीर छोड़कर जाता है, वह परम गति को प्राप्त होता है।"
},
"gita_ch8_v14": {
  en: "Pārtha, for the yogī who remembers Me constantly, every day, with a mind turned to nothing else, ever united with Me — I am easy to reach.",
  te: "పార్థా! వేరే దేని మీదా మనసు పెట్టకుండా, ప్రతిరోజూ నిరంతరం నన్ను స్మరించే, ఎల్లప్పుడూ నాతో కూడి ఉండే యోగికి నేను సులభంగా లభిస్తాను.",
  hi: "हे पार्थ! जो अनन्य चित्त से प्रतिदिन निरंतर मेरा स्मरण करता है, उस सदा मुझसे जुड़े योगी के लिए मैं सुलभ हूँ।"
},
"gita_ch8_v15": {
  en: "Having come to Me, these great souls do not take rebirth, which is the home of sorrow and impermanent — they have reached the highest perfection.",
  te: "నన్ను చేరుకున్న ఆ మహాత్ములు, దుఃఖాలకు నిలయమైన, శాశ్వతం కాని పునర్జన్మను మళ్ళీ పొందరు — వారు పరమ సిద్ధిని పొందారు.",
  hi: "मुझे प्राप्त करके वे महात्मा दुखों के घर और अनित्य पुनर्जन्म को फिर नहीं पाते — वे परम सिद्धि को प्राप्त हो चुके हैं।"
},
"gita_ch8_v16": {
  en: "Arjuna, all worlds up to the realm of Brahmā are subject to return. But, Kaunteya, on reaching Me there is no rebirth.",
  te: "అర్జునా! బ్రహ్మలోకం వరకు ఉన్న లోకాలన్నీ మళ్ళీ తిరిగి రావలసినవే. కానీ కౌంతేయా! నన్ను చేరుకున్నవారికి మళ్ళీ జన్మ ఉండదు.",
  hi: "हे अर्जुन! ब्रह्मलोक तक के सभी लोक पुनरावर्ती हैं (वहाँ से लौटना पड़ता है)। परंतु हे कौंतेय! मुझे प्राप्त होने पर पुनर्जन्म नहीं होता।"
},
"gita_ch8_v17": {
  en: "Those who understand day and night truly know that a day of Brahmā lasts a thousand ages (yugas), and his night also ends after a thousand ages.",
  te: "బ్రహ్మదేవుని ఒక పగలు వెయ్యి యుగాలు, ఆయన రాత్రి కూడా వెయ్యి యుగాలు అని తెలుసుకున్నవారే పగలూ రాత్రుల తత్త్వం తెలిసినవారు.",
  hi: "जो जानते हैं कि ब्रह्मा का एक दिन हज़ार युगों का है और उनकी रात भी हज़ार युगों में समाप्त होती है, वे ही दिन-रात के तत्त्व को जानने वाले हैं।"
},
"gita_ch8_v18": {
  en: "When Brahmā's day dawns, all manifest things come forth from the Unmanifest; when his night falls, they dissolve back into that same Unmanifest.",
  te: "బ్రహ్మదేవుని పగలు మొదలైనప్పుడు వ్యక్తమైనవన్నీ అవ్యక్తం నుంచి పుడతాయి; రాత్రి రాగానే ఆ అవ్యక్తంలోనే మళ్ళీ లీనమైపోతాయి.",
  hi: "ब्रह्मा का दिन आने पर सब व्यक्त पदार्थ अव्यक्त से प्रकट होते हैं; और रात आने पर उसी अव्यक्त में लीन हो जाते हैं।"
},
"gita_ch8_v19": {
  en: "Pārtha, this same multitude of beings comes into being again and again, and helplessly dissolves when night falls, and comes forth again when day dawns.",
  te: "పార్థా! ఇదే ప్రాణి సమూహం మళ్ళీ మళ్ళీ పుడుతూ, రాత్రి రాగానే అవశంగా లయమైపోతుంది; పగలు రాగానే మళ్ళీ పుడుతుంది.",
  hi: "हे पार्थ! यही प्राणी-समूह बार-बार उत्पन्न होकर रात आने पर विवश होकर लीन हो जाता है, और दिन आने पर फिर प्रकट होता है।"
},
"gita_ch8_v20": {
  en: "But beyond that Unmanifest there is another, eternal Unmanifest reality, which does not perish even when all beings perish.",
  te: "కానీ ఆ అవ్యక్తానికి కూడా అతీతమైన, శాశ్వతమైన మరొక అవ్యక్త తత్త్వం ఉంది — సమస్త ప్రాణులూ నశించినా అది నశించదు.",
  hi: "परंतु उस अव्यक्त से भी परे एक दूसरा सनातन अव्यक्त भाव है, जो सब प्राणियों के नष्ट होने पर भी नष्ट नहीं होता।"
},
"gita_ch8_v21": {
  en: "That Unmanifest is called the Imperishable, and it is declared to be the highest goal. Reaching it, none return — that is My supreme abode.",
  te: "ఆ అవ్యక్తాన్నే అక్షరం అంటారు; అదే పరమ గతి అని చెబుతారు. దాన్ని చేరుకున్నవారు తిరిగి రారు — అదే నా పరమ ధామం.",
  hi: "उसी अव्यक्त को अक्षर कहा गया है और उसे ही परम गति बताया गया है। जिसे पाकर कोई लौटता नहीं — वही मेरा परम धाम है।"
},
"gita_ch8_v22": {
  en: "Pārtha, that supreme Person, within whom all beings dwell and by whom all this is pervaded, is reached by undivided devotion.",
  te: "పార్థా! ఎవరిలో సమస్త ప్రాణులూ ఉన్నాయో, ఎవరితో ఇదంతా వ్యాపించి ఉందో, ఆ పరమ పురుషుడు అనన్య భక్తితోనే లభిస్తాడు.",
  hi: "हे पार्थ! जिसके भीतर सब प्राणी हैं और जिससे यह सब व्याप्त है, वह परम पुरुष अनन्य भक्ति से ही प्राप्त होता है।"
},
"gita_ch8_v23": {
  en: "Best of the Bharatas, I will now tell you the times at which yogīs depart and do not return, and the times at which they depart and return.",
  te: "భరతశ్రేష్ఠా! ఏ కాలంలో శరీరం విడిచిన యోగులు తిరిగి రారో, ఏ కాలంలో విడిచినవారు తిరిగి వస్తారో — ఆ కాలాన్ని నీకు చెబుతాను.",
  hi: "हे भरतश्रेष्ठ! जिस काल में शरीर छोड़कर गए योगी लौटते नहीं, और जिसमें गए हुए लौट आते हैं — वह काल मैं तुम्हें बताऊँगा।"
},
"gita_ch8_v24": {
  en: "Fire, light, daytime, the bright half of the month, the six months of the sun's northern course — departing by this path, those who know Brahman go to Brahman.",
  te: "అగ్ని, వెలుగు, పగలు, శుక్లపక్షం, ఉత్తరాయణంలోని ఆరు నెలలు — ఈ మార్గంలో వెళ్ళిన బ్రహ్మవేత్తలు బ్రహ్మాన్నే చేరుకుంటారు.",
  hi: "अग्नि, ज्योति, दिन, शुक्ल पक्ष और उत्तरायण के छह महीने — इस मार्ग से जाने वाले ब्रह्मवेत्ता ब्रह्म को प्राप्त होते हैं।"
},
"gita_ch8_v25": {
  en: "Smoke, night, the dark half of the month, the six months of the sun's southern course — the yogī who goes by this path reaches the light of the moon and returns.",
  te: "పొగ, రాత్రి, కృష్ణపక్షం, దక్షిణాయనంలోని ఆరు నెలలు — ఈ మార్గంలో వెళ్ళిన యోగి చంద్రుని కాంతిని పొంది మళ్ళీ తిరిగి వస్తాడు.",
  hi: "धुआँ, रात, कृष्ण पक्ष और दक्षिणायन के छह महीने — इस मार्ग से गया योगी चंद्रमा की ज्योति पाकर लौट आता है।"
},
"gita_ch8_v26": {
  en: "These two paths of the world, the bright and the dark, are considered eternal. By one, a person goes and does not return; by the other, he comes back again.",
  te: "లోకానికి సంబంధించిన ఈ శుక్ల, కృష్ణ మార్గాలు రెండూ శాశ్వతమైనవని భావిస్తారు. ఒకదాని ద్వారా వెళ్ళినవాడు తిరిగి రాడు; మరొకదాని ద్వారా వెళ్ళినవాడు మళ్ళీ తిరిగి వస్తాడు.",
  hi: "जगत के ये शुक्ल और कृष्ण — दोनों मार्ग सनातन माने गए हैं। एक से जाने वाला लौटता नहीं, दूसरे से जाने वाला फिर लौट आता है।"
},
"gita_ch8_v27": {
  en: "Pārtha, no yogī who knows these two paths is ever confused. Therefore, Arjuna, at all times be steadfast in yoga.",
  te: "పార్థా! ఈ రెండు మార్గాలు తెలిసిన ఏ యోగీ మోహంలో పడడు. కాబట్టి అర్జునా! అన్ని కాలాల్లోనూ యోగయుక్తుడివై ఉండు.",
  hi: "हे पार्थ! इन दोनों मार्गों को जानने वाला कोई भी योगी मोहित नहीं होता। इसलिए हे अर्जुन! तुम हर समय योग से युक्त रहो।"
},
"gita_ch8_v28": {
  en: "Whatever merit is promised for studying the Vedas, for sacrifices, austerities and charity — the yogī who knows this goes beyond all of it and reaches the supreme, primal abode.",
  te: "వేదాధ్యయనం, యజ్ఞాలు, తపస్సులు, దానాలు — వీటికి ఏ పుణ్యఫలం చెప్పబడిందో, ఇది తెలుసుకున్న యోగి వాటన్నిటినీ దాటిపోయి, ఆదియైన పరమ స్థానాన్ని చేరుకుంటాడు.",
  hi: "वेदों के अध्ययन, यज्ञों, तपों और दानों का जो पुण्यफल बताया गया है, इसे जानने वाला योगी उन सबसे आगे निकलकर आदि परम स्थान को प्राप्त होता है।"
},

// ── Chapter 9 · Rāja Vidyā Rāja Guhya Yoga ──
"gita_ch9_v1": {
  en: "The Lord said: Because you do not find fault, I will now tell you this most secret knowledge, together with the experience of it. Knowing it, you will be freed from all that is harmful.",
  te: "శ్రీ భగవానుడు అన్నాడు: నీకు అసూయ లేదు, కాబట్టి అత్యంత రహస్యమైన ఈ జ్ఞానాన్ని, దాని అనుభవంతో కలిపి నీకు చెబుతాను. దీనిని తెలుసుకుంటే నువ్వు అశుభం అంతటి నుండీ విముక్తుడవుతావు.",
  hi: "श्री भगवान ने कहा: तुम दोष नहीं निकालते, इसलिए मैं तुम्हें यह सबसे गोपनीय ज्ञान, उसके अनुभव सहित बताऊँगा। इसे जानकर तुम सब अशुभ से मुक्त हो जाओगे।"
},
"gita_ch9_v2": {
  en: "This is the king of all knowledge, the king of secrets, supremely pure. It can be directly experienced, it is in harmony with dharma, it is very easy to practise, and it never perishes.",
  te: "ఇది విద్యలన్నిటికీ రాజు, రహస్యాలన్నిటికీ రాజు, అత్యంత పవిత్రమైనది. దీనిని నేరుగా అనుభవించవచ్చు, ఇది ధర్మానికి అనుగుణమైనది, ఆచరించడం చాలా సులభం, ఇది ఎన్నటికీ నశించదు.",
  hi: "यह सब विद्याओं का राजा है, सब रहस्यों का राजा है, परम पवित्र है। इसका प्रत्यक्ष अनुभव हो सकता है, यह धर्म के अनुकूल है, इसका पालन बहुत सरल है और यह कभी नष्ट नहीं होता।"
},
"gita_ch9_v3": {
  en: "Parantapa, people who have no faith in this dharma do not reach Me; they return again and again to the path of death and worldly existence.",
  te: "పరంతపా! ఈ ధర్మం మీద శ్రద్ధ లేని మనుషులు నన్ను చేరుకోలేక, మళ్ళీ మళ్ళీ మరణంతో కూడిన సంసార మార్గంలోకే తిరిగి వస్తారు.",
  hi: "हे परंतप! इस धर्म में श्रद्धा न रखने वाले लोग मुझे प्राप्त नहीं होते; वे बार-बार मृत्यु और संसार के मार्ग पर लौट आते हैं।"
},
"gita_ch9_v4": {
  en: "This whole universe is pervaded by Me in My unmanifest form. All beings rest in Me, but I do not rest in them.",
  te: "అవ్యక్తమైన నా రూపంతో ఈ జగత్తంతా నేను వ్యాపించి ఉన్నాను. ప్రాణులన్నీ నాలో ఉన్నాయి, కానీ నేను వాటిలో ఆధారపడి లేను.",
  hi: "मेरे अव्यक्त रूप से यह सारा जगत व्याप्त है। सब प्राणी मुझमें स्थित हैं, परंतु मैं उनमें स्थित नहीं हूँ।"
},
"gita_ch9_v5": {
  en: "And yet beings do not truly rest in Me — behold My divine power! My Self sustains all beings and brings them into existence, yet it does not dwell in them.",
  te: "అయినా ప్రాణులు నిజంగా నాలో లేవు — నా దివ్యమైన యోగశక్తిని చూడు! నా ఆత్మ ప్రాణులన్నిటినీ పోషిస్తూ, వాటిని పుట్టిస్తూ ఉన్నా, వాటిలో నివసించదు.",
  hi: "फिर भी प्राणी वास्तव में मुझमें स्थित नहीं हैं — मेरी दिव्य योगशक्ति को देखो! मेरा आत्मा सब प्राणियों का पालन करता है और उन्हें उत्पन्न करता है, फिर भी उनमें स्थित नहीं है।"
},
"gita_ch9_v6": {
  en: "Just as the mighty wind, moving everywhere, always rests in space, understand that in the same way all beings rest in Me.",
  te: "అంతటా సంచరించే మహా వాయువు ఎప్పుడూ ఆకాశంలోనే ఉన్నట్లు, ప్రాణులన్నీ అలాగే నాలో ఉన్నాయని గ్రహించు.",
  hi: "जैसे सर्वत्र बहने वाली महान वायु सदा आकाश में ही स्थित रहती है, वैसे ही सब प्राणी मुझमें स्थित हैं — ऐसा समझो।"
},
"gita_ch9_v7": {
  en: "Kaunteya, at the end of a cosmic cycle all beings merge into My own Prakṛti (nature); at the beginning of the next cycle I send them forth again.",
  te: "కౌంతేయా! కల్పం ముగిసినప్పుడు ప్రాణులన్నీ నా ప్రకృతిలో లీనమవుతాయి; కొత్త కల్పం ఆరంభంలో వాటిని నేను మళ్ళీ సృష్టిస్తాను.",
  hi: "हे कौंतेय! कल्प के अंत में सब प्राणी मेरी प्रकृति में लीन हो जाते हैं; अगले कल्प के आरंभ में मैं उन्हें फिर से रचता हूँ।"
},
"gita_ch9_v8": {
  en: "Taking hold of My own Prakṛti, I send forth again and again this whole multitude of beings, who are helpless under the sway of nature.",
  te: "నా ప్రకృతిని ఆధారం చేసుకుని, ప్రకృతి వశంలో నిస్సహాయంగా ఉన్న ఈ ప్రాణి సమూహాన్నంతటినీ నేను మళ్ళీ మళ్ళీ సృష్టిస్తాను.",
  hi: "अपनी प्रकृति का सहारा लेकर मैं प्रकृति के वश में विवश इस समस्त प्राणी-समूह को बार-बार रचता हूँ।"
},
"gita_ch9_v9": {
  en: "Dhanañjaya, these actions do not bind Me, because I remain like one who sits apart, unattached to them.",
  te: "ధనంజయా! ఈ కర్మలు నన్ను బంధించవు, ఎందుకంటే నేను వాటిపై ఆసక్తి లేకుండా, ఉదాసీనుడిలా ఉంటాను.",
  hi: "हे धनंजय! ये कर्म मुझे नहीं बाँधते, क्योंकि मैं उनमें आसक्ति रखे बिना उदासीन की तरह स्थित रहता हूँ।"
},
"gita_ch9_v10": {
  en: "Under My watchful presence, Prakṛti gives birth to all that moves and all that does not move. Because of this, Kaunteya, the world keeps turning.",
  te: "నా పర్యవేక్షణలో ప్రకృతి చరాచర జగత్తునంతటినీ పుట్టిస్తుంది. కౌంతేయా! ఈ కారణం చేతనే లోకం తిరుగుతూ ఉంటుంది.",
  hi: "मेरी अध्यक्षता में प्रकृति चर-अचर सबको उत्पन्न करती है। हे कौंतेय! इसी कारण यह जगत चक्र की तरह घूमता रहता है।"
},
"gita_ch9_v11": {
  en: "Fools disregard Me when I take a human form, not knowing My higher nature as the great Lord of all beings.",
  te: "నేను మానవ రూపం ధరించినప్పుడు, ప్రాణులన్నిటికీ మహేశ్వరుడనైన నా పరమ స్వభావాన్ని తెలియని మూఢులు నన్ను చిన్నచూపు చూస్తారు.",
  hi: "जब मैं मनुष्य का शरीर धारण करता हूँ, तब सब प्राणियों के महान ईश्वर के रूप में मेरे परम भाव को न जानने वाले मूढ़ लोग मेरी उपेक्षा करते हैं।"
},
"gita_ch9_v12": {
  en: "Their hopes are in vain, their actions are in vain, their knowledge is in vain, and their minds are confused; they cling to a deluding nature that is cruel and demonic.",
  te: "వారి ఆశలు వ్యర్థం, వారి కర్మలు వ్యర్థం, వారి జ్ఞానం వ్యర్థం, వారి బుద్ధి చెదిరిపోయి ఉంటుంది; మోహంలో ముంచే రాక్షస, అసుర స్వభావాన్ని వారు ఆశ్రయిస్తారు.",
  hi: "उनकी आशाएँ व्यर्थ, कर्म व्यर्थ और ज्ञान व्यर्थ होता है, उनकी बुद्धि भ्रमित रहती है; वे मोह में डालने वाले राक्षसी और आसुरी स्वभाव का आश्रय लेते हैं।"
},
"gita_ch9_v13": {
  en: "But great souls, Pārtha, who take refuge in the divine nature, worship Me with undivided minds, knowing Me as the imperishable source of all beings.",
  te: "కానీ పార్థా! దైవీ స్వభావాన్ని ఆశ్రయించిన మహాత్ములు, నన్ను సర్వ ప్రాణులకూ మూలమైనవాడిగా, నాశనం లేనివాడిగా తెలుసుకుని, ఏకాగ్రమైన మనసుతో నన్ను భజిస్తారు.",
  hi: "परंतु हे पार्थ! दैवी स्वभाव का आश्रय लेने वाले महात्मा मुझे सब प्राणियों का अविनाशी आदि कारण जानकर, अनन्य मन से मेरा भजन करते हैं।"
},
"gita_ch9_v14": {
  en: "Always singing My glory, striving with firm resolve, and bowing to Me with devotion, they worship Me, ever united with Me.",
  te: "ఎల్లప్పుడూ నా కీర్తిని గానం చేస్తూ, దృఢమైన వ్రతంతో ప్రయత్నిస్తూ, భక్తితో నాకు నమస్కరిస్తూ, నిత్యం నాతో కూడి వారు నన్ను ఉపాసిస్తారు.",
  hi: "सदा मेरा कीर्तन करते हुए, दृढ़ संकल्प के साथ प्रयत्न करते हुए और भक्ति से मुझे नमस्कार करते हुए, वे सदा मुझसे जुड़े रहकर मेरी उपासना करते हैं।"
},
"gita_ch9_v15": {
  en: "Others worship Me through the offering of knowledge — some as the One, some as distinct from themselves, and some in many ways, as the One whose faces are everywhere.",
  te: "మరికొందరు జ్ఞానయజ్ఞంతో నన్ను ఆరాధిస్తారు — కొందరు నన్ను తమతో ఏకమైనవాడిగా, కొందరు వేరైనవాడిగా, మరికొందరు అంతటా ముఖాలు కలిగిన విశ్వరూపుడిగా అనేక విధాలుగా ఉపాసిస్తారు.",
  hi: "कुछ अन्य ज्ञान-यज्ञ के द्वारा मेरी उपासना करते हैं — कुछ मुझे एक मानकर, कुछ अलग मानकर, और कुछ अनेक प्रकार से, सब ओर मुख वाले विश्वरूप के रूप में।"
},
"gita_ch9_v16": {
  en: "I am the ritual, I am the sacrifice, I am the offering to the ancestors, I am the healing herb. I am the mantra, I am the ghee, I am the fire, and I am the act of offering.",
  te: "క్రతువును నేనే, యజ్ఞాన్ని నేనే, పితరులకు ఇచ్చే స్వధను నేనే, ఔషధాన్ని నేనే. మంత్రాన్ని నేనే, నెయ్యిని నేనే, అగ్నిని నేనే, హోమం చేసే క్రియను కూడా నేనే.",
  hi: "मैं ही क्रतु हूँ, मैं ही यज्ञ हूँ, पितरों को दी जाने वाली स्वधा मैं हूँ, औषधि मैं हूँ। मंत्र मैं हूँ, घी मैं हूँ, अग्नि मैं हूँ और आहुति देने की क्रिया भी मैं ही हूँ।"
},
"gita_ch9_v17": {
  en: "I am the father of this world, its mother, its sustainer and its grandsire. I am what is to be known, the purifier, the sacred syllable Om, and the Ṛg, Sāma and Yajur Vedas.",
  te: "ఈ జగత్తుకు తండ్రిని నేనే, తల్లిని నేనే, పోషించేవాడిని నేనే, తాతను నేనే. తెలుసుకోవలసినది నేనే, పవిత్రం చేసేది నేనే, ఓంకారం నేనే, ఋగ్, సామ, యజుర్వేదాలు కూడా నేనే.",
  hi: "इस जगत का पिता मैं हूँ, माता मैं हूँ, धारण करने वाला मैं हूँ, पितामह मैं हूँ। जानने योग्य मैं हूँ, पवित्र करने वाला मैं हूँ, ओंकार मैं हूँ, और ऋग्, साम तथा यजुर्वेद भी मैं ही हूँ।"
},
"gita_ch9_v18": {
  en: "I am the goal, the supporter, the master, the witness, the home, the refuge and the friend. I am the origin and the dissolution, the ground, the treasure-house, and the imperishable seed.",
  te: "గమ్యం నేనే, భరించేవాడిని నేనే, ప్రభువును నేనే, సాక్షిని నేనే, నివాసం నేనే, శరణం నేనే, మిత్రుడిని నేనే. పుట్టుక, లయం, ఆధారం, నిధి, నాశనం లేని బీజం — అన్నీ నేనే.",
  hi: "गति मैं हूँ, भरण करने वाला मैं हूँ, स्वामी, साक्षी, निवास, शरण और सुहृद मैं हूँ। उत्पत्ति और प्रलय, आधार, निधान और अविनाशी बीज भी मैं ही हूँ।"
},
"gita_ch9_v19": {
  en: "I give heat; I hold back the rain and send it forth. I am immortality and also death, Arjuna; I am both what is and what is not.",
  te: "వేడిని ఇచ్చేది నేనే; వర్షాన్ని ఆపేది, కురిపించేది నేనే. అర్జునా! అమృతమూ నేనే, మృత్యువూ నేనే; ఉన్నదీ నేనే, లేనిదీ నేనే.",
  hi: "मैं ही तपता हूँ; मैं ही वर्षा को रोकता और बरसाता हूँ। हे अर्जुन! अमृत भी मैं हूँ और मृत्यु भी; सत् भी मैं हूँ और असत् भी।"
},
"gita_ch9_v20": {
  en: "Those who follow the three Vedas, drink the soma and are cleansed of sin worship Me through sacrifices and pray for heaven. Reaching the holy world of Indra, they enjoy the divine pleasures of the gods.",
  te: "మూడు వేదాలను అనుసరించేవారు, సోమపానం చేసి పాపాలు పోగొట్టుకున్నవారు యజ్ఞాలతో నన్ను ఆరాధించి స్వర్గాన్ని కోరుకుంటారు. పుణ్యమైన ఇంద్రలోకాన్ని చేరి, అక్కడ దేవతల దివ్య భోగాలను అనుభవిస్తారు.",
  hi: "तीनों वेदों का पालन करने वाले, सोमपान करके पापों से शुद्ध हुए लोग यज्ञों से मेरी पूजा करके स्वर्ग की प्रार्थना करते हैं। वे पुण्यमय इंद्रलोक को पाकर वहाँ देवताओं के दिव्य भोग भोगते हैं।"
},
"gita_ch9_v21": {
  en: "Having enjoyed that vast heaven, when their merit is used up they enter the world of mortals again. So those who follow the Vedic rituals out of desire for pleasures keep coming and going.",
  te: "ఆ విశాలమైన స్వర్గాన్ని అనుభవించి, పుణ్యం తీరిపోగానే మళ్ళీ మర్త్యలోకంలోకి వస్తారు. ఇలా భోగాలను కోరి వేద కర్మలను అనుసరించేవారు రాకపోకలే పొందుతారు.",
  hi: "उस विशाल स्वर्ग को भोगकर पुण्य समाप्त होने पर वे फिर मृत्युलोक में आ जाते हैं। इस प्रकार भोगों की कामना से वैदिक कर्मों का पालन करने वाले आते-जाते ही रहते हैं।"
},
"gita_ch9_v22": {
  en: "Those who think of Me alone and worship Me with no other thought — for them, who are always united with Me, I Myself bring what they need and protect what they have.",
  te: "ఇంకేమీ ఆలోచించకుండా నన్నే చింతిస్తూ ఉపాసించేవారు — నిత్యం నాతో కూడి ఉన్న వారి యోగక్షేమాలను నేనే స్వయంగా చూసుకుంటాను.",
  hi: "जो लोग अनन्य भाव से मेरा ही चिंतन करते हुए मेरी उपासना करते हैं — सदा मुझसे जुड़े उन भक्तों का योगक्षेम मैं स्वयं वहन करता हूँ।"
},
"gita_ch9_v23": {
  en: "Even those devotees who worship other gods with faith are really worshipping Me alone, Kaunteya, though not in the proper way.",
  te: "కౌంతేయా! శ్రద్ధతో ఇతర దేవతలను పూజించే భక్తులు కూడా నిజానికి నన్నే పూజిస్తున్నారు, కానీ సరైన విధానంలో కాదు.",
  hi: "हे कौंतेय! जो भक्त श्रद्धा के साथ अन्य देवताओं की पूजा करते हैं, वे भी वास्तव में मेरी ही पूजा करते हैं, परंतु विधिपूर्वक नहीं।"
},
"gita_ch9_v24": {
  en: "For I alone am the enjoyer and the Lord of all sacrifices. But they do not know Me as I truly am, and so they fall back.",
  te: "ఎందుకంటే యజ్ఞాలన్నిటినీ స్వీకరించేవాడిని, వాటికి ప్రభువును నేనే. కానీ వారు నన్ను యథార్థంగా తెలుసుకోరు, అందుకే మళ్ళీ కిందికి జారిపోతారు.",
  hi: "क्योंकि सब यज्ञों का भोक्ता और स्वामी मैं ही हूँ। परंतु वे मुझे तत्त्व से नहीं जानते, इसलिए वे फिर गिर जाते हैं।"
},
"gita_ch9_v25": {
  en: "Those devoted to the gods go to the gods; those devoted to the ancestors go to the ancestors; those who worship spirits go to the spirits; and those who worship Me come to Me.",
  te: "దేవతలను ఆరాధించేవారు దేవతలను చేరుకుంటారు; పితరులను ఆరాధించేవారు పితరులను చేరుకుంటారు; భూతాలను పూజించేవారు భూతాలను చేరుకుంటారు; నన్ను పూజించేవారు నన్నే చేరుకుంటారు.",
  hi: "देवताओं के उपासक देवताओं को प्राप्त होते हैं, पितरों के उपासक पितरों को, भूतों के पूजक भूतों को, और मेरी पूजा करने वाले मुझे ही प्राप्त होते हैं।"
},
"gita_ch9_v26": {
  en: "Whoever offers Me with devotion a leaf, a flower, a fruit or a little water — that offering of love from a pure heart, I gladly accept.",
  te: "ఎవరైనా భక్తితో నాకు ఒక ఆకును, ఒక పువ్వును, ఒక పండును లేదా కొంచెం నీటిని సమర్పిస్తే — పవిత్ర హృదయంతో ప్రేమగా ఇచ్చిన ఆ కానుకను నేను ఆనందంగా స్వీకరిస్తాను.",
  hi: "जो कोई भक्ति से मुझे एक पत्ता, एक फूल, एक फल या थोड़ा-सा जल अर्पित करता है — शुद्ध मन वाले उस भक्त का प्रेम से दिया हुआ वह उपहार मैं प्रसन्नता से स्वीकार करता हूँ।"
},
"gita_ch9_v27": {
  en: "Whatever you do, whatever you eat, whatever you offer in sacrifice, whatever you give, whatever discipline you practise, Kaunteya — do it as an offering to Me.",
  te: "కౌంతేయా! నువ్వు ఏది చేసినా, ఏది తిన్నా, ఏది హోమం చేసినా, ఏది దానం చేసినా, ఏ తపస్సు చేసినా — దానిని నాకు అర్పణగా చేయి.",
  hi: "हे कौंतेय! तुम जो कुछ करते हो, जो खाते हो, जो हवन करते हो, जो दान देते हो और जो तप करते हो — वह सब मुझे अर्पण करके करो।"
},
"gita_ch9_v28": {
  en: "In this way you will be freed from the bonds of action and their good and bad results. With your mind set on renunciation and yoga, you will be liberated and come to Me.",
  te: "ఇలా చేస్తే, మంచి చెడు ఫలాలను ఇచ్చే కర్మబంధాల నుండి నువ్వు విడుదల పొందుతావు. సన్యాస యోగంతో కూడిన మనసుతో విముక్తుడవై నన్నే చేరుకుంటావు.",
  hi: "इस प्रकार तुम शुभ-अशुभ फल देने वाले कर्मबंधनों से मुक्त हो जाओगे। संन्यास-योग से युक्त मन वाले होकर, मुक्त होकर तुम मुझे ही प्राप्त होगे।"
},
"gita_ch9_v29": {
  en: "I am the same towards all beings; no one is hateful to Me and no one is a favourite. But those who worship Me with devotion are in Me, and I am in them.",
  te: "నేను ప్రాణులన్నిటి పట్లా సమానంగా ఉంటాను; నాకు ద్వేషించదగినవాడూ లేడు, ప్రత్యేకంగా ప్రియమైనవాడూ లేడు. కానీ భక్తితో నన్ను భజించేవారు నాలో ఉంటారు, నేను వారిలో ఉంటాను.",
  hi: "मैं सब प्राणियों के प्रति समान हूँ; न मेरा कोई द्वेष का पात्र है, न कोई विशेष प्रिय। परंतु जो भक्ति से मेरा भजन करते हैं, वे मुझमें हैं और मैं उनमें हूँ।"
},
"gita_ch9_v30": {
  en: "Even if a person of very bad conduct worships Me with undivided devotion, he should be regarded as good, for he has made the right resolve.",
  te: "చాలా చెడు నడవడిక ఉన్నవాడైనా సరే, అనన్య భక్తితో నన్ను భజిస్తే, అతడిని సాధువుగానే భావించాలి, ఎందుకంటే అతడు సరైన నిర్ణయం తీసుకున్నాడు.",
  hi: "यदि अत्यंत दुराचारी व्यक्ति भी अनन्य भक्ति से मेरा भजन करता है, तो उसे साधु ही मानना चाहिए, क्योंकि उसने सही निश्चय कर लिया है।"
},
"gita_ch9_v31": {
  en: "He quickly becomes righteous and attains lasting peace. Kaunteya, declare it boldly: My devotee never perishes.",
  te: "అతడు త్వరలోనే ధర్మాత్ముడై శాశ్వతమైన శాంతిని పొందుతాడు. కౌంతేయా! ధైర్యంగా ప్రకటించు: నా భక్తుడు ఎన్నడూ నశించడు.",
  hi: "वह शीघ्र ही धर्मात्मा बन जाता है और स्थायी शांति प्राप्त करता है। हे कौंतेय! निश्चय के साथ घोषणा करो: मेरा भक्त कभी नष्ट नहीं होता।"
},
"gita_ch9_v32": {
  en: "Pārtha, whoever takes refuge in Me — even those born in humble circumstances, women, vaiśyas and śūdras — they too reach the supreme goal.",
  te: "పార్థా! నన్ను ఆశ్రయించినవారు ఎవరైనా — తక్కువగా భావించబడే జన్మలో పుట్టినవారైనా, స్త్రీలైనా, వైశ్యులైనా, శూద్రులైనా — వారు కూడా పరమ గతిని పొందుతారు.",
  hi: "हे पार्थ! जो कोई मेरी शरण लेता है — चाहे वह नीची मानी जाने वाली योनि में जन्मा हो, या स्त्री, वैश्य या शूद्र हो — वे भी परम गति को प्राप्त होते हैं।"
},
"gita_ch9_v33": {
  en: "How much more, then, the pure brāhmaṇas and devoted royal sages! Having come into this passing and joyless world, worship Me.",
  te: "అలాంటప్పుడు పుణ్యాత్ములైన బ్రాహ్మణులు, భక్తులైన రాజర్షుల సంగతి వేరే చెప్పాలా! శాశ్వతం కాని, సుఖం లేని ఈ లోకంలోకి వచ్చావు కాబట్టి నన్ను భజించు.",
  hi: "तो फिर पुण्यात्मा ब्राह्मणों और भक्त राजर्षियों का कहना ही क्या! इस अनित्य और सुखरहित संसार में आकर तुम मेरा भजन करो।"
},
"gita_ch9_v34": {
  en: "Fix your mind on Me, be devoted to Me, worship Me, bow down to Me. Uniting yourself with Me in this way, with Me as your highest goal, you will surely come to Me.",
  te: "నీ మనసును నాపై నిలుపు, నా భక్తుడివి కా, నన్ను పూజించు, నాకు నమస్కరించు. ఇలా నన్నే పరమ గమ్యంగా చేసుకుని నాతో నిన్ను కలుపుకుంటే, నువ్వు తప్పకుండా నన్నే చేరుకుంటావు.",
  hi: "अपना मन मुझमें लगाओ, मेरे भक्त बनो, मेरी पूजा करो, मुझे नमस्कार करो। इस प्रकार मुझे ही परम लक्ष्य बनाकर स्वयं को मुझसे जोड़ोगे, तो तुम निश्चय ही मुझे प्राप्त होगे।"
},

// ── Chapter 12 · Bhakti Yoga ──
"gita_ch12_v1": {
  en: "Arjuna asked: Some devotees are always united with You and worship You in Your personal form. Others worship the Imperishable, the Unmanifest. Of these two kinds, who knows yoga best?",
  te: "అర్జునుడు అడిగాడు: కొందరు భక్తులు ఎల్లప్పుడూ నీతో ఏకమై, సగుణ రూపంలో నిన్ను ఉపాసిస్తారు. మరికొందరు అక్షరమైన, అవ్యక్తమైన పరబ్రహ్మను ఉపాసిస్తారు. ఈ ఇద్దరిలో యోగాన్ని బాగా తెలిసినవారు ఎవరు?",
  hi: "अर्जुन ने पूछा: कुछ भक्त सदा आपसे जुड़े रहकर आपके साकार रूप की उपासना करते हैं। कुछ अन्य अविनाशी, अव्यक्त ब्रह्म की उपासना करते हैं। इन दोनों में योग को सबसे अच्छी तरह जानने वाले कौन हैं?"
},
"gita_ch12_v2": {
  en: "The Lord said: Those who fix their minds on Me, worship Me with constant devotion and are filled with supreme faith — I consider them the most perfect in yoga.",
  te: "శ్రీ భగవానుడు అన్నాడు: మనసును నా యందే నిలిపి, నిత్యం నాతో కూడి, పరమ శ్రద్ధతో నన్ను ఉపాసించేవారే యోగంలో అత్యుత్తములని నా అభిప్రాయం.",
  hi: "श्री भगवान ने कहा: जो अपना मन मुझमें लगाकर, सदा मुझसे जुड़े रहकर, परम श्रद्धा के साथ मेरी उपासना करते हैं — उन्हें मैं योग में सबसे श्रेष्ठ मानता हूँ।"
},
"gita_ch12_v3": {
  en: "But those who worship the Imperishable — which cannot be described, cannot be seen, is everywhere, beyond thought, unchanging, unmoving and eternal —",
  te: "కానీ వర్ణించడానికి వీలుకాని, కంటికి కనిపించని, అంతటా వ్యాపించి ఉన్న, ఆలోచనకు అందని, మార్పు లేని, కదలని, శాశ్వతమైన అక్షర బ్రహ్మను ఉపాసించేవారు —",
  hi: "परंतु जो उस अविनाशी की उपासना करते हैं — जिसका वर्णन नहीं हो सकता, जो दिखाई नहीं देता, सर्वत्र व्याप्त है, विचार से परे है, अपरिवर्तनशील, अचल और नित्य है —"
},
"gita_ch12_v4": {
  en: "— having controlled all their senses, seeing everything with an equal mind, and delighting in the welfare of all beings, they too reach Me alone.",
  te: "— ఇంద్రియాలన్నిటినీ అదుపులో ఉంచుకుని, అంతటా సమబుద్ధితో, సర్వ ప్రాణుల హితంలోనే ఆనందించేవారు — వారు కూడా నన్నే చేరుకుంటారు.",
  hi: "— अपनी सब इंद्रियों को वश में करके, सर्वत्र समान बुद्धि रखते हुए, सब प्राणियों के हित में लगे रहने वाले — वे भी मुझे ही प्राप्त होते हैं।"
},
"gita_ch12_v5": {
  en: "But the struggle is greater for those whose minds are set on the Unmanifest. For embodied beings, the path to the Unmanifest is hard to walk.",
  te: "అయితే అవ్యక్తం మీద మనసు నిలిపేవారికి శ్రమ ఇంకా ఎక్కువ. దేహాభిమానం ఉన్న మనుషులకు అవ్యక్త మార్గంలో నడవడం చాలా కష్టం.",
  hi: "परंतु जिनका मन अव्यक्त में लगा है, उनका परिश्रम अधिक है। देहधारी मनुष्यों के लिए अव्यक्त का मार्ग कठिनाई से पार होता है।"
},
"gita_ch12_v6": {
  en: "But those who offer all their actions to Me, hold Me as the highest goal, and worship Me with single-minded devotion, always meditating on Me —",
  te: "కానీ తమ కర్మలన్నిటినీ నాకు అర్పించి, నన్నే పరమ గమ్యంగా భావించి, వేరే ఆలోచన లేని భక్తితో నన్నే ధ్యానిస్తూ ఉపాసించేవారు —",
  hi: "परंतु जो अपने सब कर्म मुझे अर्पित करके, मुझे ही परम लक्ष्य मानकर, अनन्य भक्ति से मेरा ही ध्यान करते हुए उपासना करते हैं —"
},
"gita_ch12_v7": {
  en: "— for them, whose minds have entered into Me, O Pārtha, I soon become the one who lifts them out of the ocean of death and rebirth.",
  te: "— పార్థా! మనసును నా యందే లీనం చేసిన అలాంటివారిని మృత్యువుతో నిండిన సంసార సముద్రం నుండి నేనే త్వరలో ఉద్ధరిస్తాను.",
  hi: "— हे पार्थ! जिनका मन मुझमें लीन है, उन्हें मृत्युरूपी संसार-सागर से मैं शीघ्र ही उबार लेता हूँ।"
},
"gita_ch12_v8": {
  en: "Fix your mind on Me alone; let your understanding rest in Me. Then you will surely live in Me from now on — there is no doubt.",
  te: "నీ మనసును నా యందే నిలుపు; నీ బుద్ధిని నా యందే ఉంచు. ఆ తర్వాత నువ్వు నా యందే నివసిస్తావు — ఇందులో సందేహం లేదు.",
  hi: "अपना मन मुझमें ही लगाओ, अपनी बुद्धि मुझमें ही स्थिर करो। इसके बाद तुम मुझमें ही निवास करोगे — इसमें कोई संदेह नहीं।"
},
"gita_ch12_v9": {
  en: "If you cannot hold your mind steadily on Me, then seek to reach Me by the yoga of practice — bringing the mind back to Me again and again, O Dhanañjaya.",
  te: "ధనంజయా! మనసును నా మీద స్థిరంగా నిలపలేకపోతే, అభ్యాస యోగంతో — మళ్ళీ మళ్ళీ మనసును నా వైపుకు మళ్ళిస్తూ — నన్ను చేరాలని ప్రయత్నించు.",
  hi: "हे धनंजय! यदि तुम मन को मुझमें स्थिर नहीं रख सकते, तो अभ्यास-योग से — मन को बार-बार मेरी ओर लौटाते हुए — मुझे पाने का प्रयत्न करो।"
},
"gita_ch12_v10": {
  en: "If you cannot even practise like that, make working for Me your highest aim. Even by doing your actions for My sake, you will reach perfection.",
  te: "అభ్యాసం కూడా చేయలేకపోతే, నా కోసం పని చేయడాన్నే పరమ లక్ష్యంగా పెట్టుకో. నా కోసమే కర్మలు చేస్తున్నా కూడా నువ్వు సిద్ధిని పొందుతావు.",
  hi: "यदि अभ्यास भी न कर सको, तो मेरे लिए कर्म करना ही अपना परम लक्ष्य बना लो। मेरे लिए कर्म करते हुए भी तुम सिद्धि पा लोगे।"
},
"gita_ch12_v11": {
  en: "If you cannot do even this, then take refuge in Me, master yourself, and give up the fruits of all your actions.",
  te: "ఇది కూడా చేయలేకపోతే, నన్ను ఆశ్రయించి, మనసును అదుపులో ఉంచుకుని, నీ కర్మలన్నిటి ఫలాన్ని త్యాగం చెయ్యి.",
  hi: "यदि यह भी न कर सको, तो मेरी शरण लेकर, मन को वश में करके, सब कर्मों के फल का त्याग कर दो।"
},
"gita_ch12_v12": {
  en: "Knowledge is better than mechanical practice; meditation is better than knowledge; giving up the fruits of action is better than meditation — for peace follows that giving up at once.",
  te: "యాంత్రికమైన అభ్యాసం కంటే జ్ఞానం శ్రేష్ఠం; జ్ఞానం కంటే ధ్యానం గొప్పది; ధ్యానం కంటే కర్మఫల త్యాగం గొప్పది — ఎందుకంటే ఆ త్యాగం వల్ల వెంటనే శాంతి కలుగుతుంది.",
  hi: "यांत्रिक अभ्यास से ज्ञान श्रेष्ठ है; ज्ञान से ध्यान श्रेष्ठ है; ध्यान से कर्मफल का त्याग श्रेष्ठ है — क्योंकि त्याग से तुरंत शांति मिलती है।"
},
"gita_ch12_v13": {
  en: "One who hates no being, who is friendly and compassionate, free from 'mine' and free from ego, the same in pain and pleasure, and forgiving —",
  te: "ఏ ప్రాణినీ ద్వేషించనివాడు, అందరితో స్నేహంగా, దయగా ఉండేవాడు, ‘నాది’ అనే మమకారం, ‘నేను’ అనే అహంకారం లేనివాడు, సుఖదుఃఖాలలో సమంగా ఉండేవాడు, ఓర్పు గలవాడు —",
  hi: "जो किसी प्राणी से द्वेष नहीं करता, सबका मित्र और दयालु है, 'मेरा' और 'मैं' के भाव से मुक्त है, सुख-दुःख में समान है और क्षमाशील है —"
},
"gita_ch12_v14": {
  en: "— ever content, a yogī with self-control and firm resolve, whose mind and understanding are offered to Me — such a devotee of Mine is dear to Me.",
  te: "— ఎల్లప్పుడూ సంతృప్తిగా ఉండే యోగి, తనను తాను అదుపులో ఉంచుకున్నవాడు, దృఢ నిశ్చయం గలవాడు, మనసునూ బుద్ధినీ నాకు అర్పించినవాడు — అలాంటి నా భక్తుడు నాకు ప్రియుడు.",
  hi: "— जो सदा संतुष्ट योगी है, संयमी है, दृढ़ निश्चय वाला है, जिसने मन और बुद्धि मुझे अर्पित कर दी है — ऐसा मेरा भक्त मुझे प्रिय है।"
},
"gita_ch12_v15": {
  en: "One by whom the world is not disturbed, and who is not disturbed by the world; who is free from excitement, envy, fear and anxiety — that one is dear to Me.",
  te: "ఎవరి వల్ల లోకానికి కలవరం కలగదో, లోకం వల్ల ఎవరికి కలవరం కలగదో, హర్షం, అసూయ, భయం, ఉద్వేగాల నుండి విముక్తుడైనవాడు — అతడు నాకు ప్రియుడు.",
  hi: "जिससे संसार व्याकुल नहीं होता और जो संसार से व्याकुल नहीं होता, जो हर्ष, ईर्ष्या, भय और उद्वेग से मुक्त है — वह मुझे प्रिय है।"
},
"gita_ch12_v16": {
  en: "One who wants nothing, who is pure and capable, who stays unattached and untroubled, and who has given up all self-centred undertakings — such a devotee of Mine is dear to Me.",
  te: "దేనినీ ఆశించనివాడు, పవిత్రుడు, సమర్థుడు, పక్షపాతం లేనివాడు, బాధ లేనివాడు, స్వార్థంతో మొదలుపెట్టే ప్రయత్నాలన్నిటినీ విడిచినవాడు — అలాంటి నా భక్తుడు నాకు ప్రియుడు.",
  hi: "जो किसी चीज़ की अपेक्षा नहीं रखता, पवित्र और कुशल है, तटस्थ और व्यथा-रहित है, स्वार्थ से शुरू किए गए सब कार्यों का त्यागी है — ऐसा मेरा भक्त मुझे प्रिय है।"
},
"gita_ch12_v17": {
  en: "One who neither rejoices nor hates, neither grieves nor craves, and who has let go of both good and bad outcomes — that devotee is dear to Me.",
  te: "హర్షించనివాడు, ద్వేషించనివాడు, శోకించనివాడు, కోరుకోనివాడు, శుభాశుభ ఫలాలు రెండింటినీ విడిచిపెట్టినవాడు — అలాంటి భక్తుడు నాకు ప్రియుడు.",
  hi: "जो न हर्षित होता है, न द्वेष करता है, न शोक करता है, न कामना करता है, और जिसने शुभ-अशुभ दोनों का त्याग कर दिया है — वह भक्त मुझे प्रिय है।"
},
"gita_ch12_v18": {
  en: "One who is the same to enemy and friend, the same in honour and dishonour, the same in cold and heat, pleasure and pain, and free from attachment —",
  te: "శత్రువు పట్ల, మిత్రుని పట్ల ఒకేలా ఉండేవాడు; మానావమానాలలో, చలి వేడిలలో, సుఖదుఃఖాలలో సమంగా ఉండేవాడు; సంగం (ఆసక్తి) లేనివాడు —",
  hi: "जो शत्रु और मित्र के प्रति, मान और अपमान में, सर्दी-गर्मी और सुख-दुःख में समान रहता है, और आसक्ति से रहित है —"
},
"gita_ch12_v19": {
  en: "— the same in blame and praise, quiet, content with whatever comes, not attached to any home, steady of mind and full of devotion — that person is dear to Me.",
  te: "— నిందనూ స్తుతినీ సమానంగా తీసుకునేవాడు, మౌనంగా ఉండేవాడు, దొరికినదానితో తృప్తి పడేవాడు, ఏ ఇంటికీ కట్టుబడనివాడు, స్థిరమైన మనసు గలవాడు, భక్తి గలవాడు — ఆ మనిషి నాకు ప్రియుడు.",
  hi: "— जो निंदा और स्तुति को समान मानता है, मौन रहता है, जो कुछ मिले उसी में संतुष्ट है, किसी घर से बंधा नहीं, स्थिर बुद्धि वाला और भक्तिमान है — वह मनुष्य मुझे प्रिय है।"
},
"gita_ch12_v20": {
  en: "But those who follow this immortal teaching of dharma just as I have given it, with faith, holding Me as their highest goal — those devotees are exceedingly dear to Me.",
  te: "నేను చెప్పిన ఈ ధర్మమయమైన అమృతాన్ని శ్రద్ధతో, నన్నే పరమ గమ్యంగా భావించి, యథాతథంగా ఆచరించే భక్తులు — వారు నాకు అత్యంత ప్రియులు.",
  hi: "परंतु जो श्रद्धा के साथ, मुझे परम लक्ष्य मानकर, मेरे बताए इस धर्ममय अमृत का ठीक वैसे ही पालन करते हैं — वे भक्त मुझे अत्यंत प्रिय हैं।"
}

});
